// Generated by scripts/gen-l10n.mjs (gdetail n3, vi) — 不要手改;改翻譯請改 scripts/out/l10n/vi/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["vi"]=Object.assign(window.GRAMMAR_DETAIL_L10N["vi"]||{},{"n3-42":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜わけがない」tương đương với tiếng Việt <b>「làm gì có chuyện ～」「sao có thể ～ được」</b>. Ở đây 「わけ」 mang nghĩa là \"lẽ phải, lý lẽ\", nên 「わけがない」 nghĩa đen là \"không có lẽ nào như vậy\". Ý của nó là bạn đang khẳng định chắc chắn: chuyện này <b>hoàn toàn không thể xảy ra</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Khẳng định không thể</span>Dựa vào lẽ thường, hoặc dựa vào sự hiểu biết của bạn về một người nào đó, bạn thấy chuyện này tuyệt đối không thể xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに簡単に成功するわけがない。</span>（Làm gì có chuyện thành công dễ dàng như vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな値段で本物が手に入るわけがない。</span>（Với giá này thì không thể nào mua được hàng thật）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるわけがない。</span>（Đã luyện tập chăm chỉ như thế thì không thể nào thua được）</div><div class='gd-sec'><span class='gd-tag'>Phản bác đối phương</span>Khi nói chuyện với bạn bè, bạn đáp lại kiểu \"làm gì có chuyện đó\". Trong văn nói, người ta hay bỏ 「が」 và nói thành 「わけない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>宝くじなんて、当たるわけないよ。</span>（Xổ số ấy à, làm gì có chuyện trúng chứ）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなわけないでしょ。</span>（Làm gì có chuyện đó chứ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp, thể phủ định và thể quá khứ cũng dùng được.<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるわけがない</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないわけがない</span></span><br><b>Tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いわけがない</span></span><br><b>Tính từ な</b>: đổi 「だ」 thành 「な」.<br><span class='gd-pair'><span class='gd-jp'>好きだ</span> → <span class='gd-jp'>好きなわけがない</span></span><br><b>Danh từ</b>: đổi 「だ」 thành 「の」; nếu muốn trang trọng hơn thì dùng 「である」.<br><span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物のわけがない</span></span><br>Muốn nói lịch sự hơn, bạn dùng 「<span class='gd-jp'>わけがありません</span>」.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Với tính từ な và danh từ, không được giữ nguyên 「だ」 rồi nối tiếp: <span class='gd-jp'>好きだわけがない</span>、<span class='gd-jp'>本物だわけがない</span> đều sai.<br>・「〜ないわけがない」 là hai lần phủ định chồng lên nhau, nên nghĩa lại là <b>「chắc chắn sẽ」</b>: <span class='gd-jp'>彼が期限を守らないわけがない。</span>（Không thể nào anh ấy không giữ hạn chót = anh ấy chắc chắn sẽ giữ hạn chót）<br>・Tiếng Việt dùng \"không thể\" cho cả \"không thể nào xảy ra\" lẫn \"không tiện, không được phép\", nhưng tiếng Nhật tách hai ý này rất rõ. \"Mai thi rồi nên không thể đi chơi\" là bạn <b>không tiện, không nên</b> đi, phải dùng わけにはいかない: <span class='gd-jp'>明日は試験だから、遊びに行くわけにはいかない。</span>（Mai thi rồi nên không thể đi chơi được）Nếu viết <span class='gd-jp'>遊びに行くわけがない</span> thì nghĩa thành \"làm sao mình có thể đi chơi được chứ\".<br>・Sắc thái rất mạnh, có chút kiểu \"bạn đang nói gì ngớ ngẩn vậy\". Nếu đáp thẳng <span class='gd-jp'>そんなわけないです</span> với cấp trên hay người lớn tuổi thì sẽ khá gắt, bạn nên đổi thành <span class='gd-jp'>それはないと思います</span>.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Tình huống: bạn đưa bánh kem cho Tanaka, anh ấy bảo thôi không cần. Người bên cạnh hỏi bạn: \"Tanaka có phải ghét bánh kem không?\"<br><b>わけがない</b> = <b>phủ định mạnh</b>, giọng kiểu \"làm gì có chuyện đó\":</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんがケーキが嫌いなわけがないよ。毎日食べてるもん。</span>（Tanaka làm gì có chuyện ghét bánh kem, ngày nào anh ấy cũng ăn mà）</div><div class='gd-sec'><b>はずがない</b> = <b>suy luận theo lẽ thường</b> rằng sẽ không như vậy, giọng bình tĩnh hơn:</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは甘いものが大好きだから、ケーキが嫌いなはずがない。</span>（Tanaka rất thích đồ ngọt, nên theo lẽ thường thì không thể nào ghét bánh kem）</div><div class='gd-sec'>Nhiều lúc hai mẫu này dùng thay nhau được. Điểm khác là はずがない thiên về \"dựa vào manh mối đang có mà suy ra là không\", còn わけがない thiên về \"xét về lý lẽ thì vô lý\", và trong văn nói thì cảm xúc mạnh hơn.<br><b>わけではない</b> = <b>「không phải là ～」</b>, chỉ để chỉnh lại một hiểu lầm, hoàn toàn không có ý \"không thể nào\". Nếu để chính Tanaka giải thích thì anh ấy sẽ nói:</div><div class='gd-ex-line'>・<span class='gd-jp'>甘いものが嫌いなわけではない。今はおなかがいっぱいなだけだ。</span>（Không phải là tôi ghét đồ ngọt, chỉ là bây giờ tôi đang no thôi）</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"làm gì có chuyện\" thì dùng わけがない; muốn nói \"theo lẽ thường thì không thể\" thì dùng はずがない; muốn nói \"không phải là ～\" thì dùng わけではない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Họ 「わけ」 còn có: <span class='gd-jp'>わけではない</span>（không phải là ～）、<span class='gd-jp'>わけにはいかない</span>（không thể ～）. Thêm <span class='gd-jp'>はずがない</span> có nghĩa gần nhất nữa, học cùng nhau sẽ ít bị nhầm nhất.</div>","n3-43":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜わけではない」tương đương với tiếng Việt <b>「không phải là ～」「cũng không có nghĩa là ～」</b>. Có thể đối phương đang nghĩ là như vậy, và bạn lên tiếng làm rõ: \"không phải như bạn nghĩ đâu\". Nó khá giống câu người Việt hay nói: \"không phải là mình ghét đâu, chỉ là…\", và phía sau thường là lý do thật sự.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Làm rõ hiểu lầm</span>Đối phương có vẻ đã hiểu lầm bạn, và bạn nói cho rõ ràng.</div><div class='gd-ex-line'>・<span class='gd-jp'>反対しているわけではありません。ちょっと心配なだけです。</span>（Tôi không phải là phản đối, chỉ là hơi lo thôi）</div><div class='gd-ex-line'>・<span class='gd-jp'>別に怒っているわけじゃないよ。</span>（Mình đâu có đang giận đâu）</div><div class='gd-sec'><span class='gd-tag'>Không phải tất cả đều vậy</span>Dùng cùng với 「<span class='gd-jp'>みんな</span>」「<span class='gd-jp'>いつも</span>」「<span class='gd-jp'>全部</span>」, nghĩa là \"không nhất thiết lúc nào cũng vậy\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな納豆が好きなわけではない。</span>（Không phải người Nhật nào cũng thích natto）</div><div class='gd-ex-line'>・<span class='gd-jp'>高い服がいつもいいわけではない。</span>（Quần áo đắt không phải lúc nào cũng tốt hơn）</div><div class='gd-sec'><span class='gd-tag'>Từ chối khéo</span>Khi không muốn nói dứt khoát, bạn phủ định trước một hiểu lầm có thể xảy ra, rồi mới nêu lý do.</div><div class='gd-ex-line'>・<span class='gd-jp'>料理が嫌いなわけじゃないけど、毎日はちょっと…。</span>（Mình không phải ghét nấu ăn, chỉ là ngày nào cũng nấu thì hơi…）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt \"thể thông thường\", tức là cách nói không có ます (thể từ điển, thể ない, thể た đều dùng được).<br><b>Động từ</b>: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くわけではない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったわけではない</span></span><br><b>Tính từ い</b>: <span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいわけではない</span></span><br><b>Tính từ な</b>: phải thêm <b>な</b>　<span class='gd-pair'><span class='gd-jp'>嫌い</span> → <span class='gd-jp'>嫌いなわけではない</span></span><br><b>Danh từ</b>: thêm <b>な</b>, hoặc dùng 「という」　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生というわけではない</span></span></div><div class='gd-sec'>Khi nói chuyện, người ta hay nói thành <b>わけじゃない</b>; muốn lịch sự hơn thì nói <b>わけではありません</b> hoặc <b>わけじゃありません</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ <b>không được nối だ</b>: phải nói <span class='gd-jp'>嫌いなわけではない</span>, không được nói 「嫌いだわけではない」.<br>・「わけ」 ở đây không mang nghĩa \"lý do\", đừng dịch thành \"không có lý do\".<br>・Nó nhẹ nhàng hơn phủ định trực tiếp: <span class='gd-jp'>嫌いじゃない</span> là \"không ghét\", còn <span class='gd-jp'>嫌いなわけじゃない</span> là \"cũng không phải là ghét (mà có lý do khác)\", nên phía sau thường phải bổ sung một câu giải thích.<br>・Khi phía trước là thể phủ định thì thành phủ định kép: <span class='gd-jp'>行きたくないわけじゃない。</span>（Cũng không phải là không muốn đi）, nghĩa là thật ra cũng hơi muốn đi.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về chuyện một quán đắt hay không:<br><b>わけではない</b> = <b>không phải là</b>: <span class='gd-jp'>この店、高いわけではないけど、ちょっと遠い。</span>（Quán này không phải là đắt, chỉ là hơi xa）<br><b>わけがない</b> = <b>không thể nào</b>: <span class='gd-jp'>100円ショップだから、高いわけがない。</span>（Là cửa hàng 100 yên nên không thể nào đắt được）<br><b>わけだ</b> = <b>thảo nào</b>: <span class='gd-jp'>有名なシェフの店か。高いわけだ。</span>（Hóa ra là quán của đầu bếp nổi tiếng, thảo nào đắt thế）</div><div class='gd-warn'>Mẹo phân biệt: \"không phải là ～\" dùng わけではない, \"không thể nào ～\" dùng わけがない, \"thảo nào ～\" dùng わけだ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」（cũng không phải là không ～）có nghĩa gần với 「〜ないわけではない」, đều mang giọng \"miễn cưỡng thì cũng được\": <span class='gd-jp'>辛い料理も食べられないことはない。</span>（Món cay cũng không phải là không ăn được）</div>","n3-8":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にとって」nghĩa là <b>「đối với ～ thì」</b>. Bạn nói trước là đang đứng từ góc nhìn của ai, rồi mới nói việc đó với người ấy <b>quan trọng hay không, khó hay dễ, tốt hay không</b>. Cùng một việc, người khác nhìn vào có thể cảm nhận hoàn toàn khác, và にとって chính là để cho biết「đây là cảm nhận của ai」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私にとって、家族が一番大切です。</span>(Đối với tôi, gia đình là quan trọng nhất)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chỉ cần thêm にとって vào sau danh từ. Thường gặp nhất là đi với người, nhưng cũng có thể là động vật, công ty, quốc gia.<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私にとって</span></span><span class='gd-pair'><span class='gd-jp'>外国人</span> → <span class='gd-jp'>外国人にとって</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>外国人にとって、敬語は難しい。</span>(Đối với người nước ngoài, kính ngữ rất khó)</div><div class='gd-ex-line'>・<span class='gd-jp'>猫にとって、この部屋は暑すぎるかもしれない。</span>(Đối với mèo, căn phòng này có lẽ quá nóng)</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>にとって</span>có thể đặt ở đầu câu hoặc giữa câu, diễn tả việc này như thế nào「khi đứng ở lập trường của ai đó」. Phía sau có dấu phẩy hay không đều được.</div><div class='gd-ex-line'>・<span class='gd-jp'>この経験は私にとって大きな財産だ。</span>(Trải nghiệm này là một tài sản lớn đối với tôi)</div><div class='gd-sec'><span class='gd-tag'>にとっては</span>có thêm は nên mang sắc thái so sánh: 「với người này thì thế, còn với người khác thì chưa chắc」.</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にとっては短い時間でも、子供にとっては長い。</span>(Khoảng thời gian ngắn với người lớn, nhưng với trẻ con lại rất dài)</div><div class='gd-sec'><span class='gd-tag'>にとっての＋名詞</span>dùng khi muốn gói「cái … đối với ～」thành một cụm danh từ hoàn chỉnh, ở giữa phải thêm <b>の</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとっての幸せを考えてみましょう。</span>(Cùng thử nghĩ xem hạnh phúc đối với trẻ em là gì nhé)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau にとって là một <b>đánh giá</b>: 大切, 難しい, 便利, 貴重, 意味がある… Không dùng với「thái độ hay hành động hướng tới người khác」. Câu「Cô giáo rất thân thiện với học sinh」phải nói là <span class='gd-jp'>先生は学生に対して親切だ</span>, nói thành 先生は学生にとって親切だ là sai.<br>・Từ「đối với」trong tiếng Việt dùng rất rộng, còn tiếng Nhật phải chia ra nhiều cách. Đừng cứ thấy「đối với」là phản xạ viết にとって.<br>・Về vấn đề の: <span class='gd-jp'>私にとって、幸せは家族と過ごす時間です。</span> Câu này hoàn toàn đúng, vì にとって đang bổ nghĩa cho cả câu. Chỉ khi muốn tạo thành một khối danh từ kiểu「cái … đối với ～」, ví dụ đặt trước を làm tân ngữ, thì mới bắt buộc dùng <span class='gd-jp'>にとっての</span>.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng liên quan đến「học sinh」, nhưng đổi mẫu ngữ pháp là nghĩa khác ngay:<br><b>にとって</b> = <b>đánh giá</b> từ góc nhìn của học sinh: <span class='gd-jp'>学生にとって、この先生は怖い存在だ。</span>(Đối với học sinh, thầy/cô này là một sự tồn tại đáng sợ)<br><b>に対して</b> = thái độ, hành động <b>hướng về</b> học sinh: <span class='gd-jp'>この先生は学生に対して厳しい。</span>(Thầy/cô này nghiêm khắc với học sinh)<br><b>について</b> = <b>chủ đề</b> của lời nói, suy nghĩ: <span class='gd-jp'>先生は学生について話した。</span>(Thầy/cô đã nói về chuyện của học sinh)</div><div class='gd-sec'>Một mẫu nữa hay bị nhầm là <b>として</b>, nghĩa là「với tư cách là ～」:<br><span class='gd-jp'>親として、子供を守りたい。</span>(Là cha mẹ, tôi muốn bảo vệ con)<br><span class='gd-jp'>親にとって、子供は宝物だ。</span>(Đối với cha mẹ, con cái là báu vật)</div><div class='gd-warn'>Mẹo phán đoán nhanh: phía sau là đánh giá cảm nhận kiểu「quan trọng, khó, quý giá」thì dùng にとって; phía sau là thái độ với người khác kiểu「nghiêm khắc, tốt bụng, phản đối」thì dùng に対して; phía sau là「nói, điều tra, thảo luận」thì dùng について; muốn nói「với tư cách là ～」thì dùng として.</div>","n3-28":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に関して」nghĩa là <b>「về ～」「liên quan đến ～」</b>, ý nghĩa gần giống「〜について」nhưng nghe <b>trang trọng và cứng hơn</b>. Giống như trong tiếng Việt, nói chuyện hằng ngày bạn sẽ nói「về chuyện đó」, còn thông báo công ty, bản tin thì sẽ viết「liên quan đến vụ việc này」. Bạn sẽ gặp nó rất thường xuyên trong tin tức, thông báo công ty, thông báo trường học, thư trả lời chăm sóc khách hàng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước luôn là <b>danh từ</b>, còn phía sau nối với gì thì quyết định dạng bạn dùng:</div><div class='gd-sec'><span class='gd-tag'>Phía sau là câu</span>Danh từ＋に関して, rồi nối với một câu hoàn chỉnh (làm gì, như thế nào).</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の原因に関して、今調べています。</span>(Về nguyên nhân vụ tai nạn, hiện đang điều tra)</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関して、何か質問はありますか。</span>(Về việc này, bạn có câu hỏi nào không?)</div><div class='gd-sec'><span class='gd-tag'>Phía sau là danh từ</span>Danh từ＋に関する＋danh từ, dùng để bổ nghĩa cho danh từ phía sau, thành「… liên quan đến ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>環境問題に関する本を探しています。</span>(Tôi đang tìm sách liên quan đến vấn đề môi trường)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の文化に関するレポートを書きました。</span>(Tôi đã viết một bài báo cáo về văn hóa Nhật Bản)</div><div class='gd-sec'>Khi phía sau là danh từ, bạn cũng có thể nói <span class='gd-jp'>に関しての</span>, ví dụ <span class='gd-jp'>環境問題に関しての本</span>, nghĩa giống nhau.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>に関しては</span>thêm「は」, mang cảm giác「còn phần ○○ thì…」, hay dùng khi giải thích hoặc trả lời câu hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>料金に関しては、こちらをご覧ください。</span>(Về phần chi phí, mời bạn xem ở đây)</div><div class='gd-sec'><span class='gd-tag'>に関しまして</span>là phiên bản lịch sự hơn, rất hay nghe trong điện thoại công việc và khi giải thích ở những dịp trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関しまして、後ほどご連絡いたします。</span>(Về việc này, lát nữa chúng tôi sẽ liên lạc lại với quý khách)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi phía sau là danh từ, phải dùng <b>に関する</b> hoặc <b>に関しての</b>. <span class='gd-jp'>環境問題に関して本</span> là sai, phải nói <span class='gd-jp'>環境問題に関する本</span>.<br>・Mẫu này rất trang trọng, nói chuyện với bạn bè mà dùng sẽ nghe hơi lạ, như đang họp vậy. Giữa bạn bè, nói về chủ đề như「bộ phim hôm qua」thì dùng <span class='gd-jp'>について</span> là đủ.<br>・Không phải lúc nào「với ～」hay「đối với ～」trong tiếng Việt cũng đổi được thành に関して. Trong「lịch sự với khách」, thái độ hướng về một người nên phải dùng <span class='gd-jp'>に対して</span>, không dùng に関して được.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>について</b> = 「về ～」, dùng được cả đời thường lẫn trang trọng, phạm vi rộng nhất. <b>に関して</b> nghĩa giống, chỉ là trang trọng hơn.<br><span class='gd-jp'>昨日の試合について話そうよ。</span>(Mình nói về trận đấu hôm qua đi: bạn bè nói chuyện)<br><span class='gd-jp'>昨日の試合に関して、監督がコメントを発表した。</span>(Về trận đấu hôm qua, huấn luyện viên đã đưa ra bình luận: tin tức)<br>Nhớ thêm một điều: khi について đứng trước danh từ thì là <span class='gd-jp'>についての</span>, ví dụ <span class='gd-jp'>日本についての本</span>.</div><div class='gd-sec'><b>に対して</b> = 「đối với ～, hướng về ～」, nói về thái độ, hành động hướng tới ai.<br><span class='gd-jp'>お客様に対して、丁寧な言葉を使います。</span>(Với khách hàng, chúng tôi dùng lời lẽ lịch sự)<br>Câu này không thể đổi thành に関して, vì bạn không nói về「chủ đề liên quan đến khách」mà là「nói chuyện với khách」.</div><div class='gd-sec'><b>にとって</b> = 「đối với ～」, đánh giá từ lập trường của ai đó.<br><span class='gd-jp'>私にとって、家族が一番大切です。</span>(Đối với tôi, gia đình là quan trọng nhất)</div><div class='gd-warn'>Mẹo phán đoán nhanh: nếu trong tiếng Việt nói được là「liên quan đến ～, về ～」thì dùng に関して (trang trọng) hoặc について (đời thường); 「thái độ hướng về ai đó」dùng に対して; 「đối với ai đó (theo quan điểm của họ)」dùng にとって.</div>","n3-3":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'><span class='gd-jp'>〜について</span> tương đương với <b>“về ～”, “liên quan đến ～”</b> trong tiếng Việt. Bạn nêu ra một chủ đề trước, rồi nối với các động từ như “nói, hỏi, tìm hiểu, nghĩ” để cho người nghe biết <b>nội dung</b> bạn đang bàn hoặc nghiên cứu là gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画についてどう思う？</span>（Bạn thấy bộ phim này thế nào?）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Theo sau là động từ</b>: danh từ＋について<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化について調べる</span></span>（tìm hiểu về văn hóa Nhật Bản）<br><b>Theo sau là danh từ</b>: danh từ＋<b>についての</b>＋danh từ<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化についての本</span></span>（cuốn sách về văn hóa Nhật Bản）<br><b>Phía trước là cả một câu</b>: thêm「こと」hoặc「か」trước để biến nó thành một chủ đề.<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学することについて</span></span>（về chuyện đi du học）<br><span class='gd-pair'><span class='gd-jp'>どうする</span> → <span class='gd-jp'>どうするかについて話し合う</span></span>（bàn bạc xem nên làm thế nào）</div><div class='gd-sec'>Mẹo nhớ: <span class='gd-jp'>について</span> vốn là「に＋就いて」, mang cảm giác “bám vào việc này”, nên nó dùng để nói về một chủ đề nào đó.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>について＋động từ</span>Cách dùng cơ bản nhất, phía sau thường là “nói, viết, hỏi, tìm hiểu, nghĩ”.</div><div class='gd-ex-line'>・<span class='gd-jp'>将来について考えたことある？</span>（Bạn đã bao giờ nghĩ về tương lai chưa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の予定について話しましょう。</span>（Cùng nói về kế hoạch du lịch nhé）</div><div class='gd-sec'><span class='gd-tag'>についての＋danh từ</span>Bổ nghĩa cho danh từ phía sau, giống “… về ～” trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の歴史についての本を読んでいます。</span>（Mình đang đọc một cuốn sách về lịch sử Nhật Bản）</div><div class='gd-sec'><span class='gd-tag'>については</span>Tách chủ đề ra để nói riêng, có cảm giác “còn về phần ～ thì…”.</div><div class='gd-ex-line'>・<span class='gd-jp'>料金については、受付で聞いてください。</span>（Về phần chi phí, xin hãy hỏi ở quầy lễ tân）</div><div class='gd-sec'><span class='gd-tag'>につきまして</span>Dạng cực kỳ lịch sự, hay nghe thấy ở bộ phận chăm sóc khách hàng và thông báo của công ty.</div><div class='gd-ex-line'>・<span class='gd-jp'>この件につきましては、後ほどご連絡いたします。</span>（Về việc này, chúng tôi sẽ liên lạc với quý khách sau）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi theo sau là danh từ thì nhất định phải thêm「の」: <span class='gd-jp'>日本の文化について本</span> là sai, phải nói <span class='gd-jp'>日本の文化についての本</span>.<br>・Khi phía trước là động từ thì phải thêm こと trước: <span class='gd-jp'>日本で働くについて</span> là sai, phải nói <span class='gd-jp'>日本で働くことについて</span>.<br>・“Về” trong tiếng Việt dùng rất rộng, nhưng sau <span class='gd-jp'>について</span> phải là hành động liên quan đến “nội dung” (nói, hỏi, tìm hiểu, nghĩ, thảo luận). Cẩn thận: <span class='gd-jp'>先生について行く</span> là một cụm khác, nghĩa là “đi theo thầy/cô”, chứ không phải “đi về thầy/cô”.<br>・<span class='gd-jp'>私について</span>（về tôi）và <span class='gd-jp'>私にとって</span>（đối với tôi）chỉ khác nhau một chút xíu nhưng nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về “trẻ em”, đổi một cụm là nghĩa khác hẳn:<br><b>について</b>＝<b>chủ đề</b> được bàn tới: <span class='gd-jp'>子どもの教育について話す。</span>（nói về việc giáo dục trẻ em）<br><b>に対して</b>＝thái độ, hành động <b>hướng về ai</b>: <span class='gd-jp'>子どもに対して優しい。</span>（dịu dàng với trẻ em）<br><b>にとって</b>＝đánh giá <b>từ lập trường của ai</b>: <span class='gd-jp'>子どもにとって大切なことだ。</span>（là điều quan trọng đối với trẻ em）</div><div class='gd-sec'>Còn có <b>に関して</b> nghĩa gần như y hệt, đa số trường hợp có thể thay cho nhau, chỉ là trang trọng và cứng hơn, hay gặp trong thông báo, tin tức, báo cáo:<br><span class='gd-jp'>新しいルールについて説明します。</span>（Mình sẽ giải thích về quy định mới, cách nói thường ngày）<br><span class='gd-jp'>新しいルールに関して説明します。</span>（Xin giải thích liên quan đến quy định mới, trang trọng hơn）<br>Khi bổ nghĩa cho danh từ, <span class='gd-jp'>についての</span> tương ứng với <span class='gd-jp'>に関する</span>.</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói “nói chuyện gì, tìm hiểu gì” thì dùng について; “đối với ai thì thế nào” thì dùng に対して; “đối với ai mà nói” thì dùng にとって; khi viết văn bản trang trọng và muốn nói “liên quan đến” thì có thể đổi sang に関して.</div>","n3-2":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に対して」có hai nghĩa:<br>Nghĩa thứ nhất là <b>“đối với ～”, “nhắm vào ～”</b>, như một mũi tên chỉ ra thái độ, hành động, phản ứng đang hướng về ai hoặc cái gì.<br>Nghĩa thứ hai là <b>“trái lại với ～”, “trong khi ～”</b>, đặt hai vế cạnh nhau để so sánh: A thì thế này, còn B lại thế kia.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đối tượng của thái độ</span>Rất nghiêm khắc, rất dịu dàng, rất lịch sự với ai đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に対して厳しい。</span>（Thầy giáo rất nghiêm khắc với học sinh）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は誰に対しても優しい。</span>（Cô ấy dịu dàng với tất cả mọi người）</div><div class='gd-sec'><span class='gd-tag'>Đối tượng của sự phản hồi</span>Trả lời hoặc phản ứng trước câu hỏi, ý kiến, đề xuất.</div><div class='gd-ex-line'>・<span class='gd-jp'>質問に対して、丁寧に答えた。</span>（Trước câu hỏi, đã trả lời rất cẩn thận）</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいルールに対して、反対の意見が多い。</span>（Có nhiều ý kiến phản đối quy định mới）</div><div class='gd-sec'><span class='gd-tag'>Đối lập</span>Khi hai bên khác nhau rõ rệt.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が静かなのに対して、弟はにぎやかだ。</span>（Anh trai thì trầm lặng, còn em trai thì ồn ào sôi nổi）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京は雨だったのに対して、大阪は晴れていた。</span>（Tokyo thì mưa, trong khi Osaka thì nắng）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Cách dùng “đối với ～”</b>: danh từ ghép thẳng với に対して.<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様に対して</span></span><br>Khi phía sau là danh từ thì đổi thành <b>に対する</b>:<br><span class='gd-pair'><span class='gd-jp'>先生に対して</span> → <span class='gd-jp'>先生に対する態度</span>（thái độ đối với thầy cô）</span></div><div class='gd-sec'><b>Cách dùng “trái lại với ～”</b>: đặt cả một câu phía trước, rồi thêm <b>のに対して</b>.<br>Động từ và tính từ い ghép thẳng: <span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるのに対して</span></span><br>Tính từ な và danh từ phải thêm「な」trước: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに対して</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なのに対して</span></span><br>Chuyện đã xảy ra thì dùng thể quá khứ: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったのに対して</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ phía trước là <b>に</b>, không phải を: viết「先生を対して」là sai.<br>・Phía sau là danh từ thì phải dùng <b>に対する</b>: nói「先生に対して態度」là sai, phải nói <span class='gd-jp'>先生に対する態度</span>.<br>・Với nghĩa đối lập, phía trước nhất định phải có「の」: nói「静かに対して」là sai, phải nói <span class='gd-jp'>静かなのに対して</span>.<br>・“Đối với” hay “với” trong tiếng Việt dùng rất linh hoạt, nhưng không phải chỗ nào cũng thay được bằng に対して. “Tốt cho sức khỏe” là <span class='gd-jp'>体にいい</span>; “có hứng thú với văn hóa Nhật” là <span class='gd-jp'>日本文化に興味がある</span>; “đối với tôi mà nói” là <span class='gd-jp'>私にとって</span>.<br>・に対して nghe khá trang trọng. Trong trò chuyện hằng ngày, muốn nói “tốt với bạn bè” thì chỉ cần <span class='gd-jp'>友達に優しい</span> là đã rất tự nhiên.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng là chuyện “quy định mới”, đổi cách nói là nghĩa khác ngay:<br><b>について</b>＝chủ đề là gì (về ～): <span class='gd-jp'>新しいルールについて説明した。</span>（Đã giải thích về nội dung quy định mới）<br><b>に対して</b>＝thái độ, phản ứng hướng về ai hoặc cái gì (đối với ～): <span class='gd-jp'>新しいルールに対して、文句を言う人が多い。</span>（Có nhiều người phàn nàn về quy định mới）<br><b>にとって</b>＝đánh giá từ lập trường của ai (đối với ～ mà nói): <span class='gd-jp'>学生にとって、新しいルールは厳しすぎる。</span>（Đối với học sinh, quy định mới quá khắt khe）</div><div class='gd-sec'>Cặp dễ lẫn nhất là:<br><span class='gd-jp'>先生は学生に対して厳しい。</span>（Thầy giáo nghiêm khắc với học sinh: người nghiêm khắc là thầy）<br><span class='gd-jp'>この試験は学生にとって難しい。</span>（Kỳ thi này khó đối với học sinh: người thấy khó là học sinh）<br>Ngoài ra, <b>に関して</b> có nghĩa giống について, chỉ là trang trọng hơn.</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói “về chủ đề gì” thì dùng について; nói “đối với ai thì thế nào, phản ứng với cái gì” thì dùng に対して; nói “đối với ai thì là như thế nào” thì dùng にとって.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp <span class='gd-jp'>〜にとって</span> và <span class='gd-jp'>〜に関して</span> để phân biệt một lượt các cách nói “đối với, về” này.</div>","n3-41":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜わけだ」 tương đương với <b>“thảo nào ～”, “hóa ra là vậy, nên mới ～”</b>, cũng có thể là <b>“tức là ～”</b>. Bạn đã có sẵn một sự thật trong tay, rồi lại biết thêm nguyên nhân phía sau (hoặc tính toán lại thông tin), hai bên nối lại với nhau thì trong đầu bạn nghĩ “ồ, hiểu rồi”. Lúc đó hãy dùng わけだ.<br>(<span class='gd-jp'>わけ</span> viết bằng chữ Hán là 「訳」, nghĩa là lý lẽ, nguyên do.)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Thảo nào</span>Chuyện từ lâu bạn đã thấy lạ, giờ biết nguyên nhân nên chợt vỡ lẽ. Thường đi cùng <span class='gd-jp'>道理で</span> (thảo nào), <span class='gd-jp'>〜のか</span> (hóa ra ～ à).</div><div class='gd-ex-line'>・<span class='gd-jp'>道理で寒いわけだ。雪が降っている。</span>(Thảo nào lạnh thế, hóa ra đang có tuyết rơi)</div><div class='gd-ex-line'>・<span class='gd-jp'>3年も住んでいたのか。日本語が上手なわけだ。</span>(Sống ở đây tận ba năm à, thảo nào tiếng Nhật giỏi thế)</div><div class='gd-sec'><span class='gd-tag'>Tức là</span>Nói lại thông tin vừa nêu theo cách khác, hoặc tính ra kết quả, giống như bạn đang nói “vậy kết luận là ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に出て9時に着いたから、1時間かかったわけだ。</span>(8 giờ ra khỏi nhà, 9 giờ đến nơi, tức là mất một tiếng)</div><div class='gd-ex-line'>・<span class='gd-jp'>「明日は会社が休みです。」「じゃあ、ゆっくり寝られるわけですね。」</span>(“Ngày mai công ty nghỉ.” “Vậy tức là có thể ngủ thoải mái rồi nhỉ.”)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: thể thường nối trực tiếp (thể thường = cách nói không có ます; quá khứ, phủ định đều được)<br><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないわけだ</span></span><span class='gd-pair'><span class='gd-jp'>かかった</span> → <span class='gd-jp'>かかったわけだ</span></span><br><b>Tính từ い</b>: nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いわけだ</span></span><br><b>Tính từ な</b>: phải giữ lại 「な」<br><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手なわけだ</span></span><br><b>Danh từ</b>: thêm 「な」 (văn viết trang trọng hơn thì dùng 「である」)<br><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みなわけだ</span></span><br>Khi nói với người khác cần lịch sự thì đổi thành <span class='gd-jp'>わけです</span>. Lúc trò chuyện thường rút gọn thành <span class='gd-jp'>わけか</span>、<span class='gd-jp'>わけね</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ <b>không được nối thẳng わけ</b>: phải nói <span class='gd-jp'>上手なわけだ</span>, không phải “上手わけだ”.<br>・わけだ không phải để đoán bừa. Phía trước nhất định phải có <b>sự thật hoặc lý do bạn đã biết</b>, và bạn chỉ đang nối nó với kết quả.<br>・Khi dùng cho khuyết điểm của người khác, như <span class='gd-jp'>だから失敗したわけだ</span> (thảo nào thất bại), câu nghe có vị “bảo sao”, nên hãy cẩn thận với người trên và khách hàng.<br>・Đừng nhầm với <span class='gd-jp'>わけがない</span>、<span class='gd-jp'>わけではない</span>、<span class='gd-jp'>わけにはいかない</span>: chỉ khác vài chữ mà nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>はずだ</b> cũng là “đưa ra nhận định dựa trên lý do”, điểm khác biệt then chốt nằm ở <b>lúc kết quả còn chưa chắc chắn</b>: nếu chỉ là suy đoán theo lẽ thường thì chỉ dùng được はずだ, không dùng được わけだ. Cùng một tình huống: anh Tanaka đã sống ở Mỹ mười năm.<br><span class='gd-tag'>わけだ</span>Bạn đã nghe anh ấy nói tiếng Anh và thấy rất trôi chảy, giờ biết được nguyên nhân:<br><span class='gd-jp'>10年もアメリカにいたのか。英語がうまいわけだ。</span>(Ở Mỹ tận mười năm à, thảo nào tiếng Anh giỏi thế)<br><span class='gd-tag'>はずだ</span>Bạn chưa nghe anh ấy nói tiếng Anh, chỉ suy đoán theo lẽ thường (lúc này không dùng được わけだ):<br><span class='gd-jp'>10年もアメリカにいたから、英語がうまいはずだ。</span>(Anh ấy ở Mỹ mười năm, theo lẽ thường thì tiếng Anh phải giỏi)<br>Thêm một ví dụ: <span class='gd-jp'>彼は来ると言っていたから、来るはずだ。</span>(Anh ấy nói sẽ đến, nên chắc chắn sẽ đến) Người chưa xuất hiện, kết quả chưa chắc chắn thì dùng はずだ.<br>Tuy nhiên, với nghĩa “thảo nào” thì はずだ cũng dùng được, như <span class='gd-jp'>道理で寒いはずだ。</span>、<span class='gd-jp'>10年もアメリカにいたのか。英語がうまいはずだ。</span> đều rất tự nhiên, nghĩa gần giống わけだ.<br>Còn nếu đến lý do cũng không có, chỉ đoán đại kiểu “chắc là vậy” thì đó là <span class='gd-jp'>だろう</span>／<span class='gd-jp'>でしょう</span>, không phải はずだ, cũng không phải わけだ.</div><div class='gd-warn'>Mẹo phân biệt nhanh: khi kết quả chưa chắc chắn, chỉ suy đoán theo lẽ thường thì chỉ dùng được はずだ; khi kết quả đã nằm ngay trước mắt và bạn đang nói “thảo nào / hóa ra là vậy” thì わけだ và はずだ đều dùng được.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Bạn có thể học tiếp “họ nhà わけ”: <span class='gd-jp'>わけがない</span> (không thể nào), <span class='gd-jp'>わけではない</span> (không phải là ～), <span class='gd-jp'>わけにはいかない</span> (về lý thì không thể ～). Ngoài ra, khi giải thích xong lý do và muốn kết lại, người Nhật hay nói <span class='gd-jp'>というわけで</span> (là vậy đó, nên ～): <span class='gd-jp'>というわけで、明日は休みます。</span> (Là vậy đó, nên ngày mai tôi xin nghỉ)</div>","n3-13":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Nghĩa thường gặp nhất của 「〜うちに」 là <b>「nhân lúc ～, tranh thủ lúc ～」</b>, giống kiểu \"rèn sắt khi còn nóng\": trạng thái hiện tại <b>sau này sẽ thay đổi</b>, nên phải tranh thủ làm ngay khi còn kịp. Ngoài ra nó còn một nghĩa nữa là <b>「cứ ～ một lúc thì tự nhiên…」</b>. Cả hai nghĩa đều rất hay dùng.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nhân lúc ～</span>Trạng thái hiện tại (còn nóng, còn trẻ, còn là sinh viên) sẽ không kéo dài mãi, nên bạn cần nắm lấy cơ hội.</div><div class='gd-ex-line'>・<span class='gd-jp'>熱いうちに召し上がってください。</span>(Mời bạn ăn nhân lúc còn nóng)</div><div class='gd-ex-line'>・<span class='gd-jp'>学生のうちに、たくさん本を読んでおきたい。</span>(Mình muốn tranh thủ lúc còn là sinh viên để đọc thật nhiều sách)</div><div class='gd-ex-line'>・<span class='gd-jp'>両親が元気なうちに、一緒に旅行したい。</span>(Mình muốn đi du lịch cùng bố mẹ khi hai người còn khỏe)</div><div class='gd-sec'><span class='gd-tag'>Trước khi chưa ～</span>Dùng thể ない＋うちに, nghĩa là \"nhân lúc việc nào đó chưa xảy ra\", mang cảm giác hơi gấp gáp.</div><div class='gd-ex-line'>・<span class='gd-jp'>暗くならないうちに帰ろう。</span>(Về thôi, trước khi trời tối)</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないうちに、メモしておこう。</span>(Ghi lại trước khi quên đã)</div><div class='gd-sec'><span class='gd-tag'>Cứ ～ rồi tự nhiên…</span>Vế trước là một việc cứ diễn ra liên tục, làm một lúc thì vế sau xuất hiện một thay đổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>話しているうちに、仲良くなった。</span>(Nói chuyện một lúc thì thân nhau lúc nào không hay)</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も聞いているうちに、歌詞を覚えた。</span>(Nghe đi nghe lại nhiều lần, thế là thuộc lời bài hát)</div><div class='gd-ex-line'>・<span class='gd-jp'>知らないうちに寝てしまった。</span>(Mình ngủ quên lúc nào không hay)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ thể ている: <span class='gd-pair'><span class='gd-jp'>話している</span> → <span class='gd-jp'>話しているうちに</span></span><br>Động từ thể ない: <span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないうちに</span></span><br>Tính từ đuôi い: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱いうちに</span></span><br>Tính từ đuôi な: thêm な　<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なうちに</span></span><br>Danh từ: thêm の　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のうちに</span></span><br>Thể từ điển của động từ cũng nối được, nhưng phần lớn là các động từ chỉ \"trạng thái\", ví dụ <span class='gd-jp'>日本にいるうちに</span> (nhân lúc còn ở Nhật).</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không nối với thể た: <b>×話したうちに</b>, phải nói là <span class='gd-jp'>話しているうちに</span>.<br>・Đừng nối nhầm tính từ đuôi な và danh từ: <span class='gd-jp'>元気なうちに</span> chứ không phải 元気のうちに; <span class='gd-jp'>学生のうちに</span> chứ không phải 学生なうちに; tính từ đuôi い thì không thêm の, là <span class='gd-jp'>若いうちに</span> chứ không phải 若いのうちに.<br>・Thấy 「ないうちに」 có phủ định thì đừng lo, nó có nghĩa là 「<b>trước khi chưa ～</b>」, không phải \"lúc không ～\".<br>・Với nghĩa \"nhân lúc ～\", vế sau thường là việc bạn muốn làm hoặc cần làm: <span class='gd-jp'>〜ておこう</span>、<span class='gd-jp'>〜たい</span>、<span class='gd-jp'>〜てください</span>.<br>・Với nghĩa \"cứ ～ rồi tự nhiên…\", vế sau là thay đổi xảy ra một cách tự nhiên, hay gặp <span class='gd-jp'>〜なった</span>、<span class='gd-jp'>〜てしまった</span>, chứ không phải việc bạn chủ động làm.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>間に</b> = chỉ đơn giản nói \"trong khoảng thời gian đó\", không mang sắc thái cảm xúc đặc biệt: <span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>(Mình muốn leo núi Phú Sĩ trong thời gian ở Nhật)<br><b>うちに</b> = mang cảm giác 「<b>nhân lúc còn đang thế này, sau này sẽ không còn cơ hội</b>」: <span class='gd-jp'>日本にいるうちに、富士山に登りたい。</span>(Mình muốn nhân lúc còn ở Nhật mà leo núi Phú Sĩ)<br>Nếu khoảng thời gian có điểm bắt đầu và kết thúc rõ ràng, ví dụ \"từ 3 giờ đến 5 giờ\", thì chỉ dùng được <span class='gd-jp'>3時から5時の間に</span>, không dùng うちに.</div><div class='gd-sec'><b>前に</b> và <b>ないうちに</b> cũng khá giống nhau:<br><span class='gd-jp'>雨が降る前に帰ろう。</span>(Về trước khi trời mưa nhé: chỉ nói về thứ tự)<br><span class='gd-jp'>雨が降らないうちに帰ろう。</span>(Về nhanh nhân lúc trời chưa mưa nhé: có cảm giác gấp hơn)</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn nói \"tranh thủ khi còn kịp, làm nhanh lên\" thì dùng うちに; chỉ nói \"trong khoảng thời gian đó\" thì dùng 間に; chỉ nói thứ tự trước sau thì dùng 前に.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể xem tiếp 「〜間に」 và 「〜最中に」 (đang lúc ～), rồi so sánh cả ba mẫu cùng nhau, như vậy khi nói về \"thời gian\" bạn sẽ không bị lẫn.</div>","n3-20":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ば〜ほど」 chính là <b>「càng ～ càng ～」</b> trong tiếng Việt. Như \"càng luyện càng giỏi\", \"càng nghĩ càng bực\": việc ở vế trước làm càng nhiều, mức độ càng cao thì kết quả ở vế sau càng rõ.<br>Cách làm trong tiếng Nhật là: <b>lặp lại cùng một từ hai lần</b>, lần đầu dùng thể ば (thể \"nếu ～\"), lần hai dùng dạng gốc, cuối cùng thêm ほど.</div><div class='gd-ex-line'>・<span class='gd-jp'>練習すればするほど上手になる。</span>(Càng luyện tập càng giỏi)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Đổi sang thể ば trước, sau đó nối thể từ điển (dạng gốc trong từ điển) của cùng động từ đó, rồi thêm ほど.<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「え」 cùng hàng, rồi thêm ば.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → đổi む thành め → <span class='gd-jp'>読めば読むほど</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行けば行くほど</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」, thêm れば.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば食べるほど</span></span><br><b>Nhóm 3</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればするほど</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば来るほど</span>(くればくるほど)</span><br>Với động từ dạng 「danh từ＋する」 như 「<span class='gd-jp'>勉強する</span>」, lần thứ hai thường chỉ giữ lại する: <span class='gd-jp'>勉強すればするほど</span>.</div><div class='gd-sec'><span class='gd-tag'>Tính từ đuôi い</span>Bỏ 「い」, thêm ければ, vế sau nối tính từ đuôi い gốc＋ほど.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ安いほど</span></span></div><div class='gd-sec'><span class='gd-tag'>Tính từ đuôi な</span>Vế trước dùng なら, vế sau thêm な＋ほど.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら静かなほど</span></span></div><div class='gd-h'>Những câu hay gặp nhất</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は勉強すればするほど面白くなる。</span>(Tiếng Nhật càng học càng thú vị)</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は読めば読むほど好きになる。</span>(Cuốn sách này càng đọc càng thích)</div><div class='gd-ex-line'>・<span class='gd-jp'>返事は早ければ早いほどいいです。</span>(Trả lời càng sớm càng tốt)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋は静かなら静かなほどいい。</span>(Phòng càng yên tĩnh càng tốt)</div><div class='gd-sec'>「<span class='gd-jp'>早ければ早いほどいい</span>」「<span class='gd-jp'>多ければ多いほどいい</span>」 gần như là cách nói cố định, bạn thuộc cả câu sẽ rất tiện.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước và sau nhất định phải là <b>cùng một từ</b>. Tiếng Việt nói \"càng A càng B\", còn tiếng Nhật lặp lại A hai lần, B nằm ở vế câu phía sau.<br>・Lần sau dùng dạng gốc, đừng thêm ば nữa: là <span class='gd-jp'>考えれば考えるほど</span>, không phải 考えれば考えればほど.<br>・Thể ば của <span class='gd-jp'>いい</span> là <span class='gd-jp'>よければ</span>, không phải いければ: <span class='gd-jp'>よければよいほど</span>.<br>・<span class='gd-jp'>来れば</span> đọc là くれば, không phải きれば.<br>・Với tính từ đuôi な, vế trước là なら, vế sau là な, hai bên khác nhau, đừng viết thành <span class='gd-jp'>静かなら静かならほど</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>〜ば〜ほど</b>: <span class='gd-jp'>練習すればするほど上手になる。</span>(Càng luyện tập càng giỏi)<br><b>〜ほど</b> (bỏ ば ở vế trước): <span class='gd-jp'>練習するほど上手になる。</span>(Nghĩa giống nhau)<br>Bản bỏ ば thì ngắn gọn hơn; bản có ば thể hiện cảm giác \"càng ～ càng ～\" rõ ràng và mạnh hơn.<br><b>〜とともに</b>: <span class='gd-jp'>年をとるとともに、体力が落ちる。</span>(Cùng với tuổi tác tăng lên, thể lực sẽ giảm)<br>So sánh: <span class='gd-jp'>年をとればとるほど、体力が落ちる。</span>(Tuổi càng cao, thể lực càng kém)<br>とともに nghĩa là \"cùng với ～\", trang trọng và mang tính văn viết hơn; ば〜ほど nghĩa là \"càng ～ càng ～\", dùng được cả khi nói lẫn khi viết.</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn nói \"càng ～ càng ～\" thì dùng ば〜ほど; chỉ khi muốn nói \"cùng với ～\" theo kiểu trang trọng hơn thì mới dùng とともに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜ほど」 đứng một mình còn có cách dùng \"đến mức ～\", ví dụ <span class='gd-jp'>泣きたいほど痛い</span> (đau đến mức muốn khóc). Bạn có thể xem tiếp thẻ 「〜ほど」 nhé.</div>","n3-21":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」giống với tiếng Việt <b>「cũng không phải là không～ đâu」</b>. Hai lần phủ định chồng lên nhau, nghĩa thực ra là \"được\", nhưng là <b>kiểu \"được\" bị giảm bớt</b>: làm cũng được, có khả năng, chỉ là không muốn lắm, không hào hứng lắm. Giống như bạn rủ bạn bè bốn giờ sáng đi leo núi, họ trả lời \"cũng không phải là không đi được đâu…\", ai cũng nghe ra là họ không muốn đi lắm.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ chuyển sang thể ない trước, rồi thêm <span class='gd-jp'>ことはない</span> hoặc <span class='gd-jp'>こともない</span>.<br><span class='gd-pair'><span class='gd-jp'>行ける</span> → <span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けないことはない</span></span>（cũng không phải là không đi được）<br><span class='gd-pair'><span class='gd-jp'>食べられる</span> → <span class='gd-jp'>食べられない</span> → <span class='gd-jp'>食べられないこともない</span></span>（cũng không phải là không ăn được）<br>Mẫu này hay đi với cách nói về \"có làm được hay không\", tức là những từ như <span class='gd-jp'>行ける</span>、<span class='gd-jp'>できる</span>、<span class='gd-jp'>食べられる</span>, vì bản thân mẫu câu này vốn hay dùng để nói về khả năng làm được hay không.</div><div class='gd-sec'>Nếu bạn chưa quen thể ない thì ôn lại một chút nhé:<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm hàng「あ」cùng hàng, rồi thêm ない. <span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành か → <span class='gd-jp'>行かない</span></span>; động từ kết thúc bằng う thì đổi thành わ: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」, thêm ない. <span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><br><b>Nhóm 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm được nhưng hơi gượng</span>Hơi vất vả, nhưng nếu cố thì vẫn làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>この量なら、一人で食べられないことはない。</span>（Với lượng này thì một mình mình cũng không phải là không ăn hết được）</div><div class='gd-sec'><span class='gd-tag'>Theo sau là điều kiện kèm theo</span>Dạng hay gặp nhất là thêm「<span class='gd-jp'>けど</span>／<span class='gd-jp'>が</span>」ở phía sau, rồi nói ra điều băn khoăn thật sự.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩けないことはないけど、ちょっと遠いね。</span>（Đi bộ ra ga cũng không phải là không đi được, nhưng hơi xa đấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>行けないこともないが、あまり気が進まない。</span>（Cũng không phải là không đi được, nhưng không muốn đi lắm）</div><div class='gd-sec'><span class='gd-tag'>Trả lời lấp lửng</span>Khi bị hỏi mà bạn không muốn nhận lời ngay, nhưng cũng không muốn từ chối thẳng.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにできる？</span>（Trước ngày mai làm xong được không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>できないことはないですけど…。</span>（Cũng không phải là không làm xong được, nhưng mà…）</div><div class='gd-sec'><b>ことはない và こともない khác nhau ở đâu?</b> Nghĩa gần như giống nhau, có thể thay cho nhau. <span class='gd-jp'>こともない</span> có thêm「も」nên giọng mềm hơn, mơ hồ hơn một chút, như đang nói \"thật ra… thì cũng tạm được\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Câu này mang nghĩa <b>khẳng định</b>. <span class='gd-jp'>行けないことはない</span>＝đi được (chỉ là hơi miễn cưỡng), đừng thấy hai chữ \"không\" mà tưởng là \"không đi được\".<br>・Nó <b>không phải là kiểu \"được\" sảng khoái</b>. Bạn bè rủ mà bạn đáp <span class='gd-jp'>行けないことはない</span>, người ta sẽ thấy bạn không muốn đến lắm. Nếu thật lòng muốn đi thì hãy nói <span class='gd-jp'>行けるよ</span>、<span class='gd-jp'>いいね、行こう</span>. Nói thế với cấp trên hay khách hàng cũng dễ bị cho là thiếu hợp tác.<br>・Phía trước nhất định phải là <b>thể ない</b>. Thiếu ない thì <span class='gd-jp'>行くことはない</span> sẽ thành \"không cần đi\", nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về \"karaoke\", chỉ khác ở phần đứng trước mà nghĩa đã hoàn toàn khác:<br><b>Thể ない＋ことはない</b>＝cũng không phải là không～: <span class='gd-jp'>カラオケは行かないことはないけど、年に一回くらいかな。</span>（Karaoke thì cũng không phải là không đi, chắc một năm khoảng một lần thôi）<br><b>Thể từ điển＋ことはない</b>＝không cần～: <span class='gd-jp'>嫌なら、無理して行くことはないよ。</span>（Nếu không thích thì không cần cố đi đâu）<br><b>Thể た＋ことはない</b>＝chưa từng～: <span class='gd-jp'>カラオケには一度も行ったことはない。</span>（Mình chưa đi karaoke lần nào）<br><b>ないわけではない</b>＝không phải là～: <span class='gd-jp'>カラオケが好きじゃないわけではない。</span>（Không phải là mình không thích karaoke）<br>Mẫu cuối này khá gần với ないことはない. Khác nhau ở chỗ <span class='gd-jp'>わけではない</span> nhấn vào việc đính chính hiểu lầm của đối phương: \"sự thật không như bạn nghĩ\"; còn <span class='gd-jp'>ないことはない</span> nhấn vào \"có khả năng, miễn cưỡng thì được\".</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước có「ない」＋<span class='gd-jp'>ことはない</span>＝\"cũng không phải là không～\"; thể từ điển＋<span class='gd-jp'>ことはない</span>＝\"không cần～\"; thể た＋<span class='gd-jp'>ことはない</span>＝\"chưa từng～\", lại là một nghĩa khác; muốn đính chính hiểu lầm của người khác thì dùng <span class='gd-jp'>わけではない</span>.</div>","n3-29":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜わりに」giống với tiếng Việt <b>「xét về ～ thì cũng khá…」「lẽ ra phải～, vậy mà lại…」</b>. Từ việc đứng trước, bạn hình dung ra một kết quả \"lẽ ra sẽ như thế\", nhưng thực tế lại khác với dự đoán, lúc đó dùng わりに. Ví dụ nói với bạn \"quán này giá như vậy mà phần ăn nhiều ghê\", đó chính là cảm giác của わりに.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Bất ngờ theo hướng tốt</span>Kết quả tốt hơn tưởng tượng.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は、値段のわりに量が多い。</span>（Quán này xét theo giá thì phần ăn khá nhiều）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はよく食べるわりに、太らない。</span>（Anh ấy ăn nhiều như vậy mà lại không béo）</div><div class='gd-sec'><span class='gd-tag'>Bất ngờ theo hướng xấu</span>Kết quả tệ hơn tưởng tượng, giọng hơi thất vọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>よく勉強したわりに、点数が悪かった。</span>（Học nhiều như vậy mà điểm lại thấp）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は体が大きいわりには、気が小さい。</span>（Anh ấy to con như vậy mà lại nhát gan）</div><div class='gd-sec'>Muốn nhấn mạnh hơn, bạn có thể nói thành <b>わりには</b>, nghĩa vẫn như nhau.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp, việc đã xảy ra thì dùng thể た.<br><span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるわりに</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強した</span> → <span class='gd-jp'>勉強したわりに</span></span><br><b>Tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いわりに</span></span><br><b>Tính từ な</b>: đổi だ thành な.<br><span class='gd-pair'><span class='gd-jp'>丈夫だ</span> → <span class='gd-jp'>丈夫なわりに</span></span><br><b>Danh từ</b>: thêm の.<br><span class='gd-pair'><span class='gd-jp'>年齢</span> → <span class='gd-jp'>年齢のわりに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近いわりに、家賃が安い。</span>（Phòng này gần ga như vậy mà tiền thuê lại rẻ）</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは丈夫なわりに軽い。</span>（Cái cặp này bền như vậy mà lại nhẹ）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに元気だ。</span>（Bố mình so với tuổi thì còn khỏe lắm）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な phải dùng「な」, danh từ phải thêm「の」: đúng là <span class='gd-jp'>丈夫なわりに</span>、<span class='gd-jp'>年齢のわりに</span>, không phải 丈夫だわりに、年齢わりに.<br>・Nhất định phải \"khác với dự đoán\" thì mới dùng được. Đồ đắt mà ngon là chuyện đương nhiên, nên nói <span class='gd-jp'>値段が高いわりにおいしい</span> nghe rất lạ; phải nói <span class='gd-jp'>値段が高いわりにおいしくない</span> (đắt như vậy mà không ngon) mới đúng.<br>・Phía trước tốt nhất là thứ có thể so sánh cao thấp, nhiều ít: tuổi tác, giá cả, chiều cao, lượng học.<br>・Phía sau là để miêu tả, đánh giá, không thể nối với yêu cầu hay lời mời kiểu \"hãy～\", \"nào cùng～\".<br>・<span class='gd-jp'>わりに</span> đứng riêng ngay trước tính từ (cũng hay nói <span class='gd-jp'>わりと</span>) là một cách dùng khác, nghĩa là \"hơn tưởng tượng\": <span class='gd-jp'>今日のテストはわりに簡単だった。</span>（Bài kiểm tra hôm nay dễ hơn mình tưởng）</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>にしては</b> cũng có nghĩa \"xét về ～ thì thật bất ngờ\", dịch sang tiếng Việt gần như giống nhau, khác nhau ở thứ đặt phía trước.<br><b>わりに</b>: phía trước có thể là mức độ chung chung như \"tuổi tác, giá cả\", và có thể nối với tính từ, động từ.<br><b>にしては</b>: phía trước đặt con số, thân phận hoặc sự thật cụ thể, như「60歳」「1000円」「初めて」, chủ yếu nối với danh từ và động từ, ít nối với tính từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに若く見える。</span>（Bố mình so với tuổi thì trông trẻ）</div><div class='gd-ex-line'>・<span class='gd-jp'>父は60歳にしては若く見える。</span>（Với một người 60 tuổi thì bố mình trông trẻ）</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は値段のわりにおいしい。</span>（Món này xét theo giá thì ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は1000円にしてはおいしい。</span>（Món này với 1000 yên thì ngon）</div><div class='gd-sec'>Ngược lại, nói「年齢にしては」「値段にしては」nghe không tự nhiên, vì \"tuổi tác\" và \"giá cả\" không phải là một con số cụ thể.</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước là mức độ chung chung như \"tuổi tác, giá cả\", hoặc là tính từ thì dùng わりに; phía trước là con số hay thân phận cụ thể như \"60 tuổi, 1000 yên, lần đầu tiên\" thì dùng にしては.</div>","n3-30":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にしては」nghĩa là <b>「xét về ～ thì cũng khá…／vậy mà lại…」</b>. Bạn có sẵn một kỳ vọng về một thân phận hay một sự thật nào đó, nhưng thực tế lại <b>khác với kỳ vọng</b>. Lúc đó hãy dùng mẫu này.<br>Ví dụ thấy một bạn nhỏ viết chữ rất đẹp, bạn sẽ nói “xét là trẻ con thì chữ đẹp thật đấy”. Câu đó là <span class='gd-jp'>子どもにしては、字がきれいだ。</span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Tốt hơn kỳ vọng</span>Ban đầu bạn không mong đợi nhiều, nhưng kết quả lại khá tốt, nên câu mang chút khen ngợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて作ったにしては、おいしいね。</span>（Xét là lần đầu làm thì ngon thật đấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人にしては、よくやっている。</span>（Xét là người mới thì làm tốt lắm rồi）</div><div class='gd-sec'><span class='gd-tag'>Tệ hơn kỳ vọng</span>Ban đầu bạn mong đợi rất nhiều, nhưng kết quả lại làm bạn thất vọng, nên câu mang chút chê trách.</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な店にしては、あまりおいしくなかった。</span>（Xét là quán nổi tiếng thì không ngon lắm）</div><div class='gd-sec'><span class='gd-tag'>Thời tiết, thời gian</span>Khác với vẻ thường thấy của mùa hay thời điểm đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>4月にしては寒いですね。</span>（Xét là tháng 4 thì lạnh thật đấy）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: nối trực tiếp, ở giữa <b>không thêm の, cũng không thêm だ</b>.<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロにしては</span></span><span class='gd-pair'><span class='gd-jp'>4月</span> → <span class='gd-jp'>4月にしては</span></span></div><div class='gd-sec'><b>Động từ</b>: dùng thể thông thường (thể từ điển, thể た… tức là các dạng không có ます).<br><span class='gd-pair'><span class='gd-jp'>初めて作った</span> → <span class='gd-jp'>初めて作ったにしては</span></span><span class='gd-pair'><span class='gd-jp'>3年も住んでいる</span> → <span class='gd-jp'>3年も住んでいるにしては</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ, nối thẳng にしては, <b>đừng thêm の</b>: nói <span class='gd-jp'>子どもにしては</span>, không nói 子どものにしては. (Mẫu có の là <span class='gd-jp'>子どものわりに</span>, đừng nhầm lẫn nhé.)<br>・Phần đứng trước phải là <b>thân phận, con số, sự thật cụ thể</b>, như 「新人」「60歳」「千円」「初めて」. Những từ chỉ nói về một phạm vi như “tuổi”, “giá cả”, “chiều cao” thì không nối trực tiếp được: nói <span class='gd-jp'>値段にしては</span> nghe không tự nhiên, phải đổi thành <span class='gd-jp'>値段のわりに</span>.<br>・Tính từ đuôi い thường không nối trực tiếp với にしては. Ví dụ 「安いにしては」 nghe rất lạ, trường hợp này hãy dùng <span class='gd-jp'>安いわりに</span>.<br>・Vế sau là <b>đánh giá, cảm nhận</b> của bạn, không đi với mệnh lệnh hay quyết định như 「hãy ～」「tôi sẽ ～」.<br>・Bạn cũng có thể dùng để nói về chính mình: <span class='gd-jp'>私にしては、よく頑張ったと思う。</span>（Xét là tôi thì tôi nghĩ mình đã cố gắng nhiều rồi）</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>わりに</b> (n3-29) cũng là “khác với kỳ vọng”, và tiếng Việt thường dịch đều là “xét về ～ thì…”. Điểm khác nhau nằm ở <b>thứ đứng phía trước</b>.<br>Cùng một tình huống, một bác trông rất trẻ:<br><span class='gd-jp'>あの人は60歳にしては若く見える。</span>（Xét là 60 tuổi thì bác ấy trông trẻ）→ phía trước là con số cụ thể 「60歳」<br><span class='gd-jp'>あの人は年のわりに若く見える。</span>（Bác ấy trông trẻ hơn so với tuổi thật）→ phía trước là 「年」, một từ chỉ phạm vi như “tuổi tác”<br>Cùng một quán vừa rẻ vừa ngon:<br><span class='gd-jp'>千円にしてはおいしい。</span>（Xét là 1000 yên thì ngon thật）<br><span class='gd-jp'>値段のわりにおいしい。</span>／<span class='gd-jp'>安いわりにおいしい。</span>（So với giá thì ngon／Rẻ mà vẫn ngon）<br>Ngoài ra, にしては mang cảm giác bất ngờ ngay lúc đó kiểu “rõ ràng là ～ mà”, và lời đánh giá đi kèm cũng rõ hơn.</div><div class='gd-sec'><b>として</b> (n3-5) cũng hay được dịch là “với tư cách ～”, nhưng nó nói <b>đứng trên lập trường của thân phận đó</b>, không có nghĩa “khác với kỳ vọng”.<br><span class='gd-jp'>先生として、生徒を守りたい。</span>（Với tư cách là giáo viên, tôi muốn bảo vệ học sinh）<br><span class='gd-jp'>先生にしては、字が汚いね。</span>（Xét là giáo viên mà chữ xấu thật đấy）</div><div class='gd-warn'>Mẹo phân biệt: nếu phía trước là thân phận, con số, sự thật cụ thể và kết quả làm bạn bất ngờ thì dùng にしては. Nếu phía trước là từ chỉ phạm vi như “tuổi, giá cả” hoặc là tính từ thì dùng わりに. Nếu chỉ đang nói về lập trường “với tư cách là ～” và không có gì bất ngờ thì dùng として.</div>","n3-5":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜として」nghĩa là <b>「với tư cách là ～」「trên cương vị ～」「coi như là ～」</b>. Phía trước đặt một danh từ để nói rằng bạn làm việc này với thân phận, vai trò hay danh nghĩa gì.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thân phận・lập trường</span>Làm việc gì đó với một thân phận nào đó, đây là cách dùng phổ biến nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学生として日本に来ました。</span>（Tôi đến Nhật với tư cách là du học sinh）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者として、また父として尊敬されている。</span>（Anh ấy được kính trọng, cả với tư cách bác sĩ lẫn tư cách người cha）</div><div class='gd-sec'><span class='gd-tag'>Coi như・danh nghĩa</span>Xem một món đồ như có một công dụng nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>これはお土産として買いました。</span>（Cái này tôi mua để làm quà）</div><div class='gd-sec'><span class='gd-tag'>Xét theo loại nào</span>Nói rằng một thứ nổi tiếng hay được nhìn nhận “với tư cách là ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>京都は観光地として有名です。</span>（Kyoto nổi tiếng là một địa điểm du lịch）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Rất đơn giản, <b>danh từ + として</b>:<br><span class='gd-pair'><span class='gd-jp'>先生</span> → <span class='gd-jp'>先生として</span></span><span class='gd-pair'><span class='gd-jp'>趣味</span> → <span class='gd-jp'>趣味として</span></span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>としての＋danh từ</span>Khi phía sau cần nối với danh từ, thêm「の」ở giữa.</div><div class='gd-ex-line'>・<span class='gd-jp'>親としての責任がある。</span>（Có trách nhiệm của người làm cha mẹ）</div><div class='gd-sec'><span class='gd-tag'>私としては</span>Nghĩa là “xét từ lập trường của tôi”, dùng để nêu ý kiến một cách lịch sự, rất hay nghe trong họp hành và công việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>私としては、この案に賛成です。</span>（Theo lập trường cá nhân, tôi tán thành phương án này）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Khi phía sau là danh từ, phải dùng <b>としての</b>: nói <span class='gd-jp'>医者としての仕事</span>, không thể nói 「医者として仕事」 để diễn đạt “công việc của bác sĩ”.<br>・Trong câu tiếng Việt “Đối với học sinh, việc học rất quan trọng”, “đối với ～” không phải là として. Phải nói <span class='gd-jp'>学生にとって、勉強は大切だ。</span> Nếu viết 「学生として、勉強は大切だ」 thì câu sẽ rất lạ.<br>・Về nguyên tắc, phía trước として là danh từ, đừng nối trực tiếp với động từ hay tính từ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>として</b> = danh từ phía trước là <b>thân phận, vai trò của chính nhân vật chính</b>:<br><span class='gd-jp'>父として、子どもを守りたい。</span>（Với tư cách người cha, tôi muốn bảo vệ con: người nói “là” người cha）<br><b>にとって</b> = danh từ phía trước là <b>người mà ta đứng ở góc nhìn của họ để cảm nhận, đánh giá</b>:<br><span class='gd-jp'>父にとって、子どもは一番大切だ。</span>（Đối với người cha, con cái là quan trọng nhất: nhìn từ góc nhìn của người cha）<br>Thêm một cặp nữa: <span class='gd-jp'>京都は観光地として有名だ。</span>（Kyoto “là” địa điểm du lịch, nổi tiếng với thân phận đó）／<span class='gd-jp'>私にとって、京都は特別な場所だ。</span>（Theo góc nhìn của tôi, Kyoto là nơi đặc biệt）</div><div class='gd-warn'>Mẹo phân biệt: nếu danh từ phía trước là thân phận, vai trò, loại của chính nhân vật chính (anh ấy “là” bác sĩ, Kyoto “là” địa điểm du lịch) thì dùng として. Nếu là “đứng ở góc nhìn của ai để cảm nhận, đánh giá” (đối với bố mẹ, đối với tôi) thì dùng にとって.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Bạn có thể ôn cùng lúc <span class='gd-jp'>〜にとって</span> trong cùng bài. Ngoài ra, trong <span class='gd-jp'>〜をはじめ（として）</span> (lấy ～ làm đầu) cũng có bóng dáng của として.</div>","n3-17":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜さえ〜ば」tương đương với <b>「chỉ cần ～ là ～」</b> trong tiếng Việt. Nghĩa là: những thứ khác không cần, <b>chỉ riêng một điều kiện này là đủ</b>. Ví dụ bạn muốn nói \"Chỉ cần có mạng là làm việc ở đâu cũng được\", tiếng Nhật sẽ dùng mẫu câu này.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあれば、もっと旅行したい。</span>(Chỉ cần có thời gian, mình muốn đi du lịch nhiều hơn)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước hết ôn lại cách chia thể ば (cách nói \"nếu ～\"), mình xem từng từ nhé:<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành け → <span class='gd-jp'>書けば</span></span><br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あれば</span></span><br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よければ</span></span></div><div class='gd-sec'><span class='gd-tag'>名詞＋さえ＋〜ば</span>Hay gặp nhất. さえ đặt sau thứ bạn muốn nhấn mạnh, phía sau nối thể ば của động từ hoặc tính từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気さえよければ、明日は富士山が見える。</span>(Chỉ cần thời tiết đẹp, ngày mai sẽ nhìn thấy núi Phú Sĩ)</div><div class='gd-sec'><span class='gd-tag'>動詞＋さえすれば</span>Nhấn mạnh \"chỉ cần làm hành động này\". Đầu tiên chia động từ sang thể ます, bỏ ます đi, rồi thêm さえすれば.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → bỏ ます → <span class='gd-jp'>飲みさえすれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲みさえすれば、すぐ治りますよ。</span>(Chỉ cần uống thuốc này là sẽ khỏi nhanh thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>ボタンを押しさえすれば、あとは機械がやってくれる。</span>(Chỉ cần bấm nút, phần còn lại máy sẽ làm giúp bạn)</div><div class='gd-sec'><span class='gd-tag'>て形＋さえいれば</span>Nhấn mạnh \"chỉ cần cứ giữ nguyên trạng thái này\".<br><span class='gd-pair'><span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってさえいれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ここで待ってさえいれば、大丈夫です。</span>(Chỉ cần đợi ở đây là không sao đâu)</div><div class='gd-sec'><span class='gd-tag'>形容詞＋さえあれば</span>Tính từ い thì đổi い thành く, tính từ な thì thêm で, rồi nối さえあれば.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くさえあれば</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでさえあれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かでさえあれば、狭い部屋でもかまわない。</span>(Chỉ cần yên tĩnh, phòng nhỏ một chút cũng không sao)</div><div class='gd-h'>Trong văn nói hay đổi thành たら、なら</div><div class='gd-sec'>Đổi ば thành「たら」hoặc「なら」, nghĩa vẫn là \"chỉ cần ～ là ～\", và bạn sẽ nghe rất nhiều trong hội thoại.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあったら、手伝うよ。</span>(Chỉ cần có thời gian là mình sẽ giúp)</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたさえいいなら、私はそれでいい。</span>(Chỉ cần bạn thấy ổn thì mình thế nào cũng được)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ phải dùng <b>thể ます bỏ ます</b> rồi mới nối: phải là <span class='gd-jp'>飲みさえすれば</span>, không được nói 「飲むさえすれば」。<br>・「が」「を」đứng sau danh từ sẽ bị さえ thay thế: phải là <span class='gd-jp'>お金さえあれば</span>, không phải 「お金がさえあれば」。<br>・Đây là \"chỉ cần\", không phải \"chỉ có ～ mới\". <span class='gd-jp'>練習さえすれば</span> nghĩa là \"chỉ cần luyện tập là được\", trọng tâm là điều kiện rất đơn giản, chứ không phải đang hạn chế \"những cái khác đều không được\".<br>・Phía sau さえ nhất định phải có thể điều kiện (ば、たら、なら) thì mới mang nghĩa \"chỉ cần\"; nếu không có, さえ sẽ thành nghĩa \"đến cả ～ cũng\".</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cùng là「さえ」, phía sau nối với gì sẽ quyết định nghĩa:<br><b>さえ〜ば／たら／なら</b>＝chỉ cần ～ là: <span class='gd-jp'>ひらがなさえ読めれば、このゲームはできる。</span>(Chỉ cần đọc được hiragana là chơi được game này)<br><b>さえ đứng một mình</b>＝đến cả ～ cũng: <span class='gd-jp'>ひらがなさえ読めない。</span>(Đến cả hiragana cũng không đọc được)</div><div class='gd-warn'>Mẹo nhận biết: xem sau さえ có nối thể điều kiện (〜ば、〜たら、〜なら) hay không. Có thì là \"chỉ cần\", không có thì là \"đến cả ～ cũng\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>〜さえ dùng một mình (đến cả ～ cũng) có thể học so sánh cùng các mẫu gần nghĩa như <span class='gd-jp'>〜すら</span>、<span class='gd-jp'>〜まで</span>.</div>","n3-24":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜代わりに」nghĩa là <b>「lấy B thay cho A」</b>. Có thể là đổi đồ vật, đổi người, đổi cách làm, cũng có thể là kiểu trao đổi \"bạn giúp mình, mình mời bạn\", hoặc kiểu có được có mất như \"lương cao nhưng bù lại rất mệt\". Cốt lõi đều giống nhau: <b>đổi bên này lấy bên kia, vừa vặn cân bằng</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đổi đồ vật・đổi cách làm</span>Lẽ ra dùng A, làm A, nhưng đổi thành B.</div><div class='gd-ex-line'>・<span class='gd-jp'>砂糖の代わりに、はちみつを使った。</span>(Đã dùng mật ong thay cho đường)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は外食する代わりに、家で作ろう。</span>(Hôm nay đừng ăn ngoài, mình nấu ở nhà đi)</div><div class='gd-sec'><span class='gd-tag'>Đổi người</span>Vốn dĩ A phải làm, nhưng B làm thay.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の代わりに、部長が会議に出た。</span>(Trưởng phòng đã dự cuộc họp thay giám đốc)</div><div class='gd-ex-line'>・<span class='gd-jp'>私の代わりに電話に出てくれる？</span>(Bạn nghe điện thoại giúp mình được không?)</div><div class='gd-sec'><span class='gd-tag'>Điều kiện trao đổi</span>Mình làm A, bạn làm B.</div><div class='gd-ex-line'>・<span class='gd-jp'>英語を教える代わりに、日本語を教えてもらっている。</span>(Mình dạy tiếng Anh cho đối phương, đổi lại được họ dạy tiếng Nhật)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を手伝ってもらった代わりに、昼ご飯をおごった。</span>(Được bạn giúp làm bài tập, mình mời bữa trưa để đền đáp)</div><div class='gd-sec'><span class='gd-tag'>Có tốt có xấu</span>Có một điểm tốt thì bù lại có một điểm xấu, ngược lại cũng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>給料が高い代わりに、仕事がきつい。</span>(Lương cao, nhưng bù lại công việc rất mệt)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から遠い代わりに、家賃が安い。</span>(Phòng này xa ga, nhưng bù lại tiền thuê rẻ)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: ở giữa phải thêm「の」。<span class='gd-pair'><span class='gd-jp'>砂糖</span> → <span class='gd-jp'>砂糖の代わりに</span></span><br><b>Động từ・tính từ い</b>: nối trực tiếp với thể thường, khẳng định, phủ định, quá khứ đều được.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行く代わりに</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かない代わりに</span></span><span class='gd-pair'><span class='gd-jp'>手伝ってもらった</span> → <span class='gd-jp'>手伝ってもらった代わりに</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高い代わりに</span></span><span class='gd-pair'><span class='gd-jp'>効かない</span> → <span class='gd-jp'>効かない代わりに</span></span><br><b>Tính từ な</b>: phải giữ lại「な」。<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な代わりに</span></span><br>Khi nói \"không làm A mà làm B\", động từ thường dùng thể từ điển, ví dụ <span class='gd-jp'>行く代わりに</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬はあまり効かない代わりに、副作用もない。</span>(Thuốc này không hiệu quả lắm, nhưng bù lại cũng không có tác dụng phụ)</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>その代わり</span>Đứng riêng ở đầu câu, nghĩa là \"nhưng bù lại ～\", cực hay dùng khi thương lượng điều kiện với bạn bè.</div><div class='gd-ex-line'>・<span class='gd-jp'>車、貸してあげる。その代わり、ガソリン入れてきてね。</span>(Mình cho bạn mượn xe, nhưng bù lại bạn nhớ đổ xăng giúp mình nhé)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Thứ tự ngược với tiếng Việt</b>: tiếng Việt nói \"dùng mật ong thay cho đường\" (thứ thay thế đứng trước), còn tiếng Nhật là <span class='gd-jp'>砂糖の代わりにはちみつ</span>, thứ bị thay thế đứng trước「代わりに」. Nếu viết theo thứ tự tiếng Việt thành <span class='gd-jp'>はちみつの代わりに砂糖</span>, nghĩa sẽ bị đảo ngược hoàn toàn.<br>・Đừng quên「の」sau danh từ và「な」sau tính từ な.<br>・Với cách dùng \"có tốt có xấu\", hai vế phải bù trừ được cho nhau. Nếu chỉ là \"nhưng\" đơn thuần thì dùng「けど」: <span class='gd-jp'>日本語は難しいけど、毎日勉強している。</span> Câu này không thể đổi thành 代わりに.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'><b>代わりに</b>＝một tốt một xấu, <b>vừa vặn cân bằng</b>:<br><span class='gd-jp'>この店は高い代わりに、すごくおいしい。</span>(Quán này đắt, nhưng bù lại rất ngon)<br><b>わりに</b>＝xét theo A thì kết quả <b>khác với mong đợi</b>:<br><span class='gd-jp'>この店は高いわりに、あまりおいしくない。</span>(Quán này đắt như vậy mà lại không ngon lắm)<br>Ngoài ra, <b>反面</b> cũng có thể nói một tốt một xấu (<span class='gd-jp'>給料が高い反面、仕事がきつい。</span>), nghĩa rất gần với 代わりに, chỉ là mang tính văn viết hơn, thiên về nói hai mặt của cùng một việc.</div><div class='gd-warn'>Mẹo nhận biết: nếu cảm thấy \"đổi bên này lấy bên kia, huề nhau\" thì dùng 代わりに; nếu cảm thấy \"xét theo ～ thì sao lại thế này\" thì dùng わりに.</div>","n3-33":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜っぽい」gần giống kiểu nói <b>「có cảm giác hơi ~」「trông như ~」「kiểu ~」</b> trong tiếng Việt, ví dụ nói một người \"trẻ con\", hay một cái áo \"trông rẻ tiền\". Khi đi sau một số động từ, nghĩa chuyển thành <b>「hay ~」「dễ ~」</b>, ví dụ \"hay quên\", \"dễ nổi nóng\". Đây là cách nói rất khẩu ngữ, bạn sẽ nghe thấy liên tục khi trò chuyện.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Trông như ~</span>Danh từ＋っぽい: thật ra không phải vậy, nhưng cho người ta cảm giác như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう30歳なのに、子供っぽい。</span>(Anh ấy 30 tuổi rồi mà vẫn còn trẻ con)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪っぽい。</span>(Hôm nay hình như hơi bị cảm)</div><div class='gd-sec'><span class='gd-tag'>Ngả màu ~, hơi có chất ~</span>Tính từ い＋っぽい: hay dùng để nói về màu sắc hoặc chất liệu.</div><div class='gd-ex-line'>・<span class='gd-jp'>白っぽいシャツを買った。</span>(Mình đã mua một chiếc áo sơ mi ngả trắng)</div><div class='gd-sec'><span class='gd-tag'>Hay ~, dễ ~</span>Động từ＋っぽい: nói về tính cách của một người.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年を取って、怒りっぽくなった。</span>(Bố lớn tuổi rồi nên trở nên dễ nổi nóng)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は飽きっぽいから、何をしても続かない。</span>(Mình hay chán nên làm gì cũng không bền)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b>: thêm trực tiếp っぽい.<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪っぽい</span>(hình như hơi bị cảm)</span></div><div class='gd-sec'><b>Tính từ い</b>: bỏ い ở cuối, rồi thêm っぽい.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → bỏ い → <span class='gd-jp'>安っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>白い</span> → <span class='gd-jp'>白っぽい</span></span></div><div class='gd-sec'><b>Động từ</b>: chuyển sang thể ます, bỏ ます, rồi thêm っぽい.<br><span class='gd-pair'><span class='gd-jp'>忘れます</span> → bỏ ます → <span class='gd-jp'>忘れっぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>怒ります</span> → <span class='gd-jp'>怒りっぽい</span></span></div><div class='gd-sec'>Sau khi ghép, cả cụm 「〜っぽい」 trở thành một tính từ い, chia giống hệt <span class='gd-jp'>高い</span>:<br><span class='gd-pair'><span class='gd-jp'>忘れっぽい</span> → <span class='gd-jp'>忘れっぽくなった</span>(trở nên hay quên)</span><br><span class='gd-pair'><span class='gd-jp'>子供っぽい</span> → <span class='gd-jp'>子供っぽくない</span>(không trẻ con)</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Với động từ, bạn không thể ghép tùy tiện, những từ hay dùng chỉ có vài từ: <span class='gd-jp'>忘れっぽい</span>、<span class='gd-jp'>怒りっぽい</span>、<span class='gd-jp'>飽きっぽい</span>. Đừng tự chế ra kiểu như <span class='gd-jp'>食べっぽい</span> nhé.<br>・<span class='gd-jp'>安っぽい</span> không có nghĩa là \"rẻ\", mà là \"trông rẻ tiền, quê mùa\", mang nghĩa tiêu cực: <span class='gd-jp'>このバッグは安っぽい。</span>(Cái túi này trông rẻ tiền). Muốn nói giá rẻ thì phải dùng <span class='gd-jp'>安い</span>.<br>・Thường mang giọng chê nhẹ. Nói người lớn <span class='gd-jp'>子供っぽい</span> không phải là khen; ngược lại, nói trẻ con hay người trẻ <span class='gd-jp'>大人っぽい</span> (chín chắn, người lớn) thì thường là lời khen.<br>・Rất khẩu ngữ, ít dùng khi viết báo cáo hay văn bản trang trọng.<br>・Giới trẻ còn gắn っぽい vào sau cả một câu, nghĩa là \"hình như ~\": <span class='gd-jp'>あの店、もう閉まったっぽい。</span>(Quán đó hình như đóng cửa rồi). Cách nói này rất thoải mái, nói với bạn bè thì được, đừng dùng với người lớn tuổi hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>らしい</b>: <span class='gd-jp'>子供らしい</span> là dáng vẻ trẻ con <b>vốn dĩ nên có</b>, thường dùng để khen trẻ con thật sự; <span class='gd-jp'>子供っぽい</span> là <b>rõ ràng không phải trẻ con mà lại giống trẻ con</b>, thường nói về người lớn.<br>・<span class='gd-jp'>元気で子供らしい子だ。</span>(Là đứa trẻ hoạt bát, đúng chất trẻ con)<br>・<span class='gd-jp'>彼は考え方が子供っぽい。</span>(Cách nghĩ của anh ấy rất trẻ con)</div><div class='gd-sec'><b>がち</b>: <span class='gd-jp'>忘れっぽい</span> nói về <b>tính cách của người đó</b>; <span class='gd-jp'>忘れがち</span> nói về <b>một việc hay xảy ra</b>, phía trước có thể nói rõ là quên cái gì.<br>・<span class='gd-jp'>彼は忘れっぽい。</span>(Anh ấy hay quên)<br>・<span class='gd-jp'>私はメールの返事を忘れがちだ。</span>(Mình hay quên trả lời email)</div><div class='gd-sec'><b>気味</b>: <span class='gd-jp'>風邪っぽい</span> và <span class='gd-jp'>風邪気味</span> đều là \"hơi bị cảm\". っぽい thoải mái hơn, nói với bạn bè là đủ; khi xin nghỉ ở công ty hoặc nói với bác sĩ thì dùng <span class='gd-jp'>風邪気味</span> sẽ an toàn hơn.</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"đúng là như vậy, đúng dáng vẻ vốn có\" dùng らしい; \"không phải nhưng trông rất giống\" hoặc \"tính cách hay ~\" dùng っぽい; \"một việc hay xảy ra\" dùng がち.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Cũng nói về xu hướng còn có <span class='gd-jp'>〜がち</span> và <span class='gd-jp'>〜気味</span>. Học cả ba mẫu cùng nhau sẽ dễ phân biệt hơn.</div>","n3-34":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜がち」 tương đương với <b>\"hay ~\", \"dễ ~\", \"thường hay ~\"</b> trong tiếng Việt. Nó nói về một xu hướng <b>thường xuyên xảy ra và thường không tốt lắm</b>, ví dụ dễ bị cảm, hay đi muộn, hay quên.</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪を引きがちだ。</span>(Mùa đông rất dễ bị cảm)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Chuyển sang thể ます, bỏ ます, rồi thêm がち.<br><span class='gd-pair'><span class='gd-jp'>休みます</span> → <span class='gd-jp'>休みがち</span></span>(hay nghỉ)<br><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れがち</span></span>(hay đến muộn, hay bị chậm)<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しがち</span></span>(hay làm)</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Thêm trực tiếp, nhưng chỉ có vài từ cố định hay gặp, không phải danh từ nào cũng ghép được.<br><span class='gd-jp'>病気がち</span>(hay bị ốm)、<span class='gd-jp'>留守がち</span>(hay vắng nhà)、<span class='gd-jp'>曇りがち</span>(trời hay âm u)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>〜がちだ</span>Đặt ở cuối câu, nói ai đó hay việc gì đó thường xuyên như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、食事を抜きがちだ。</span>(Cứ bận là hay bỏ bữa)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は最近、学校を休みがちだ。</span>(Dạo này cậu ấy hay nghỉ học)</div><div class='gd-sec'><span class='gd-tag'>〜がちな＋Danh từ</span>Đứng trước danh từ, cách dùng giống 「静かな部屋」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは初心者にありがちなミスです。</span>(Đây là lỗi người mới bắt đầu hay mắc phải)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không ghép với thể từ điển: phải là <span class='gd-jp'>休みがち</span>, không phải 「休むがち」.<br>・Nó mang sắc thái \"không tốt lắm\", chuyện tốt thường không dùng. Muốn nói \"mình hay học bài\" thì chỉ cần nói <span class='gd-jp'>よく勉強する</span>; nói thành 「勉強しがち」 sẽ rất lạ, nghe như học bài là một thói quen xấu.<br>・Việc chỉ xảy ra một lần thì không dùng được. がち nói về \"hay, dễ\", không phải \"lần này\".<br>・Danh từ không ghép tùy tiện, cứ nhớ vài từ hay gặp như <span class='gd-jp'>病気がち</span>、<span class='gd-jp'>留守がち</span> là đủ.<br>・<span class='gd-jp'>ガチ</span> mà giới trẻ hay nói (nghĩa là “nghiêm túc, siêu cấp”) là từ thịnh hành, hoàn toàn khác với 「〜がち」 ở đây.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>がち</b> = xu hướng <b>hay xảy ra</b>: <span class='gd-jp'>子どものころは病気がちだった。</span>(Hồi nhỏ mình hay bị ốm)<br><b>気味</b> = <b>hiện tại có một chút</b> cảm giác đó: <span class='gd-jp'>今日はちょっと風邪気味だ。</span>(Hôm nay hơi có cảm giác bị cảm)</div><div class='gd-sec'><b>がち</b> = một việc <b>dễ xảy ra</b>: <span class='gd-jp'>人の名前は忘れがちだ。</span>(Tên người khác mình hay quên)<br><b>っぽい</b> = cả con người <b>mang</b> tính chất đó: <span class='gd-jp'>祖父は最近忘れっぽい。</span>(Dạo này ông mình trở nên rất hay quên)</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"thường hay ~\" dùng がち, \"bây giờ hơi ~\" dùng 気味, \"cả con người có cảm giác ~\" dùng っぽい.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Tiếp theo hãy xem <span class='gd-jp'>〜気味</span> và <span class='gd-jp'>〜っぽい</span>. Nhớ ba mẫu này cùng nhau là cách ít nhầm nhất.</div>","n3-47":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ものだ」nghĩa là <b>“vốn dĩ là như vậy mà”, “vốn dĩ phải như thế”</b>. Mẫu này nói về đạo lý hay lẽ thường mà ai cũng đồng ý, chứ không phải ý kiến riêng của bạn. Ngược lại, 「〜ものではない」là kiểu người lớn hay nói: <b>“không được ～”, “làm gì có ai làm vậy”</b>, nghe hơi giáo huấn một chút.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Vốn dĩ là vậy</span>Nói về bản chất tự nhiên của con người, sự vật, hoặc đạo lý ở đời. Thường kèm chút cảm thán kiểu “haizz, đời là vậy mà”.</div><div class='gd-ex-line'>・<span class='gd-jp'>人は誰でも間違えるものだ。</span>（Con người ai cũng có lúc mắc lỗi mà.）</div><div class='gd-ex-line'>・<span class='gd-jp'>時間が経つのは早いものだ。</span>（Thời gian trôi nhanh thật đấy.）</div><div class='gd-sec'><span class='gd-tag'>Vốn dĩ phải</span>Nói về việc “nên làm như vậy” theo lẽ thường của xã hội.</div><div class='gd-ex-line'>・<span class='gd-jp'>お年寄りには親切にするものだ。</span>（Với người lớn tuổi thì phải tử tế.）</div><div class='gd-ex-line'>・<span class='gd-jp'>人の話は最後まで聞くものだ。</span>（Người khác nói thì phải nghe đến cuối.）</div><div class='gd-sec'><span class='gd-tag'>Không nên</span>Dùng「〜ものではない」để khuyên nhủ, nhắc nhở người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ物を粗末にするものではない。</span>（Không được phí phạm đồ ăn.）</div><div class='gd-sec'><span class='gd-tag'>Hoài niệm quá khứ</span>Dùng「thể た＋ものだ」để nói về việc trước đây mình <b>thường xuyên</b> làm, mang cảm giác hoài niệm kiểu “hồi đó ấy mà～”. Hay đi chung với「よく」.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃は、よくこの川で遊んだものだ。</span>（Hồi nhỏ mình hay chơi ở con sông này lắm.）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ thể từ điển：<span class='gd-pair'><span class='gd-jp'>間違える</span> → <span class='gd-jp'>間違えるものだ</span></span><br>Động từ thể ない：<span class='gd-pair'><span class='gd-jp'>変わらない</span> → <span class='gd-jp'>変わらないものだ</span></span><br>Tính từ い nối trực tiếp：<span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>Tính từ な phải thêm な：<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なものだ</span></span><br>Hoài niệm quá khứ dùng thể た：<span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>Khi nói “không nên” dùng thể từ điển：<span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うものではない</span></span></div><div class='gd-sec'>Trong khẩu ngữ hay rút gọn thành <b>もんだ</b>、<b>もんじゃない</b>：<span class='gd-jp'>そんなこと言うもんじゃないよ。</span>（Không được nói vậy đâu nhé.）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・ものだ nói về <b>đạo lý ai cũng công nhận</b>, không dùng để nói dự định của riêng bạn trong một lần cụ thể. “Ngày mai mình đi học” thì nói <span class='gd-jp'>明日学校へ行きます</span>, không thêm ものだ.<br>・「ないものだ」và「ものではない」có nghĩa khác nhau: <span class='gd-jp'>人は簡単には変わらないものだ</span> là “con người vốn dĩ không dễ thay đổi” (nói về bản tính); <span class='gd-jp'>人の悪口を言うものではない</span> là “không nên nói xấu người khác” (khuyên nhủ).<br>・Cách dùng hoài niệm nói về việc <b>trước đây thường xuyên làm</b>, việc chỉ làm một lần thì không dùng được: hôm qua ăn ramen thì nói <span class='gd-jp'>昨日ラーメンを食べた</span>, không thêm ものだ.<br>・ものではない là giọng răn dạy, nói với cấp trên hay thầy cô sẽ rất thất lễ. Thường là người lớn nói với người nhỏ, cha mẹ nói với con.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'>Cùng là “nên”, nhưng khác nhau ở chỗ lập trường của người nói:<br><b>ものだ</b>＝<b>lẽ thường của xã hội</b> vốn là như vậy, nói về đạo lý chung：<span class='gd-jp'>約束は守るものだ。</span>（Đã hứa thì phải giữ lời.）<br><b>べきだ</b>＝<b>người nói tự đánh giá</b> là nên làm vậy, giọng trực tiếp và mạnh hơn：<span class='gd-jp'>あなたはこの約束を守るべきだ。</span>（Bạn nên giữ lời hứa này.）<br><b>ことだ</b>＝<b>đưa lời khuyên</b> cho người trước mặt, “tốt nhất là ～”：<span class='gd-jp'>約束を守りたいなら、メモしておくことだ。</span>（Muốn giữ lời hứa thì tốt nhất là ghi chú lại trước.）</div><div class='gd-warn'>Mẹo phân biệt: nói “con người vốn dĩ phải thế nào” thì dùng ものだ; nói “tôi thấy bạn nên” thì dùng べきだ; khuyên đối phương “bạn tốt nhất là ～” thì dùng ことだ. Ngoài ra <span class='gd-jp'>ものだから</span> là nói lý do (vì ～ mà), không phải cùng một thứ với ものだ ở đây.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Những mẫu cũng dùng để nói đạo lý, khuyên nhủ còn có「〜べきだ・〜べきではない」và「〜ことだ」. Bạn có thể học tiếp, đặt cả ba cạnh nhau để so sánh thì sẽ rõ khi nào dùng cái nào.</div>","n3-1":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜において」nghĩa là <b>“tại ～”</b>. Trong tiếng Việt, bình thường mình nói “họp ở Đài Bắc”, nhưng trong văn bản trang trọng sẽ thành “cuộc họp được tổ chức <b>tại</b> Đài Bắc”. Tiếng Nhật cũng vậy: hằng ngày nói「<span class='gd-jp'>台北で</span>」, còn trong văn viết trang trọng, tin tức, bài phát biểu thì đổi thành「<span class='gd-jp'>台北において</span>」. Nghĩa đều là “ở ～”, chỉ là <b>trang trọng hơn nhiều</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Ở đâu</span>Sự kiện, buổi lễ diễn ra ở địa điểm nào, thường gặp nhất trong tin tức.</div><div class='gd-ex-line'>・<span class='gd-jp'>開会式は台北において行われた。</span>（Lễ khai mạc được tổ chức tại Đài Bắc.）</div><div class='gd-sec'><span class='gd-tag'>Trong hoàn cảnh nào</span>Những “bối cảnh” như cuộc họp, buổi phỏng vấn, trận đấu.</div><div class='gd-ex-line'>・<span class='gd-jp'>面接において、一番大切なのは第一印象だ。</span>（Trong phỏng vấn, điều quan trọng nhất là ấn tượng đầu tiên.）</div><div class='gd-sec'><span class='gd-tag'>Trong lĩnh vực nào</span>Một lĩnh vực, một phương diện nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>医療の分野において、AIの活用が進んでいる。</span>（Trong lĩnh vực y tế, việc ứng dụng AI ngày càng phổ biến.）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước luôn là <b>danh từ</b>, điểm mấu chốt là <b>phía sau nối với gì</b>：<br><b>Phía sau là động từ, cả câu</b> → dùng <b>において</b><br><span class='gd-pair'><span class='gd-jp'>京都で開催された</span> → <span class='gd-jp'>京都において開催された</span></span>（được tổ chức tại Kyoto）<br><b>Phía sau là danh từ trực tiếp</b> → dùng <b>における</b>, có vai trò như “ở ～” bổ nghĩa cho danh từ, giống「<span class='gd-jp'>での</span>」<br><span class='gd-pair'><span class='gd-jp'>日本での問題</span> → <span class='gd-jp'>日本における問題</span></span>（vấn đề ở Nhật Bản）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本における外国人労働者の数は年々増えている。</span>（Số lao động nước ngoài ở Nhật Bản tăng lên từng năm.）</div><div class='gd-sec'>Phía sau cũng hay thêm「は」「も」để nhấn mạnh：</div><div class='gd-ex-line'>・<span class='gd-jp'>この点においては、私も同じ意見です。</span>（Ở điểm này, tôi cũng có cùng ý kiến.）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Chuyện nhỏ hằng ngày đừng dùng</b>：<span class='gd-jp'>コンビニにおいてパンを買った</span> nghe như văn bản hành chính, rất lạ. Nói về sinh hoạt của mình thì dùng <span class='gd-jp'>コンビニでパンを買った</span> là đủ.<br>・<b>Khi phía sau là danh từ, đừng quên đổi thành における</b>：không thể nói “日本において経済”, phải nói <span class='gd-jp'>日本における経済</span>.<br>・Nó chỉ thay thế で chỉ <b>nơi chốn, hoàn cảnh</b>. で chỉ phương tiện thì không đổi được：<span class='gd-jp'>はしで食べる</span>（ăn bằng đũa）không thể nói thành「はしにおいて」.<br>・Khi nói “ở đâu <b>có</b> cái gì” thì dùng に chứ không phải で, nên cũng không thể đổi thành において：phải nói <span class='gd-jp'>公園に子どもがいる</span>.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'><b>で</b>＝dùng được cả khẩu ngữ lẫn hằng ngày：<span class='gd-jp'>会議で決まりました。</span>（Đã quyết định trong cuộc họp.）<br><b>において</b>＝cách nói trang trọng của cùng một việc：<span class='gd-jp'>会議において決定されました。</span>（Đã được quyết định tại cuộc họp.）</div><div class='gd-sec'><b>について</b>trông giống nhưng nghĩa hoàn toàn khác, là “<b>về ～</b>”, nói về nội dung, chủ đề. Xem câu này, cả hai xuất hiện cùng lúc：</div><div class='gd-ex-line'>・<span class='gd-jp'>会議において、環境問題について話し合った。</span>（Trong cuộc họp, đã thảo luận về vấn đề môi trường.）</div><div class='gd-sec'>「会議」là thảo luận <b>ở đâu</b>, 「環境問題」là thảo luận <b>về cái gì</b>.</div><div class='gd-warn'>Mẹo phân biệt: nếu tiếng Việt nói được “tại ～”, “ở ～” thì là において; nếu là “về ～”, “liên quan đến ～” thì là について.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mô hình「〜て」đi với động từ, 「〜る」đi với danh từ có ở rất nhiều mẫu ngữ pháp, như <span class='gd-jp'>〜に関して／〜に関する</span>、<span class='gd-jp'>〜によって／〜による</span>. Hiểu mẫu này rồi thì mấy mẫu kia sẽ dễ hơn nhiều.</div>","n3-7":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜せいで」nghĩa là <b>“tại ~”, “đều do ~ mà ra”</b>. Khi kết quả không tốt và bạn muốn nói rõ cái gì gây ra, hãy dùng mẫu này.<br>Đổi thành「〜せいか」thì giọng nhẹ đi một bậc, thành <b>“có lẽ là do ~ chăng”</b>, nghĩa là chính bạn cũng không chắc về nguyên nhân.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>せいで</span>Kết quả không tốt, và bạn khá chắc ai hoặc cái gì là nguyên nhân. Câu mang chút sắc thái trách móc, phàn nàn.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のせいで、試合が中止になった。</span>（Tại trời mưa nên trận đấu bị hủy）</div><div class='gd-ex-line'>・<span class='gd-jp'>私が寝坊したせいで、みんなを待たせてしまった。</span>（Tại mình ngủ quên nên bắt mọi người phải chờ）</div><div class='gd-sec'><span class='gd-tag'>せいか</span>Chỉ là đoán nguyên nhân, chưa chắc đã đúng như vậy. Tiếng Việt hay nói là “có lẽ là do ~ chăng”.</div><div class='gd-ex-line'>・<span class='gd-jp'>年のせいか、最近疲れやすい。</span>（Có lẽ do tuổi tác, dạo này mình dễ mệt）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足のせいか、頭がぼんやりする。</span>（Có lẽ do thiếu ngủ, đầu óc cứ mơ màng）</div><div class='gd-sec'><span class='gd-tag'>Đặt cuối câu</span>Đưa nguyên nhân ra nói sau cùng, thành “là do ~ đấy”.</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したのは準備不足のせいだ。</span>（Thất bại là do chuẩn bị chưa đủ）</div><div class='gd-ex-line'>・<span class='gd-jp'>私のせいです。すみません。</span>（Là lỗi của mình. Xin lỗi nhé）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>「せい」bản thân là danh từ, nên cách nối phía trước giống như với danh từ.<br><b>Danh từ</b>: thêm「の」<span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪のせいで</span></span><br><b>Tính từ な</b>: thêm「な」<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なせいで</span></span><br><b>Tính từ い</b>: nối trực tiếp<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いせいで</span></span><br><b>Động từ</b>: dùng thể thường (dạng không có ます), thể quá khứ cũng được<span class='gd-pair'><span class='gd-jp'>食べすぎた</span> → <span class='gd-jp'>食べすぎたせいで</span></span><br>せいか nối hoàn toàn giống vậy, chỉ cần đổi で thành か.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ nhất định phải thêm「の」: đúng là <span class='gd-jp'>雪のせいで</span>, không phải「雪せいで」.<br>・Tính từ な phải dùng「な」, không được nối với「だ」: đúng là <span class='gd-jp'>暇なせいか</span>, không phải「暇だせいか」.<br>・<b>Kết quả tốt thì đừng dùng せいで</b>. “Nhờ thầy cô mà mình đỗ” phải dùng おかげで. Nếu dùng せいで thì thành bạn đang trách thầy cô vì để bạn đỗ, nghe rất kỳ.<br>・Nói thẳng mặt <span class='gd-jp'>あなたのせいで</span> là đang chỉ trích đối phương trực tiếp, giọng rất nặng, nên dùng cẩn thận.<br>・<span class='gd-jp'>気のせいだよ</span> mà bạn hay nghe là cách nói cố định, nghĩa là “bạn nghĩ nhiều thôi mà”.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Cùng là “vì trời mưa”, nhưng kết quả khác nhau thì từ dùng cũng khác:<br><b>せいで</b>＝kết quả xấu, đổ lỗi cho nó: <span class='gd-jp'>雨のせいで、花火大会が中止になった。</span>（Tại trời mưa nên lễ hội pháo hoa bị hủy）<br><b>おかげで</b>＝kết quả tốt, cảm ơn nó: <span class='gd-jp'>雨のおかげで、涼しくなった。</span>（Nhờ có mưa mà trời mát hẳn）<br>Ngược lại, dùng <span class='gd-jp'>おかげで</span> cho kết quả xấu là đang mỉa mai: <span class='gd-jp'>君のおかげで、また怒られたよ。</span>（Nhờ phúc của cậu mà tớ lại bị mắng rồi đấy）</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn nói “tại ~” thì dùng せいで, muốn nói “nhờ ~” thì dùng おかげで; còn nguyên nhân chưa chắc, chỉ đoán thôi thì dùng せいか.</div>","n3-9":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「とともに」viết bằng chữ Hán là「と共に」, nghĩa gần với <b>“cùng với ~”</b> và <b>“theo đà ~”</b> trong tiếng Việt. Đây là cách nói khá <b>trang trọng, văn viết</b>, hay gặp trong tin tức, diễn văn, bài viết, lời phát biểu. Cảm giác giống như tiếng Việt nói “cùng với gia đình”, “cùng với sự thay đổi của thời đại”, ít khi dùng khi trò chuyện hằng ngày.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cùng nhau</span>Làm việc gì đó cùng với ai, là bản trang trọng của「と一緒に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とともに新居で新年を迎えた。</span>（Đón năm mới ở nhà mới cùng với gia đình）</div><div class='gd-ex-line'>・<span class='gd-jp'>チームの仲間とともに優勝を喜んだ。</span>（Cùng với đồng đội vui mừng vì giành chức vô địch）</div><div class='gd-sec'><span class='gd-tag'>Theo đà</span>Việc ở vế trước thay đổi thì việc ở vế sau cũng thay đổi theo. Đây là cách dùng hay ra thi nhất ở N3.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢とともに体力が落ちてきた。</span>（Cùng với tuổi tác, thể lực yếu dần đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>人口が減るとともに、町の店も少なくなった。</span>（Dân số giảm, các cửa hàng trong thị trấn cũng ít dần）</div><div class='gd-sec'><span class='gd-tag'>Đồng thời</span>Vào lúc A xảy ra thì B cũng xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>ベルが鳴るとともに、子どもたちは教室を飛び出した。</span>（Chuông vừa reo là bọn trẻ lao ra khỏi lớp）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族とともに</span></span><span class='gd-pair'><span class='gd-jp'>技術の発展</span> → <span class='gd-jp'>技術の発展とともに</span></span><br><b>Động từ thể từ điển (dạng nguyên mẫu tra trong từ điển)＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるとともに</span></span><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るとともに</span></span><br>Nâng cao một chút: <b>danh từ＋であるとともに</b>＝“vừa là ~, đồng thời cũng là ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者であるとともに、作家でもある。</span>（Anh ấy là bác sĩ, đồng thời cũng là nhà văn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này rất trang trọng. Nói với bạn bè <span class='gd-jp'>友達とともにラーメンを食べた</span> nghe như đang đọc công văn, trong hội thoại hãy dùng <span class='gd-jp'>友達と一緒に</span>.<br>・Với nghĩa “theo đà”, vế sau phải nói <b>“trở nên như thế nào”</b>, không thể chỉ nêu một thói quen cố định: ×<span class='gd-jp'>年をとるとともに、毎日運動している</span>　○<span class='gd-jp'>年をとるとともに、運動する時間が増えた</span>.<br>・Động từ luôn dùng thể từ điển, kể cả khi việc đã xảy ra rồi; thì quá khứ đặt ở cuối câu: ×<span class='gd-jp'>増えたとともに</span>　○<span class='gd-jp'>人口が増えるとともに、町がにぎやかになった</span>.<br>・Phía trước là「と」chứ không phải「に」: <span class='gd-jp'>家族とともに</span>, không phải 家族にともに.<br>・Trong sách báo hay viết bằng chữ Hán là <span class='gd-jp'>と共に</span>, cả hai cách viết đều đúng.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>と一緒に</b>＝“cùng nhau” trong đời sống, văn nói: <span class='gd-jp'>家族と一緒に旅行した。</span>（Mình đã đi du lịch cùng gia đình）<br><b>とともに</b>＝“cùng nhau” bản trang trọng: <span class='gd-jp'>家族とともに旅行した。</span>（Nghĩa giống nhau, nhưng giống cách viết trong bài văn hay tin tức）<br>Ngoài ra, <span class='gd-jp'>と一緒に</span> không có nghĩa “theo đà”, nên không thể nói ×<span class='gd-jp'>年齢と一緒に体力が落ちた</span>.</div><div class='gd-sec'><b>につれて</b>＝chỉ có nghĩa “theo đà”: <span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>（Càng lớn tuổi, thể lực càng yếu đi）<br><b>とともに</b>＝cũng nói được “theo đà”, giọng trang trọng hơn: <span class='gd-jp'>年をとるとともに、体力が落ちてきた。</span><br>Khác biệt là <span class='gd-jp'>につれて</span> không dùng được cho nghĩa “cùng nhau” hay “đồng thời”, còn <span class='gd-jp'>とともに</span> dùng được cả ba nghĩa.</div><div class='gd-warn'>Mẹo nhỏ để chọn: nói “cùng nhau” trong đời thường thì dùng と一緒に; nói “theo đà” thì につれて và とともに đều được, càng trang trọng càng nghiêng về とともに; muốn nói “cùng nhau” hoặc “đồng thời” mà lại cần trang trọng thì chọn とともに.</div>","n3-4":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「によって」gần giống <b>「nhờ ～」「do ～」「tùy vào ～」「bởi ～」</b> trong tiếng Việt. Phía trước đặt một danh từ, cho biết việc đó được thực hiện nhờ nó, do nó gây ra, hoặc phải xem nó thế nào mới biết. Vì thế khi dịch sang tiếng Việt, tùy ngữ cảnh sẽ là 「thông qua」「do」「tùy ～ mà khác」「bởi」. Mẫu này đặc biệt hay gặp trong tin tức, văn bản giải thích và những dịp trang trọng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước luôn nối thẳng với <b>danh từ</b>, không thêm「の」. Phần phía sau quyết định bạn dùng dạng nào:<br>Phía sau là hành động, cả một câu → <b>によって</b>：<span class='gd-jp'>台風によって電車が止まった。</span>（Do bão, tàu điện đã ngừng chạy）<br>Phía sau nối thẳng với danh từ → <b>による</b>：<span class='gd-jp'>台風による停電</span>（mất điện do bão）<br>Trong văn viết bạn cũng hay thấy「<span class='gd-jp'>により</span>」, nghĩa giống によって, chỉ là trang trọng hơn.</div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Tùy ～ mà khác</span>「Tùy vào ～, mỗi ～ một khác」. Phía sau gần như luôn là những từ chỉ sự \"khác nhau\" như <span class='gd-jp'>違う</span>、<span class='gd-jp'>異なる</span>、<span class='gd-jp'>変わる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>地域によって食文化が異なる。</span>（Văn hóa ẩm thực khác nhau tùy theo vùng）</div><div class='gd-ex-line'>・<span class='gd-jp'>人によって考え方が違う。</span>（Mỗi người một cách nghĩ khác nhau）</div><div class='gd-sec'><span class='gd-tag'>Nguyên nhân</span>「Vì ～, do ～ gây ra」, giọng khách quan, như đang đưa tin trên báo đài.</div><div class='gd-ex-line'>・<span class='gd-jp'>台風による停電が続いている。</span>（Tình trạng mất điện do bão vẫn đang tiếp diễn）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故によって電車が遅れています。</span>（Do sự cố, tàu điện đang bị chậm）</div><div class='gd-sec'><span class='gd-tag'>Phương tiện・cách thức</span>「Thông qua ～」, cách nói khá trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は話し合いによって解決した。</span>（Vấn đề này đã được giải quyết thông qua thương lượng）</div><div class='gd-sec'><span class='gd-tag'>\"Bởi ai\" trong câu bị động</span>Dùng để nói tác phẩm, phát minh, công trình kiến trúc do ai làm ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説は有名な作家によって書かれた。</span>（Cuốn tiểu thuyết này được viết bởi một nhà văn nổi tiếng）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話はベルによって発明された。</span>（Điện thoại được Bell phát minh）</div><div class='gd-sec'><span class='gd-tag'>によっては</span>Thêm một chữ「は」, nghĩa thành <b>「có những ～ thì…」</b>, chỉ chọn ra một phần trong số đó để nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>店によって値段が違う。</span>（Giá cả mỗi cửa hàng một khác）</div><div class='gd-ex-line'>・<span class='gd-jp'>店によっては、カードが使えない。</span>（Có những cửa hàng không dùng được thẻ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Câu bị động không phải lúc nào cũng dùng によって</b>. Kiểu \"bị ai mắng, bị ai nói\" trong đời thường dùng「に」：<span class='gd-jp'>母に叱られた。</span>（Bị mẹ mắng）, nói thành「母によって叱られた」nghe rất lạ. によって dành cho trường hợp \"ai đó tạo ra một thứ gì đó\".<br>・<b>Phương tiện trong đời thường chỉ cần dùng「で」</b>：<span class='gd-jp'>バスで行く</span>, không nói「バスによって行く」. 「Thông qua」của によって thiên về trang trọng, dùng cho những việc lớn hơn như phương pháp, chế độ.<br>・<b>Sau による bắt buộc phải là danh từ</b>. Nếu phía sau là một câu thì quay lại dùng によって, đừng viết thành「台風による電車が止まった」.<br>・「Tùy ～ mà khác」và「có những ～ thì…」chỉ khác nhau một chữ「は」nhưng nghĩa đã khác, nên hãy nhìn kỹ xem có chữ「は」đó hay không.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là \"vì bão\" nhưng sắc thái khác nhau rất nhiều:<br><b>によって</b>＝nói nguyên nhân một cách khách quan, không mang cảm xúc：<span class='gd-jp'>台風によって電車が止まった。</span>（Do bão, tàu điện đã ngừng chạy）<br><b>せいで</b>＝đổ lỗi cho nó, mang ý phàn nàn：<span class='gd-jp'>台風のせいで旅行に行けなかった。</span>（Tại bão mà mình không đi du lịch được）<br><b>おかげで</b>＝nhờ có nó, mang ý may mắn hoặc biết ơn：<span class='gd-jp'>台風のおかげで学校が休みになった。</span>（Nhờ bão mà trường được nghỉ）<br>Khi nối với danh từ, せいで và おかげで phía trước phải thêm「の」（<span class='gd-jp'>雨のせいで</span>）, còn によって nối thẳng với danh từ, không thêm「の」（<span class='gd-jp'>雨によって</span>）.</div><div class='gd-warn'>Mẹo nhỏ để chọn: nói nguyên nhân một cách bình thản như tin tức thì dùng によって, muốn phàn nàn thì dùng せいで, thấy may mắn thì dùng おかげで.</div>","n3-6":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜おかげで」chính là <b>「nhờ có ～」「nhờ phúc của ～」「may mà có ～」</b> trong tiếng Việt. Phía trước đặt nguyên nhân mang lại kết quả tốt, phía sau nói kết quả tốt đó, trong giọng nói có chút biết ơn.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cảm ơn ai đó</span>Nhờ có ai đó giúp đỡ nên mọi việc mới suôn sẻ.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生のおかげで、合格できました。</span>（Nhờ có thầy/cô, em đã đỗ rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が手伝ってくれたおかげで、早く終わった。</span>（Nhờ bạn giúp mà làm xong rất nhanh）</div><div class='gd-sec'><span class='gd-tag'>Nguyên nhân tốt</span>Không nhất thiết phải là người, thời tiết, môi trường, đồ vật đều được, miễn là nó mang lại kết quả tốt.</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだおかげで、熱が下がった。</span>（Nhờ uống thuốc này mà hết sốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅が近いおかげで、通勤が楽です。</span>（May mà gần ga nên đi làm rất nhẹ nhàng）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>：thêm「の」ở giữa.<br><span class='gd-pair'><span class='gd-jp'>先輩</span> → <span class='gd-jp'>先輩のおかげで</span></span></div><div class='gd-sec'><b>Động từ</b>：nối thẳng với thể thông thường (thể từ điển, thể た… tức là dạng không có ます). Kết quả tốt thường đã xảy ra rồi nên hay dùng nhất là thể た.<br><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったおかげで</span></span></div><div class='gd-sec'><b>Tính từ đuôi い</b>：nối thẳng.<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>よかった</span> → <span class='gd-jp'>よかったおかげで</span></span></div><div class='gd-sec'><b>Tính từ đuôi な</b>：thì hiện tại thêm「な」, thì quá khứ dùng「だった」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>元気だった</span> → <span class='gd-jp'>元気だったおかげで</span></span></div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>おかげさまで</span>Khi người khác hỏi thăm, bạn đáp lịch sự một câu kiểu \"nhờ phúc của anh/chị\", dù đối phương thực ra chẳng giúp gì cụ thể cũng nói được.</div><div class='gd-ex-line'>・<span class='gd-jp'>お元気ですか。</span>——<span class='gd-jp'>おかげさまで、元気です。</span>（Bạn khỏe không? — Nhờ phúc của bạn, mình khỏe）</div><div class='gd-sec'><span class='gd-tag'>〜のおかげです</span>Đặt ở cuối câu, dành công cho ai đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のおかげです。</span>（Em đỗ được là hoàn toàn nhờ thầy/cô）</div><div class='gd-sec'><span class='gd-tag'>Mỉa mai</span>Giống như trong tiếng Việt ta nói mỉa \"nhờ phúc của cậu đấy nhé\", bạn cũng có thể cố tình dùng để châm chọc khi kết quả thực ra là chuyện xấu.</div><div class='gd-ex-line'>・<span class='gd-jp'>君のおかげで、全部やり直しだよ。</span>（Nhờ phúc của cậu, phải làm lại hết từ đầu rồi đấy）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải có「の」：phải là <span class='gd-jp'>先生のおかげで</span>, không được nói 先生おかげで.<br>・Tính từ đuôi な ở thì hiện tại không được nối với「だ」：phải là <span class='gd-jp'>静かなおかげで</span>, không phải 静かだおかげで.<br>・Phía sau phải là <b>kết quả đã xảy ra, hoặc chắc chắn sẽ xảy ra</b>, không được dùng câu rủ rê hay nhờ vả kiểu「～nhé」「xin hãy ～」.<br>・Tiếng Việt dùng \"vì\", \"do\" khá thoải mái, nhưng không phải \"vì\" nào cũng đổi được sang おかげで. Nếu chỉ đơn thuần nêu nguyên nhân (ví dụ vì trời mưa nên trận đấu bị hủy) thì phải dùng <span class='gd-jp'>から</span>、<span class='gd-jp'>ので</span>; dùng おかげで nghe sẽ như bạn đang vui vì trận đấu bị hủy.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>おかげで</b>＝nhờ có ～, kết quả là <b>chuyện tốt</b>, mang ý biết ơn:<br><span class='gd-jp'>雨が降ったおかげで、涼しくなった。</span>（Nhờ trời mưa mà trời mát hẳn）<br><b>せいで</b>＝tại ～ mà ra, kết quả là <b>chuyện xấu</b>, mang ý phàn nàn, đổ lỗi:<br><span class='gd-jp'>雨が降ったせいで、試合が中止になった。</span>（Tại trời mưa mà trận đấu bị hủy）<br>Hai mẫu này cách nối hoàn toàn giống nhau, khác biệt chỉ ở chỗ bạn biết ơn hay phàn nàn về kết quả.</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn nói \"nhờ có, may mà có\" thì dùng おかげで; muốn nói \"tại ～ mà ra\" thì dùng せいで; chỉ đơn thuần nêu nguyên nhân, không có cảm xúc tốt xấu thì dùng から・ので.</div>","n3-10":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'><span class='gd-jp'>ところ</span>vốn có nghĩa là “nơi chốn”, nhưng ở đây nó là <b>“một điểm trên trục thời gian”</b>. Một việc có ba giai đoạn: <b>chưa bắt đầu, đang làm dở, vừa làm xong</b>. <span class='gd-jp'>ところだ</span> là cách nói cho người nghe biết bạn đang đứng ở “ô” nào, gần giống “sắp…”, “đang…”, “vừa mới…” trong tiếng Việt.</div><div class='gd-h'>Cách chia: dạng đứng trước quyết định bạn đang ở “ô” nào</div><div class='gd-sec'><span class='gd-tag'>Sắp làm</span>Thể từ điển (dạng nguyên thể trong từ điển) ＋ところだ. Việc <b>chưa bắt đầu</b>, nhưng sắp làm ngay.</div><div class='gd-ex-line'>・<span class='gd-jp'>今から出かけるところです。</span>（Tôi sắp ra ngoài.）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：もうご飯食べた？　B：ううん、これから食べるところ。</span>（A: Ăn cơm chưa? B: Chưa, đang chuẩn bị ăn đây.）</div><div class='gd-sec'><span class='gd-tag'>Đang làm</span>Thể て ＋ いる ＋ ところだ. Việc <b>đang làm dở</b>, chưa xong.</div><div class='gd-ex-line'>・<span class='gd-jp'>今シャワーを浴びているところだから、あとでかけ直すね。</span>（Tôi đang tắm, lát nữa gọi lại cho bạn nhé.）</div><div class='gd-ex-line'>・<span class='gd-jp'>今調べているところなので、少々お待ちください。</span>（Hiện tôi đang kiểm tra, xin vui lòng đợi một chút.）</div><div class='gd-sec'><span class='gd-tag'>Vừa làm xong</span>Thể た (quá khứ) ＋ ところだ. Việc <b>vừa mới</b> kết thúc.</div><div class='gd-ex-line'>・<span class='gd-jp'>たった今、家に帰ってきたところです。</span>（Tôi vừa mới về đến nhà.）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議がちょうど終わったところです。</span>（Cuộc họp vừa mới kết thúc.）</div><div class='gd-sec'>Đặt cùng một động từ cạnh nhau là dễ thấy nhất:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところ</span></span>（sắp ăn）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べているところ</span></span>（đang ăn）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたところ</span></span>（vừa ăn xong）<br>Với người lớn tuổi, khách hàng thì dùng <span class='gd-jp'>ところです</span>; với bạn bè có thể nói thẳng <span class='gd-jp'>ところ</span>, còn <span class='gd-jp'>ているところ</span> trong văn nói hay được rút gọn thành <span class='gd-jp'>てるところ</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Hay gặp nhất khi ai đó hỏi “bạn đang làm gì đấy”, khi nói chuyện điện thoại, khi nhắn tin trả lời, để báo <b>tình trạng của bạn ngay lúc này</b>. Nó thường đi cùng <span class='gd-jp'>これから</span>, <span class='gd-jp'>今から</span> (sắp), <span class='gd-jp'>今</span> (đang), <span class='gd-jp'>たった今</span>, <span class='gd-jp'>ちょうど</span> (vừa). Thấy những từ này là bạn biết đang ở “ô” nào.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Thể từ điển ＋ところ là <b>chưa bắt đầu</b>. <span class='gd-jp'>今食べるところ</span> nghĩa là “sắp ăn”, không phải “đang ăn”; muốn nói đang ăn thì phải dùng <span class='gd-jp'>食べているところ</span>.<br>・ているところ chỉ dùng cho <b>hành động thật sự đang diễn ra</b>. Những từ chỉ trạng thái như <span class='gd-jp'>住んでいる</span>, <span class='gd-jp'>知っている</span> thì không thể nói 「住んでいるところだ」.<br>・たところ là <b>thật sự vừa mới xảy ra</b>. Không thể nói 「先月日本に来たところだ」, vì tháng trước không còn là “vừa mới” nữa; lúc này phải dùng たばかり (xem bên dưới).<br>・<span class='gd-jp'>ところだ</span> đặt ở cuối câu mới mang nghĩa này. Còn 「〜たところ、…」 có dấu phẩy rồi nói tiếp thì là một mẫu ngữ pháp khác (làm thử ~ thì kết quả là…), đừng nhầm nhé.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>たところだ</b> và <b>たばかりだ</b> đều dịch là “vừa mới ~”, khác nhau ở chỗ “vừa” đến mức nào.<br><b>たところだ</b>: mốc thời gian chính là ngay lúc nãy, cỡ vài phút trước.<br><span class='gd-jp'>今、駅に着いたところです。</span>（Tôi vừa đến ga.）<br><b>たばかりだ</b>: người nói <b>cảm thấy</b> chưa lâu lắm, vài ngày hay vài tháng đều được.<br><span class='gd-jp'>先月日本に来たばかりです。</span>（Tháng trước tôi mới đến Nhật.）<br>Ngoài ra, たばかり hay mang sắc thái “mới ~ mà đã…”: <span class='gd-jp'>買ったばかりなのに、もう壊れた。</span>（Mới mua mà đã hỏng rồi.）</div><div class='gd-warn'>Mẹo phân biệt: nếu thay được bằng “ngay giây phút vừa rồi” thì dùng たところ; nếu muốn nói “cách đây chưa lâu, vẫn còn cảm giác mới” thì dùng たばかり. Khi không chắc, hễ khoảng thời gian dài hơn một ngày thì dùng たばかり.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thể từ điển ＋<span class='gd-jp'>ところだった</span> = suýt nữa thì ~ (may là chưa xảy ra): <span class='gd-jp'>もう少しで電車に乗り遅れるところだった。</span>（Suýt nữa thì lỡ chuyến tàu.）</div>","n3-11":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たばかり」 nghĩa là <b>“vừa mới ~”, “~ chưa được bao lâu”</b>. Điểm mấu chốt là bạn <b>cảm thấy</b> thời gian còn ngắn, nên câu này hay mang tâm trạng kiểu “chưa quen”, “sao lại ~ nữa rồi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだ慣れない。</span>（Mới đến Nhật nên vẫn chưa quen.）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Luôn đi với <b>thể た</b> của động từ (quá khứ, như <span class='gd-jp'>食べた</span>, <span class='gd-jp'>行った</span>), rồi thêm ばかり.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たばかり</span></span></div><div class='gd-h'>Những dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Cuối câu</span>〜たばかりだ／〜たばかりです</div><div class='gd-ex-line'>・<span class='gd-jp'>先月結婚したばかりです。</span>（Tháng trước tôi mới kết hôn.）</div><div class='gd-sec'><span class='gd-tag'>Còn nói tiếp</span>〜たばかりで, giải thích “vì mới ~ nên…”</div><div class='gd-ex-line'>・<span class='gd-jp'>起きたばかりで、頭がぼんやりしている。</span>（Mới ngủ dậy nên đầu óc vẫn còn lơ mơ.）</div><div class='gd-sec'><span class='gd-tag'>Bổ nghĩa danh từ</span>〜たばかりの＋danh từ</div><div class='gd-ex-line'>・<span class='gd-jp'>これは買ったばかりの靴です。</span>（Đây là đôi giày tôi mới mua.）</div><div class='gd-sec'><span class='gd-tag'>Phàn nàn, bất ngờ</span>〜たばかりなのに, “mới ~ mà sao đã…”</div><div class='gd-ex-line'>・<span class='gd-jp'>さっき食べたばかりなのに、もうお腹がすいた。</span>（Mới ăn xong mà đã đói bụng rồi.）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định phải là thể た. Nếu viết <span class='gd-jp'>来るばかり</span>, <span class='gd-jp'>食べるばかり</span> thì nghĩa sẽ khác hẳn (phần dưới sẽ nói).<br>・Khi bổ nghĩa cho danh từ phải dùng <b>の</b>: là <span class='gd-jp'>買ったばかりの靴</span>, không phải 買ったばかり靴.<br>・“Mới” ngắn hay dài là tùy cảm nhận của bạn: <span class='gd-jp'>去年入社したばかりです</span> (Năm ngoái tôi mới vào công ty) nói thế dù đã một năm trước vẫn hoàn toàn bình thường.<br>・Giữa bạn bè hay nói thành <span class='gd-jp'>たばっか</span>: <span class='gd-jp'>今起きたばっか。</span>（Tôi vừa mới dậy.）</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>〜たところだ</b> (xem ところだ ở n3-10) cũng dịch là “vừa mới ~”, nhưng nó nói về <b>thời điểm hành động vừa kết thúc</b>, thật sự chỉ cách đây vài giây, vài phút.<br>・<span class='gd-jp'>今、駅に着いたところです。</span>（Tôi vừa đến ga xong.）<br>・<span class='gd-jp'>今、駅に着いたばかりです。</span>（Tôi mới đến ga thôi.）<br>Trong tình huống “vừa xong ngay lúc nãy” thì dùng cái nào cũng được. Nhưng khi khoảng thời gian kéo dài hơn thì chỉ dùng được たばかり:<br>・<span class='gd-jp'>先月引っ越したばかりです。</span>（Tháng trước tôi mới chuyển nhà.）○<br>・<span class='gd-jp'>先月引っ越したところです。</span> ×</div><div class='gd-sec'><b>Đổi dạng đứng trước ばかり thì nghĩa cũng đổi</b>:<br><b>Thể từ điển ＋ばかり</b> phần lớn diễn tả “cứ thay đổi mãi theo một hướng (ngày càng ~)”, ví dụ <span class='gd-jp'>物価は上がるばかりだ。</span>（Vật giá cứ tăng mãi.）; cũng có thể diễn tả “chỉ toàn ~, cứ ~ suốt”, ví dụ <span class='gd-jp'>彼女は泣くばかりで何も言わない。</span>（Cô ấy chỉ khóc suốt mà chẳng nói gì.）<br><b>Thể て＋ばかりいる</b> = chỉ toàn làm một việc: <span class='gd-jp'>弟はゲームをしてばかりいる。</span>（Em trai tôi chỉ suốt ngày chơi game.）</div><div class='gd-warn'>Mẹo phân biệt: nhìn phần đứng trước ばかり trước — thể た là “vừa mới ~”, thể từ điển là “cứ ~ mãi (ngày càng ~ / chỉ toàn ~)”, thể て là “suốt ngày ~”. Nếu câu có mốc thời gian khá xa như “tháng trước, năm ngoái” mà muốn nói “vừa mới ~” thì dùng たばかり, không dùng たところ.</div>","n3-12":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜最中に」tương đương với <b>「đang ～ thì bỗng……」</b> trong tiếng Việt. Bạn đang làm dở một việc, đang bận rộn thì bị việc khác cắt ngang hoặc gặp sự cố bất ngờ. Ví dụ như 「đang thuyết trình thì mất điện」, 「đang phỏng vấn thì điện thoại reo」. Vế sau thường là chuyện <b>xảy ra đột ngột, khiến người ta trở tay không kịp</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đang làm dở thì bị cắt ngang</span>Đây là cách dùng điển hình nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議の最中に、電話が鳴った。</span>（Đang họp thì điện thoại reo）</div><div class='gd-ex-line'>・<span class='gd-jp'>シャワーを浴びている最中に、お湯が出なくなった。</span>（Đang tắm thì nước nóng bỗng hết）</div><div class='gd-sec'><span class='gd-tag'>最中だ</span>Đặt ở cuối câu, nghĩa là 「hiện giờ đang bận ～」. Rất hay dùng khi nghe điện thoại hoặc từ chối khéo người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、食事の最中なので、あとでかけ直します。</span>（Bây giờ mình đang ăn cơm, lát nữa mình gọi lại nhé）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: chuyển sang dạng 「〜ている」 trước, rồi thêm 最中に.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べている最中に</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話している最中に</span></span></div><div class='gd-sec'><b>Danh từ</b>: danh từ ＋ の ＋ 最中に. Danh từ phải là <b>một hoạt động đang diễn ra</b>, như <span class='gd-jp'>会議</span>、<span class='gd-jp'>試合</span>、<span class='gd-jp'>授業</span>、<span class='gd-jp'>面接</span>.<br><span class='gd-pair'><span class='gd-jp'>試合</span> → <span class='gd-jp'>試合の最中に</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Động từ nhất định phải ở dạng 「ている」: nói <span class='gd-jp'>食べている最中に</span>, không phải 食べる最中に.<br>・「の」sau danh từ không được bỏ: <span class='gd-jp'>授業の最中に</span>, không phải 授業最中に.<br>・「最中」ở đây đọc là <b>さいちゅう</b>.<br>・Phải nối với hành động «đang diễn ra trong một khoảng thời gian». Những động từ kết thúc ngay tức khắc như <span class='gd-jp'>着く</span>、<span class='gd-jp'>始まる</span> thì không dùng được với 最中に; những động từ chỉ mô tả trạng thái như <span class='gd-jp'>いる</span>、<span class='gd-jp'>ある</span> cũng không dùng được.<br>・Vế sau thường là <b>chuyện xảy ra đột ngột, cắt ngang</b>. Nếu bạn chỉ muốn nói 「trong khoảng thời gian đó mình đã làm một việc gì đó」 thì dùng 最中に sẽ nghe hơi kỳ.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>最中に</b>＝đang làm thì <b>bỗng bị cắt ngang, gặp sự cố bất ngờ</b>: <span class='gd-jp'>寝ている最中に、地震が起きた。</span>（Đang ngủ thì xảy ra động đất）<br><b>間に</b>＝tranh thủ khoảng thời gian đó để <b>làm xong một việc</b> (có thể là chủ ý sắp xếp): <span class='gd-jp'>子どもが寝ている間に、部屋を片付けた。</span>（Tranh thủ lúc con ngủ, mình đã dọn xong phòng）<br>Nếu câu thứ hai đổi thành 「寝ている最中に、部屋を片付けた」 thì nghe sẽ thấy sai sai, vì dọn phòng không phải là chuyện «bỗng dưng xảy ra».</div><div class='gd-sec'><b>〜中</b> (ví dụ <span class='gd-jp'>会議中</span>) chỉ nói rất nhẹ nhàng là 「đang ～」, thường thấy trên biển hiệu hay thông báo; còn <b>〜の最中</b> nghe mạnh hơn, nhấn mạnh 「đang làm dở dang, đúng lúc bận nhất」.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: muốn nói 「đang ～ thì bỗng……」 thì dùng 最中に; muốn nói 「tranh thủ lúc ～ để làm……」 thì dùng 間に.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nhấn mạnh hơn nữa, bạn có thể nói 「真っ最中」: <span class='gd-jp'>今、テストの真っ最中だ。</span>（Bây giờ đang đúng giữa giờ thi đây）</div>","n3-14":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「～間に」tương đương với <b>「trong lúc ～ (có chuyện xảy ra)」「tranh thủ lúc ～ (làm xong một việc)」</b> trong tiếng Việt. Hãy hình dung một khoảng thời gian như một đường thẳng, 「間に」là <b>cắm một lá cờ</b> lên đường thẳng đó: tại một thời điểm nào đó trong khoảng thời gian này, có chuyện xảy ra, hoặc bạn đã làm xong một việc.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Xảy ra lúc không để ý</span>Lúc bạn không có mặt hoặc không để ý thì chuyện đã xảy ra rồi.</div><div class='gd-ex-line'>・<span class='gd-jp'>留守の間に宅配便が届いた。</span>（Lúc mình vắng nhà thì bưu kiện được giao tới）</div><div class='gd-ex-line'>・<span class='gd-jp'>知らない間に、もう夜の12時になっていた。</span>（Không hay biết từ lúc nào đã 12 giờ đêm rồi）</div><div class='gd-sec'><span class='gd-tag'>Tranh thủ khoảng thời gian đó để làm</span>Tận dụng một khoảng thời gian để làm xong một việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが寝ている間に、部屋を掃除した。</span>（Tranh thủ lúc con ngủ, mình đã dọn dẹp xong phòng）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>（Mình muốn leo núi Phú Sĩ một lần trong thời gian ở Nhật）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước phải là <b>một khoảng thời gian</b> hoặc <b>một trạng thái kéo dài</b>.<br><b>Động từ</b>: những hành động như 「ngủ, ăn, xem」 thường dùng dạng ている (～ている) để biến thành khoảng thời gian 「đang ～」. <span class='gd-jp'>いる</span>、<span class='gd-jp'>ある</span> vốn đã là trạng thái, nên cứ giữ nguyên dạng gốc. Cũng có thể nối với dạng ない (～ない).<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝ている間に</span></span><span class='gd-pair'><span class='gd-jp'>日本にいる</span> → <span class='gd-jp'>日本にいる間に</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らない間に</span></span><br><b>Danh từ</b>: thêm 「の」 ở giữa.<br><span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守の間に</span></span><span class='gd-pair'><span class='gd-jp'>夏休み</span> → <span class='gd-jp'>夏休みの間に</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải thêm 「の」: phải nói <span class='gd-jp'>留守の間に</span>, không được nói 「留守間に」.<br>・「間」ở đây đọc là <b>あいだ</b>. 「かん」 trong <span class='gd-jp'>一週間</span> là một cách dùng khác, đừng đọc nhầm.<br>・Tiếng Việt hay nói chung là 「trong lúc」 hoặc 「khi」, nhưng tiếng Nhật phải xem việc ở vế sau: nếu là việc <b>diễn ra liên tục suốt</b> thì không thêm に. Vì vậy sau 「間に」 đừng nối với 「ずっと～」; câu <span class='gd-jp'>寝ている間に、ずっと雨が降っていた</span> là sai, phải bỏ に đi.<br>・Dù cả câu nói về chuyện quá khứ, phía trước thường vẫn dùng 「ている間に」, còn 「た」 của quá khứ chỉ đặt ở cuối câu: <span class='gd-jp'>寝ている間に地震があった。</span>（Trong lúc ngủ thì có động đất）</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về kỳ nghỉ hè:</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間、ずっとアルバイトをしていた。</span>（Suốt cả kỳ nghỉ hè mình đều đi làm thêm）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間に、運転免許を取った。</span>（Vào một lúc nào đó trong kỳ nghỉ hè, mình đã lấy được bằng lái xe）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みのうちに、宿題を終わらせたい。</span>（Mình muốn làm xong bài tập trước khi hết kỳ nghỉ hè）</div><div class='gd-sec'><b>間</b> (không có に)＝<b>suốt</b> cả khoảng thời gian đó đều làm, phía sau thường đi kèm 「ずっと」.<br><b>間に</b>＝tại <b>một thời điểm nào đó</b> trong khoảng thời gian này, có một việc xảy ra hoặc được làm xong.<br><b>うちに</b>＝có thêm sắc thái <b>「tranh thủ khi còn kịp」</b>, ngụ ý hết khoảng thời gian này thì sẽ bất tiện.<br>Ngoài ra còn có <b>最中に</b>＝đang làm dở một việc thì <b>đúng lúc đó</b> bị cắt ngang: <span class='gd-jp'>シャワーを浴びている最中に、電話が鳴った。</span>（Đang tắm thì đúng lúc điện thoại reo）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu vế sau là 「suốt ～」 thì dùng <b>間</b>; nếu vế sau là 「có chuyện xảy ra / làm xong một việc」 thì dùng <b>間に</b>; nếu muốn nói 「tranh thủ ngay bây giờ」 thì dùng <b>うちに</b>.</div>","n3-15":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ついでに」nghĩa là <b>“tiện thể”</b> hay <b>“nhân tiện”</b> trong tiếng Việt. A là việc bạn vốn đã phải làm. Đã làm rồi thì nhân dịp đó làm luôn B. Ví dụ: “xuống nhà đổ rác, tiện thể lấy thư”. Đổ rác là A, lấy thư là B.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Có ba cách nối. Phần đứng trước luôn là việc “vốn đã phải làm”:<br>Danh từ＋の＋ついでに　<span class='gd-pair'><span class='gd-jp'>買い物</span> → <span class='gd-jp'>買い物のついでに</span></span><br>Động từ thể từ điển＋ついでに　<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くついでに</span></span><br>Động từ thể た＋ついでに　<span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たついでに</span></span><br>Danh từ phải chỉ “một việc”, ví dụ như <span class='gd-jp'>買い物</span>、<span class='gd-jp'>散歩</span>、<span class='gd-jp'>出張</span>、<span class='gd-jp'>旅行</span>.</div><div class='gd-h'>Thể từ điển hay thể た?</div><div class='gd-sec'><span class='gd-tag'>Thể từ điển</span>A chưa làm, bạn sắp ra ngoài để làm, và nhân tiện làm B. Cách này hay dùng để nhờ người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニに行くついでに、お茶を買ってきてくれる？</span>（Lúc bạn đi cửa hàng tiện lợi, mua giúp mình chai trà luôn được không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるついでに、ゴミを出してくるね。</span>（Mình ra ngoài tiện thể đem rác đi đổ luôn nhé）</div><div class='gd-sec'><span class='gd-tag'>Thể た</span>Bạn đã đến nơi, A đã xảy ra rồi, nên nhân dịp đó làm B.</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に来たついでに、奈良にも行ってみた。</span>（Đã đến Kyoto rồi nên tiện thể mình ghé Nara luôn）</div><div class='gd-ex-line'>・<span class='gd-jp'>本屋に寄ったついでに、ノートも買った。</span>（Lúc ghé hiệu sách, mình tiện thể mua luôn cuốn vở）</div><div class='gd-sec'><span class='gd-tag'>Danh từ の</span>Gọn nhất, rất tiện trong đời sống hằng ngày.</div><div class='gd-ex-line'>・<span class='gd-jp'>買い物のついでに、銀行に寄った。</span>（Đi mua đồ, tiện thể ghé ngân hàng）</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のついでに、大阪の友達に会った。</span>（Đi công tác, tiện thể gặp bạn ở Osaka）</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-jp'>ついでに</span> cũng có thể đứng một mình ở đầu câu, dùng trực tiếp như “tiện thể”. A ở phía trước đã rõ từ ngữ cảnh nên không cần nói lại.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ついでに牛乳も買ってきて。</span>（À, tiện thể mua thêm sữa về nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Việc chính đứng trước, việc tiện thể đứng sau</b>. Nếu đảo lại, ý nghĩa sẽ thành việc kia mới là mục đích chính.<br>・Phía trước phải là “một việc”, không thể đặt thẳng địa điểm. Không nói được「駅のついでに」, mà phải nói <span class='gd-jp'>駅に行くついでに</span>.<br>・Cả A lẫn B đều phải là việc <b>bạn tự quyết định làm</b>. Những việc xảy ra tự nhiên như trời mưa thì không dùng được, không thể nói「雨が降ったついでに」.<br>・Trong tiếng Việt, “nhân tiện nói thêm” chỉ là bổ sung thông tin. Tiếng Nhật thường dùng <span class='gd-jp'>ちなみに</span> chứ ít dùng ついでに.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'>Trong tiếng Việt, “tiện thể” và “vừa… vừa…” đôi khi bị lẫn, nhưng tiếng Nhật phân biệt rất rõ. Cùng là tình huống đi ra ga:<br><b>ついでに</b>＝nhân dịp làm A, <b>làm thêm một việc nữa</b>, hai việc không nhất thiết xảy ra cùng lúc: <span class='gd-jp'>駅に行くついでに、手紙を出した。</span>（Đi ra ga, tiện thể gửi thư）<br><b>ながら</b>＝hai việc <b>diễn ra đồng thời</b>: <span class='gd-jp'>音楽を聞きながら、駅まで歩いた。</span>（Vừa nghe nhạc vừa đi bộ đến ga）</div><div class='gd-warn'>Mẹo phân biệt: “làm thêm một việc tiện thể” thì dùng ついでに; “vừa… vừa…” làm cùng lúc thì dùng ながら.</div>","n3-16":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てからでないと」nghĩa là <b>“phải ~ trước thì mới ~ được”, “nếu chưa ~ thì không thể ~”</b>. Ví dụ “phải mua vé trước mới được vào”, “phải rửa tay trước mới được ăn”. Điểm chính là <b>thứ tự không được đảo, việc đứng trước nhất định phải làm xong trước</b>.</div><div class='gd-h'>Tách ra là hiểu ngay</div><div class='gd-sec'>Thật ra mẫu này ghép từ ba phần:<br>Thể <span class='gd-jp'>て</span> (làm ~ rồi) ＋ <span class='gd-jp'>から</span> (sau đó) ＋ <span class='gd-jp'>でないと</span> (nếu không phải thế thì)<br>Ghép lại là “nếu không phải sau khi đã làm ~”, tức là “chưa làm ~ trước”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chuyển động từ sang thể て, rồi thêm thẳng「からでないと」vào sau.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span> → <span class='gd-jp'>聞いてからでないと</span></span></div><div class='gd-h'>Vế sau nối với gì</div><div class='gd-sec'>Vế sau gần như luôn là câu phủ định kiểu <b>“không được, không làm được, không thể”</b>: <span class='gd-jp'>できない</span>、<span class='gd-jp'>わからない</span>、<span class='gd-jp'>だめだ</span>、<span class='gd-jp'>無理だ</span>, thể khả năng phủ định của động từ, v.v.</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってからでないと、おやつはだめだよ。</span>（Chưa rửa tay thì không được ăn bánh đâu nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>実際に見てからでないと、買うかどうか決められない。</span>（Chưa tận mắt xem thì mình không quyết định được có mua hay không）</div><div class='gd-ex-line'>・<span class='gd-jp'>お金を払ってからでないと、商品はお渡しできません。</span>（Phải thanh toán trước thì chúng tôi mới giao hàng được ạ）</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>からでないと</span>Cách nói thông thường, dùng được cả khi nói lẫn khi viết.<br><span class='gd-tag'>からでなければ</span>Trang trọng và cứng hơn, hay thấy trong thông báo, tài liệu hướng dẫn.<br><span class='gd-tag'>からじゃないと</span>Dạng khẩu ngữ giữa bạn bè.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題やってからじゃないと、ゲームはできないよ。</span>（Làm xong bài tập rồi mới được chơi game nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau <b>không được dùng câu khẳng định kiểu “được”</b>. <span class='gd-jp'>予約してからでないと、入れます</span> là sai. Muốn nói “đặt chỗ trước rồi mới vào” thì dùng câu thông thường <span class='gd-jp'>予約してから入ります</span> là đủ.<br>・Chữ「<b>で</b>」ở giữa không được bỏ. Viết thành「てからないと」là sai.<br>・Phải chia đúng thể て: <span class='gd-jp'>行く</span> là <span class='gd-jp'>行って</span>, <span class='gd-jp'>書く</span> là <span class='gd-jp'>書いて</span>. Sai ở đây thì cả câu sai.<br>・Sắc thái của mẫu này mang tính “quy định” và “điều kiện”. Khi nói với khách, vế sau phải dùng kính ngữ, ví dụ <span class='gd-jp'>できません</span>、<span class='gd-jp'>お渡しできません</span>.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'>Cùng một tình huống: phải xem hợp đồng trước khi ký.<br><b>てから</b>＝chỉ nói về <b>thứ tự</b>, làm A rồi làm B: <span class='gd-jp'>内容を確認してから、サインします。</span>（Tôi xác nhận nội dung rồi sẽ ký）<br><b>てからでないと</b>＝nhấn mạnh <b>nhất định phải làm A trước, không thì không làm được B</b>: <span class='gd-jp'>内容を確認してからでないと、サインできません。</span>（Chưa xác nhận nội dung thì tôi không thể ký）<br><b>た上で</b>＝làm xong A rồi <b>lấy đó làm cơ sở</b> để làm B, trang trọng và thận trọng hơn: <span class='gd-jp'>内容を確認した上で、サインします。</span>（Sau khi đã xác nhận nội dung, tôi sẽ ký）</div><div class='gd-warn'>Mẹo phân biệt: nếu vế sau là “có thể làm, sẽ làm” thì dùng <b>てから</b> hoặc <b>た上で</b>; nếu vế sau là “không được, không làm được” và bạn muốn nhấn mạnh “phải ~ trước”, thì dùng <b>てからでないと</b>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể xem tiếp「<span class='gd-jp'>〜上で</span>」(n3-23), rất hay dùng trong hoàn cảnh trang trọng để nói “làm ~ trước rồi mới ~”: <span class='gd-jp'>よく考えた上で、決めてください。</span>（Hãy cân nhắc kỹ rồi hãy quyết định nhé）</div>","n3-18":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜としたら」nghĩa là <b>「giả sử thật sự ～ thì」</b>. Trước hết bạn <b>coi như là thật</b> một tình huống chưa chắc chắn, thậm chí khó có thể xảy ra, rồi nói tiếp \"vậy thì sẽ thế nào\", \"vậy thì mình muốn làm gì\". Giống như khi bạn bè tán gẫu: \"Giả sử thôi nhé, giả sử bạn trúng số...\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Giả định thuần túy</span>Nói về chuyện khó xảy ra hoặc chưa xảy ra, thường đi cùng <span class='gd-jp'>もし</span>, <span class='gd-jp'>仮に</span> (giả sử).</div><div class='gd-ex-line'>・<span class='gd-jp'>もし宝くじが当たったとしたら、何に使う？</span>(Giả sử trúng xổ số, bạn sẽ dùng tiền vào việc gì?)</div><div class='gd-ex-line'>・<span class='gd-jp'>一週間休めるとしたら、どこに行きたい？</span>(Nếu được nghỉ một tuần, bạn muốn đi đâu?)</div><div class='gd-sec'><span class='gd-tag'>Suy luận từ điều nghe được</span>Coi lời người khác nói hoặc tin nghe được là thật, rồi rút ra kết luận.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話が本当だとすれば、大変なことだ。</span>(Nếu chuyện anh ấy nói là thật thì nghiêm trọng rồi)</div><div class='gd-sec'><span class='gd-tag'>Đặt ở đầu câu</span>Thêm <span class='gd-jp'>だ</span> phía trước để thành <span class='gd-jp'>だとしたら</span>, <span class='gd-jp'>だとすると</span>, nghĩa là \"vậy thì\", nối tiếp điều đối phương vừa nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は台風が来るらしいよ。</span>(Nghe nói ngày mai bão sẽ đến đấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>B：だとすると、旅行は無理だね。</span>(Vậy thì chắc không đi du lịch được rồi nhỉ)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ và tính từ い nối trực tiếp:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとしたら</span></span><span class='gd-pair'><span class='gd-jp'>当たった</span> → <span class='gd-jp'>当たったとしたら</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとしたら</span></span><br>Danh từ và tính từ な phải thêm <b>だ</b> trước:<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だとしたら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だとしたら</span></span><br>Ba cách nói <span class='gd-jp'>としたら</span>, <span class='gd-jp'>とすれば</span>, <span class='gd-jp'>とすると</span> có cách nối giống hệt nhau.</div><div class='gd-h'>Chọn một trong ba cách nói thế nào</div><div class='gd-sec'><b>としたら</b>: khẩu ngữ nhất, dễ dùng nhất. Khi vế sau là mong muốn, dự định của bản thân kiểu \"muốn ～\", \"sẽ ～\" thì chọn nó là tự nhiên nhất.<br><b>とすれば・とすると</b>: mang sắc thái \"suy luận\" hơn, vế sau thường là những nhận định như <span class='gd-jp'>〜だろう</span>, <span class='gd-jp'>〜はずだ</span>, <span class='gd-jp'>〜必要がある</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だとすれば、運動会は延期だろう。</span>(Nếu ngày mai mưa thì có lẽ hội thao sẽ bị hoãn)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な đừng quên <b>だ</b>: phải nói <span class='gd-jp'>雨だとしたら</span>, không phải 「雨としたら」.<br>・Danh từ mà <b>không thêm だ</b>, nối thẳng với <span class='gd-jp'>としたら</span> thì sẽ thành nghĩa khác là \"đứng ở lập trường của ～\": <span class='gd-jp'>親としたら、心配だろう。</span>(Đứng ở lập trường của bố mẹ thì chắc sẽ lo lắng nhỉ)<br>・<b>Chuyện chắc chắn sẽ xảy ra thì không dùng được</b>: \"Về đến nhà thì gọi cho mình nhé\" là <span class='gd-jp'>家に着いたら電話して</span>; nếu nói 「着いたとしたら」 thì nghe như đang nghi ngờ bạn có về tới nhà được không.<br>・Sau <span class='gd-jp'>とすると</span> thường không đi với \"muốn ～\", \"hãy ～\"; những lúc đó hãy đổi sang <span class='gd-jp'>としたら</span>.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>たら</b> = \"nếu ～ / sau khi ～\" thông thường, chuyện đó có thể thật sự xảy ra:<br><span class='gd-jp'>宝くじが当たったら、車を買う。</span>(Trúng là mua xe)<br><b>としたら</b> = nhấn mạnh đặc biệt rằng \"đây chỉ là giả định\":<br><span class='gd-jp'>宝くじが当たったとしたら、車を買う。</span>(Giả sử thật sự trúng, mình sẽ mua xe)<br>Chuyện chắc chắn sẽ xảy ra thì chỉ dùng được たら: <span class='gd-jp'>家に着いたら連絡するね。</span>(Về đến nhà mình sẽ liên lạc với bạn nhé)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu nói được thành \"giả sử thật sự ～\", \"lỡ như thật sự ～\" thì dùng としたら; còn chỉ là \"sau khi ～ thì ～\" thì dùng たら.</div>","n3-19":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たところ」nghĩa là <b>「sau khi ～ thì phát hiện ra…」</b>. Bạn làm một việc trước (gọi điện hỏi, tra cứu, dùng thử), rồi mới biết được một kết quả. Ví dụ: \"Gọi điện hỏi cửa hàng thì họ bảo hết hàng rồi.\"<br>Chữ <span class='gd-jp'>ところ</span> ở đây không liên quan gì đến \"nơi chốn\", cứ coi nó là công tắc báo hiệu \"kết quả\" là được.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thể た của động từ + ところ.<br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いた</span> → <span class='gd-jp'>聞いたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べた</span> → <span class='gd-jp'>調べたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話した</span> → <span class='gd-jp'>電話したところ</span></span><br>Câu chia làm hai nửa: nửa đầu là <b>việc bạn đã làm</b>, nửa sau là <b>kết quả bạn biết hoặc xuất hiện sau khi làm</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Hỏi rồi mới biết</span>Thông tin có được sau khi hỏi người khác hoặc gọi điện xác nhận.</div><div class='gd-ex-line'>・<span class='gd-jp'>店に電話したところ、もう売り切れだった。</span>(Gọi điện đến cửa hàng thì họ bảo đã bán hết rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に相談したところ、いいアドバイスをもらえた。</span>(Sau khi trao đổi với thầy cô, mình nhận được lời khuyên rất hay)</div><div class='gd-sec'><span class='gd-tag'>Thử rồi mới biết</span>Kết quả sau khi tra thử, làm thử.</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しく調べたところ、原因がわかった。</span>(Sau khi tra cứu kỹ thì đã tìm ra nguyên nhân)</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだところ、熱が下がった。</span>(Uống thuốc này xong thì hạ sốt)</div><div class='gd-sec'>Sắc thái khá trang trọng, rất hay gặp trong báo cáo, email công việc, tin tức. Khi nói chuyện với bạn bè thì phần lớn dùng thẳng 「〜たら」.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau là <b>chuyện đã xảy ra, đã biết</b>, nên phần lớn dùng thì quá khứ. Không đi với việc bạn sắp làm, lời yêu cầu hay mệnh lệnh:<br>×<span class='gd-jp'>調べたところ、先生に聞きます。</span><br>○<span class='gd-jp'>調べてから、先生に聞きます。</span>(Tra xong rồi mới đi hỏi thầy cô)<br>・Vế đầu thường là <b>việc do chính bạn chủ động làm</b>. Những chuyện tự nhiên xảy ra như trời mưa thì không nên đặt ở vế đầu:<br>×<span class='gd-jp'>雨が降ったところ、涼しくなった。</span><br>○<span class='gd-jp'>雨が降ったら、涼しくなった。</span>(Mưa xong thì trời mát hẳn)<br>・Trọng tâm của mẫu này là \"kết quả phát hiện được sau khi làm\", bản thân nó không diễn tả \"vì ～ nên ～\". Có khi hai vế vô tình có quan hệ nhân quả (uống thuốc → hạ sốt), có khi không (gọi điện hỏi cửa hàng không phải là nguyên nhân khiến hàng hết, chỉ là cơ hội để bạn biết tin), cả hai trường hợp đều dùng được.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>たところ</b> = sau khi làm, <b>phía sau còn một câu kết quả</b>:<br><span class='gd-jp'>駅員に聞いたところ、電車は遅れているそうだ。</span>(Hỏi nhân viên nhà ga thì họ bảo tàu đang bị trễ)<br><b>たところだ</b> = <b>vừa mới</b> làm xong, câu kết thúc ở đó:<br><span class='gd-jp'>今、駅員に聞いたところだ。</span>(Mình vừa mới hỏi nhân viên nhà ga xong)<br><b>たら</b> = cũng có thể diễn tả \"sau khi ～ thì phát hiện\", nhưng mang tính khẩu ngữ hơn và phạm vi dùng rộng hơn:<br><span class='gd-jp'>駅員に聞いたら、電車が遅れてるって。</span>(Hỏi nhân viên nhà ga thì họ bảo tàu bị trễ)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: sau 「ところ」 có dấu phẩy và còn một câu kết quả nữa thì là たところ; câu dừng ở 「ところだ」 thì là \"vừa mới làm xong\". Trong hoàn cảnh trang trọng, nói về kết quả thì dùng たところ, còn trò chuyện với bạn bè thì dùng たら.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể quay lại so sánh với ba mốc thời gian của <span class='gd-jp'>〜ところだ</span> (sắp làm, đang làm, vừa làm xong), như vậy sẽ không bị lẫn với たところ.</div>","n3-25":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Chữ「限」trong <span class='gd-jp'>に限り</span>、<span class='gd-jp'>に限って</span> nghĩa là giới hạn, tức là <b>thu hẹp phạm vi lại, chỉ còn đúng một đối tượng này</b>. Mẫu này có hai cách dùng rất khác nhau. Một là <b>「chỉ áp dụng cho ～」</b> hay thấy trên thông báo. Hai là <b>「đúng lúc ～ thì lại ～」</b> dùng khi than phiền trong đời sống, giống như câu tiếng Việt «cứ lúc nào vội là y như rằng gặp đèn đỏ».</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>danh từ</b>.<br>Danh từ nối thẳng: <span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日に限り</span></span><br>Muốn nói「vào lúc ～」「vào ngày ～」thì hãy dùng động từ để nói trọn vẹn phần「とき」「日」trước, rồi mới nối vào:<br><span class='gd-pair'><span class='gd-jp'>急いでいる</span> → thêm とき → <span class='gd-jp'>急いでいるときに限って</span></span><br><span class='gd-pair'><span class='gd-jp'>傘を持っていない</span> → thêm 日 → <span class='gd-jp'>傘を持っていない日に限って</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chỉ áp dụng cho ～</span>Bạn hay gặp trong khuyến mãi của cửa hàng, vé, quy định. Giọng khá trang trọng, phần lớn viết là <span class='gd-jp'>に限り</span>. Nghĩa là「chỉ trong phạm vi này mới được」.</div><div class='gd-ex-line'>・<span class='gd-jp'>先着100名様に限り、特典をプレゼントします。</span>（Chỉ tặng quà đặc biệt cho 100 khách đầu tiên）</div><div class='gd-ex-line'>・<span class='gd-jp'>このチケットは当日に限り有効です。</span>（Vé này chỉ có giá trị trong ngày）</div><div class='gd-sec'><span class='gd-tag'>Đúng lúc ～ lại ～</span>Bình thường chẳng sao, nhưng đúng lúc bạn không muốn nhất thì lại xảy ra chuyện. Cách dùng này dùng <span class='gd-jp'>に限って</span>. Vế sau thường là chuyện xui xẻo, không như ý, giọng hơi than phiền.</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持っていない日に限って、急に雨が降る。</span>（Cứ đúng hôm không mang ô là trời lại đổ mưa bất chợt）</div><div class='gd-ex-line'>・<span class='gd-jp'>急いでいるときに限って、信号に引っかかる。</span>（Cứ đúng lúc vội là lại bị vướng đèn đỏ）</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日に限って、朝早く目が覚める。</span>（Cứ đúng ngày nghỉ là lại tỉnh dậy sớm）</div><div class='gd-sec'><span class='gd-tag'>Riêng người đó thì không</span>Phía trước đặt một người bạn rất tin tưởng, phía sau nối「không thể nào ～」. Nghĩa là「người khác thì có thể, nhưng riêng người này thì tuyệt đối không」.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの子に限って、うそをつくはずがない。</span>（Con nhà tôi thì không thể nào nói dối được）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの真面目な田中さんに限って、約束を忘れるなんてありえない。</span>（Anh Tanaka nghiêm túc như thế thì không đời nào quên cuộc hẹn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nghĩa「chỉ áp dụng cho」rất trang trọng, là giọng của thông báo, quảng cáo. Nói chuyện với bạn bè về「chỉ hôm nay thôi」thì cứ dùng <span class='gd-jp'>今日だけ</span>, còn nói <span class='gd-jp'>今日に限り</span> nghe sẽ như đang đọc bảng thông báo.<br>・<span class='gd-jp'>に限って</span> kiểu「đúng lúc … lại …」thì vế sau hầu như luôn là chuyện không hay. Đừng dùng để nói chuyện tốt.<br>・Cách dùng「riêng người đó thì không」thì vế sau nhất định phải là phủ định, như <span class='gd-jp'>はずがない</span>、<span class='gd-jp'>ありえない</span>. Dù bạn chỉ nói <span class='gd-jp'>うちの子に限って</span> rồi dừng lại, người Nhật vẫn hiểu là bạn định nói「không thể nào」.<br>・Đừng nhầm với <b><span class='gd-jp'>に限る</span></b>. Nghĩa của nó là「～ là nhất, phải ～ mới đúng」: <span class='gd-jp'>暑い日は冷たいビールに限る。</span>（Ngày nóng thì phải uống bia lạnh）. Chỉ khác một chút về chữ nhưng nghĩa hoàn toàn khác.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về「hôm nay」nhưng cách dùng khác nhau thì nghĩa khác hẳn:<br><span class='gd-jp'>本日に限り、入場無料です。</span>（Chỉ riêng hôm nay vào cửa miễn phí）→ thông báo, nghĩa「chỉ áp dụng cho」<br><span class='gd-jp'>今日に限って、財布を忘れた。</span>（Cứ đúng hôm nay lại quên ví）→ than phiền, nghĩa「đúng lúc … lại …」<br><span class='gd-jp'>あの人に限って、そんなことはしない。</span>（Riêng người đó thì không làm chuyện như vậy đâu）→ tin tưởng, nghĩa「riêng người đó thì không」</div><div class='gd-warn'>Mẹo nhận biết nhanh: thấy trên thông báo, quy định thì là「chỉ áp dụng cho」. Nói về chuyện xui của mình thì là「đúng lúc … lại …」. Phía trước là người, phía sau là「không thể nào」thì là「riêng người đó thì không」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Chuyển nó sang dạng phủ định <span class='gd-jp'>に限らず</span>, nghĩa sẽ thành「không chỉ ～」: <span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span>（Quán này không chỉ cuối tuần mà lúc nào cũng đông）</div>","n3-26":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「きり」có hai gương mặt.<br>① Gắn sau danh từ ＝ <b>「chỉ có ～」</b>, giống như «chỉ có hai đứa mình», «chỉ một lần này thôi» trong tiếng Việt.<br>② Gắn sau động từ thể た ＝ <b>「sau ～ thì không còn ～ nữa」</b>, giống như «đi biệt tăm», «từ đó bặt vô âm tín» trong tiếng Việt.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Chỉ có ～</span>Danh từ＋きり. Danh từ ở đây phần lớn là số người, số lần, hoặc「これ」.<br><span class='gd-pair'><span class='gd-jp'>二人</span> → <span class='gd-jp'>二人きり</span></span>（chỉ hai người）<span class='gd-pair'><span class='gd-jp'>一度</span> → <span class='gd-jp'>一度きり</span></span>（chỉ một lần）<span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これきり</span></span>（chỉ có chừng này）<br>Lưu ý: <span class='gd-jp'>あれきり</span>、<span class='gd-jp'>それきり</span> thường không phải「chỉ có cái đó」mà là「từ lần đó trở đi thì hết」, thuộc cách dùng thứ hai bên dưới.</div><div class='gd-ex-line'>・<span class='gd-jp'>二人きりで話したい。</span>（Muốn nói chuyện riêng chỉ hai người）</div><div class='gd-ex-line'>・<span class='gd-jp'>チャンスは一度きりだ。</span>（Cơ hội chỉ có một lần）</div><div class='gd-ex-line'>・<span class='gd-jp'>お金はこれきりしかない。</span>（Tiền chỉ còn có chừng này thôi）</div><div class='gd-sec'><span class='gd-tag'>Sau đó thì không còn ～</span>Động từ thể た＋きり. Đổi động từ sang thể た rồi thêm きり.<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけた</span> → <span class='gd-jp'>出かけたきり</span></span><br>Vế sau là「việc lẽ ra phải xảy ra nhưng mãi không xảy ra」, nên thường là câu phủ định. Bạn cũng có thể dùng thẳng「〜たきりだ」ở cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は朝出かけたきり、まだ帰ってこない。</span>（Bố đi ra ngoài từ sáng, đến giờ vẫn chưa về）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女とは卒業式で会ったきりだ。</span>（Tôi gặp cô ấy ở lễ tốt nghiệp rồi từ đó không gặp lại nữa）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれきり、彼から連絡はない。</span>（Từ lần đó, anh ấy không liên lạc lại nữa）</div><div class='gd-sec'>Có một từ rất hay gặp trong đời sống: <span class='gd-jp'>寝たきり</span> ＝ nằm xuống rồi không dậy nữa ＝ <b>nằm liệt giường</b>.<br><span class='gd-jp'>祖母は去年から寝たきりだ。</span>（Bà tôi nằm liệt giường từ năm ngoái）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trong khẩu ngữ hay đọc thành <b>っきり</b>: <span class='gd-jp'>二人っきり</span>、<span class='gd-jp'>これっきり</span>, nghĩa giống nhau, nghe thấy đừng tưởng là từ khác.<br>・Sau「たきり」không thể nối「bắt đầu làm việc mới」. Muốn nói「từ khi vào công ty ngày nào cũng bận」thì phải dùng てから: <span class='gd-jp'>会社に入ってから、毎日忙しい。</span>, không thể nói「会社に入ったきり、毎日忙しい」.<br>・Bản thân きり đã có nghĩa「từ đó trở đi」, đừng dùng chồng với <span class='gd-jp'>以来</span>.<br>・Khi「○○きり」dùng với một mốc thời gian, đó là <b>lần cuối cùng</b>, không có nghĩa là trước đó chưa từng xảy ra. <span class='gd-jp'>卒業式で会ったきり</span> là「lễ tốt nghiệp là lần gặp cuối cùng」, chứ không phải「chỉ gặp đúng lần đó」.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>きり vs だけ</b>: cả hai đều dịch được là「chỉ có」, nhưng きり chỉ gắn với những từ như số người, số lần, これ, và hay mang cảm giác「không có ai khác, chỉ thế thôi」.<br><span class='gd-jp'>一人だけ来た。</span>／<span class='gd-jp'>一人きりだ。</span>（Chỉ có một người đến／Chỉ có một mình tôi）Cả hai cách nói đều được.<br><span class='gd-jp'>りんごだけ食べた。</span>（Chỉ ăn táo）Với đồ vật thông thường như thế này thì không thể thay bằng きり.</div><div class='gd-sec'><b>たきり vs っぱなし</b>: cả hai đều có cảm giác「sau đó thì không ～」, nhưng trọng tâm khác nhau.<br><span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>（Để nguyên tivi bật mà ngủ quên）: việc lẽ ra phải làm cho xong (tắt tivi) đã không làm, trạng thái cứ để mặc như vậy.<br><span class='gd-jp'>兄は東京へ行ったきり、帰ってこない。</span>（Anh trai đi Tokyo rồi không về nữa）: sau việc đó, những chuyện tiếp theo không còn xảy ra nữa.</div><div class='gd-warn'>Mẹo nhận biết nhanh:「chỉ có chừng này người, chừng này lần」→ danh từ＋きり;「sau lần đó thì không còn ～」→ thể た＋きり;「để bật, để nguyên không dọn」→ っぱなし.</div>","n3-22":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜以上（は）」tương đương với <b>「đã ~ thì ~」</b> trong tiếng Việt. Vế trước nêu một việc đã chắc chắn, vế sau nối với \"vậy thì mình nhất định phải ~\" hoặc \"vậy thì nên ~\". Nghe giống câu \"Đã hứa với người ta rồi thì phải làm cho trọn chứ\", mang cảm giác <b>đã vậy thì phải chịu trách nhiệm đến cùng</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối thẳng sau thể thường (tức là cách nói không có ます).<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した以上</span></span>（đã hẹn rồi thì）<br><span class='gd-pair'><span class='gd-jp'>やる</span> → <span class='gd-jp'>やる以上</span></span>（đã làm thì）<br><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ない以上</span></span>（đã không đến thì）</div><div class='gd-sec'><b>Danh từ, tính từ な</b>: ở giữa phải thêm 「である」, không nối thẳng được.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である以上</span></span>（đã là học sinh thì）<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロである以上</span></span>（đã là dân chuyên nghiệp thì）</div><div class='gd-sec'>Có thêm hay không thêm 「は」 phía sau đều được. Thêm vào thì giọng nặng hơn một chút, nghĩa vẫn y nguyên.</div><div class='gd-h'>Vế sau nối với gì</div><div class='gd-sec'>Trọng tâm nằm ở vế sau: đó nhất định là <b>quyết tâm, nghĩa vụ hoặc phán đoán</b> của người nói, chứ không phải chỉ miêu tả một việc đã xảy ra.</div><div class='gd-sec'><span class='gd-tag'>Tôi sẽ ~ (quyết tâm)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた以上は、最後までやります。</span>（Đã nhận việc này rồi thì tôi sẽ làm đến cùng）</div><div class='gd-ex-line'>・<span class='gd-jp'>やる以上は、一番を目指したい。</span>（Đã làm thì tôi muốn nhắm đến vị trí số một）</div><div class='gd-sec'><span class='gd-tag'>Nên ~, phải ~ (nghĩa vụ)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住んでいる以上、日本の法律を守らなければならない。</span>（Đã sống ở Nhật thì phải tuân thủ pháp luật Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロである以上、言い訳はできない。</span>（Đã là dân chuyên nghiệp thì không được viện cớ）</div><div class='gd-sec'><span class='gd-tag'>Vậy thì chỉ có thể ~ (phán đoán)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>本人が来ない以上、この話は進められない。</span>（Đã là đương sự không đến thì chuyện này không thể bàn tiếp được）</div><div class='gd-sec'>Vế trước dùng thể <span class='gd-jp'>た</span> nghĩa là \"việc đó đã xảy ra rồi, nên ~\". Dùng thể từ điển thì nghĩa là \"đã định làm như vậy, đã mang thân phận này, nên ~\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ phải thêm である: đúng là <span class='gd-jp'>学生である以上</span>, không phải 「学生な以上」. Nếu viết thẳng <span class='gd-jp'>学生以上</span> thì sẽ bị hiểu thành nghĩa khác (trình độ từ học sinh trở lên).<br>・Vế sau không thể chỉ là một sự thật bình thường. Không thể nói 「雨が降った以上、試合が中止になった」, vì “trận đấu bị hủy” chỉ là việc đã xảy ra, không phải quyết tâm hay phán đoán.<br>・<span class='gd-jp'>以上</span> còn có nghĩa khác, đừng lẫn: <span class='gd-jp'>三人以上</span> là “từ ba người trở lên”, còn <span class='gd-jp'>以上です</span> nói khi kết thúc báo cáo nghĩa là “xin hết, báo cáo đến đây là xong”.<br>・Giọng văn khá nghiêm túc, mang vẻ quyết tâm, hay dùng với chủ đề trách nhiệm, lời hứa, thân phận. Dùng cho chuyện nhỏ nhặt thì nghe hơi làm quá.</div><div class='gd-h'>Phân biệt với mẫu gần giống</div><div class='gd-sec'>Dễ nhầm nhất là <b>から</b>, chỉ đơn thuần nêu lý do.<br><span class='gd-jp'>約束したから、行きます。</span>（Vì đã hẹn nên tôi sẽ đi）: chỉ giải thích lý do.<br><span class='gd-jp'>約束した以上、行かなければならない。</span>（Đã hẹn rồi thì nhất định phải đi）: nhấn mạnh \"việc này đã thành lập, tôi có trách nhiệm\".<br>Ngoài ra, <span class='gd-jp'>雨が降ったから、試合が中止になった。</span>（Vì trời mưa nên trận đấu bị hủy）dùng から được, nhưng đổi sang 以上 thì không được, vì vế sau chỉ là việc đã xảy ra.</div><div class='gd-warn'>Mẹo phán đoán: vế sau là quyết tâm hay phán đoán kiểu \"tôi nhất định phải, nên, chỉ có thể\" thì dùng 以上. Nếu chỉ nói nguyên nhân và kết quả thì dùng から.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hay đi cùng <span class='gd-jp'>べきだ</span>: <span class='gd-jp'>約束した以上、守るべきだ。</span>（Đã hẹn rồi thì nên giữ lời）. Sau này bạn sẽ gặp <span class='gd-jp'>からには</span> và <span class='gd-jp'>上は</span> có nghĩa gần như giống hệt, trong đó <span class='gd-jp'>上は</span> mang tính văn viết và trang trọng hơn.</div>","n3-23":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜上で」có hai nghĩa, <b>nhìn vế trước nối với thể nào là biết nghĩa nào</b>:<br>Nối với <b>thể た</b>: \"làm xong ~ cho đàng hoàng rồi <b>mới</b> …\", giống như tiếng Việt nói \"bàn bạc <b>xong</b> rồi mới quyết định\".<br>Nối với <b>thể từ điển</b> (dạng gốc tra trong từ điển): \"<b>trong việc</b> ~\", giống như nói \"khi sống ở Nhật, kính ngữ rất quan trọng\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>① Làm xong rồi mới…</span>Thể た＋上で／Danh từ の＋上で<br><span class='gd-pair'><span class='gd-jp'>相談する</span> → <span class='gd-jp'>相談した上で</span></span><span class='gd-pair'><span class='gd-jp'>確認</span> → <span class='gd-jp'>確認の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>よく考えた上で、返事します。</span>（Tôi sẽ suy nghĩ kỹ rồi mới trả lời bạn）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とよく相談した上で、転職を決めた。</span>（Bàn bạc kỹ với gia đình xong, tôi mới quyết định chuyển việc）</div><div class='gd-sec'>Điểm mấu chốt là việc ở vế trước là <b>bước chuẩn bị cần thiết</b>, làm xong rồi mới tiến hành vế sau. Vế sau hay là những hành động kiểu \"đưa ra quyết định, làm thủ tục\" như <span class='gd-jp'>決める</span>, <span class='gd-jp'>申し込む</span>, <span class='gd-jp'>返事する</span>.</div><div class='gd-sec'><span class='gd-tag'>② Trong việc ~</span>Thể từ điển＋上で／Danh từ の＋上で<br><span class='gd-pair'><span class='gd-jp'>生活する</span> → <span class='gd-jp'>生活する上で</span></span><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本で生活する上で、敬語は大切だ。</span>（Khi sống ở Nhật, kính ngữ rất quan trọng）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は日本語を勉強する上で役に立つ。</span>（Cuốn sách này rất hữu ích khi học tiếng Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事の上での付き合いは大切です。</span>（Các mối quan hệ trong công việc rất quan trọng）</div><div class='gd-sec'>Vế sau phần lớn là một lời đánh giá: <span class='gd-jp'>大切だ</span>, <span class='gd-jp'>必要だ</span>, <span class='gd-jp'>欠かせない</span>, <span class='gd-jp'>役に立つ</span>, <span class='gd-jp'>注意が必要だ</span>. Khi sau đó nối với danh từ, đổi で thành <b>での</b>, như <span class='gd-jp'>仕事の上での付き合い</span> ở trên.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Trong thông báo, biểu mẫu, hướng dẫn của cửa hàng, bạn rất hay thấy「<b>ご＋danh từ＋の上</b>」, thường lược bỏ で, đây là cách nói văn viết rất lịch sự.</div><div class='gd-ex-line'>・<span class='gd-jp'>内容をご確認の上、サインしてください。</span>（Vui lòng xác nhận nội dung rồi hãy ký tên）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nối sai thể là nghĩa lệch ngay: <span class='gd-jp'>相談した上で</span> là \"sau khi đã bàn bạc xong\", còn <span class='gd-jp'>相談する上で</span> là \"trong việc bàn bạc\" (ví dụ: <span class='gd-jp'>相談する上で大切なこと</span> = điều quan trọng khi bàn bạc). Muốn nói \"xong rồi mới…\" thì nhất định dùng thể た.<br>・① không phải là \"rồi thì\" nói bừa. <span class='gd-jp'>ご飯を食べた上で、テレビを見た</span> nghe rất gượng, thứ tự trước sau trong sinh hoạt thường ngày chỉ cần dùng <span class='gd-jp'>〜てから</span> là được.<br>・Chữ 「上」 ở đây đọc là <b>うえ</b>. Ngoài ra còn có <span class='gd-jp'>仕事上</span> nối thẳng sau danh từ, đọc là しごと<b>じょう</b>, nghĩa gần giống <span class='gd-jp'>仕事の上で</span> nhưng cách viết và cách đọc khác nhau, đừng nhầm lẫn.<br>・Đừng viết thành 「上に」. <span class='gd-jp'>〜上に</span> nghĩa là \"không những ~ mà còn ~\", là một mẫu ngữ pháp khác.</div><div class='gd-h'>Phân biệt với mẫu gần giống</div><div class='gd-sec'><b>た上で vs てから</b><br><span class='gd-jp'>家族と相談してから決めます。</span>（Bàn bạc với gia đình trước rồi quyết định: chỉ nói thứ tự）<br><span class='gd-jp'>家族と相談した上で決めます。</span>（Bàn bạc kỹ với gia đình, lấy đó làm cơ sở rồi mới quyết định: nhấn mạnh đã nghiêm túc làm bước này）<br>てから dùng được trong mọi trường hợp; た上で trang trọng hơn, dùng cho những quyết định quan trọng.</div><div class='gd-sec'><b>る上で vs ために</b><br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（Để làm việc ở Nhật, tôi đang học tiếng Nhật）<br><span class='gd-jp'>日本で働く上で、日本語は欠かせません。</span>（Khi làm việc ở Nhật, tiếng Nhật là thứ không thể thiếu）<br>Dịch sang tiếng Việt thì cả hai đều dễ thành kiểu \"để / khi làm ~\", nhưng sau ために là <b>việc bạn làm vì mục đích đó</b>, còn sau る上で là <b>việc đó cần gì, điều gì quan trọng</b>.</div><div class='gd-warn'>Mẹo phán đoán: muốn nói \"làm xong ~ cho đàng hoàng rồi mới …\" thì dùng <b>た上で</b>; muốn nói \"khi làm ~, điều gì là quan trọng\" thì dùng <b>る上で</b>; nếu vế sau là \"tôi đi làm một việc gì đó\" thì dùng <b>ために</b>.</div>","n3-27":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をはじめ」nghĩa là <b>“tiêu biểu là ～”, “đứng đầu là ～, và cả… nữa”</b>. Bạn nêu trước một đại diện tiêu biểu, nổi tiếng nhất, rồi mới nhắc đến những thành viên còn lại trong cùng nhóm. Giống như khi giới thiệu món ăn Việt Nam cho bạn bè, bạn sẽ nói “phở” trước, rồi mới thêm “bún chả, bánh mì… và nhiều món khác”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước chỉ đặt được <b>danh từ</b>. <span class='gd-jp'>をはじめ</span> và <span class='gd-jp'>をはじめとして</span> có nghĩa giống nhau, thêm として thì trang trọng và đầy đủ hơn.<br><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京をはじめ</span></span><span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長をはじめとして</span></span><br>Nếu phía sau muốn nối thẳng với danh từ, hãy dùng <b>をはじめとする＋danh từ</b>: <span class='gd-jp'>寿司をはじめとする日本料理</span> (các món Nhật mà sushi là đại diện tiêu biểu).</div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Nêu đại diện</span>Nói trước cái nổi tiếng nhất, rồi cho biết còn rất nhiều cái khác nữa.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本には、東京をはじめ、大きな都市がたくさんある。</span>(Nhật Bản có nhiều thành phố lớn, tiêu biểu là Tokyo)</div><div class='gd-sec'><span class='gd-tag'>Người có vị trí cao nhất dẫn đầu</span>Nói từ người ở trên cùng cho đến tất cả mọi người, rất hay nghe trong công ty và các buổi lễ.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長をはじめ、社員全員が会議に出た。</span>(Từ giám đốc đến toàn thể nhân viên đều tham dự cuộc họp)</div><div class='gd-sec'><span class='gd-tag'>をはじめとする</span>Dùng như một thành phần bổ nghĩa, phía sau nối thẳng với danh từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司をはじめとする日本料理は、海外でも人気だ。</span>(Các món Nhật mà sushi là đại diện tiêu biểu rất được yêu thích cả ở nước ngoài)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải đặt cái <b>tiêu biểu nhất, nổi tiếng nhất, hoặc có vị trí cao nhất</b>. Câu <span class='gd-jp'>社員をはじめ、社長も参加した</span> nghe rất kỳ vì thứ tự bị ngược; phải nói <span class='gd-jp'>社長をはじめ、社員も参加した</span>.<br>・Phía sau nhất định phải nhắc đến “còn những cái khác nữa”, thường đi với <span class='gd-jp'>や</span>, <span class='gd-jp'>など</span>, <span class='gd-jp'>多くの</span>, <span class='gd-jp'>全員</span>, <span class='gd-jp'>も</span>. Nếu chỉ nói về một thứ thì không dùng được.<br>・はじめ ở đây không phải là “bắt đầu” về thời gian. “Bắt đầu từ tháng 9” phải nói <span class='gd-jp'>9月から</span>, không được nói 9月をはじめ.<br>・Sắc thái khá trang trọng, hay dùng trong tin tức, thuyết minh, diễn văn. Khi nói chuyện với bạn bè, nói <span class='gd-jp'>京都とか奈良とか</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>を中心に</b> cũng đặt một thứ lên đầu, nhưng ý nghĩa khác. Hãy xem cùng một trận mưa:<br><span class='gd-jp'>東京をはじめ、関東の各地で雨が降った。</span>(Mưa rơi ở khắp vùng Kanto, tiêu biểu là Tokyo)<br>→ Nơi nào cũng có mưa, chỉ là nêu Tokyo trước.<br><span class='gd-jp'>東京を中心に雨が降った。</span>(Mưa rơi tập trung quanh Tokyo)<br>→ Mưa tập trung ở khu vực Tokyo, Tokyo là trung tâm, càng ra xa càng ít.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói “～ và những cái khác nữa, tất cả đều…” thì dùng をはじめ; muốn nói “trọng tâm, cốt lõi là ～” thì dùng を中心に.</div>","n3-31":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ほど」nghĩa là <b>“đến mức…”, “… muốn chết”</b>. Thay vì nói thẳng “rất”, bạn đưa ra một hình ảnh để người nghe tự cảm nhận mức độ khoa trương. Giống như tiếng Việt nói “mệt chết đi được”, “cười chảy cả nước mắt”, tiếng Nhật là <span class='gd-jp'>死ぬほど疲れた</span>, <span class='gd-jp'>涙が出るほど笑った</span>.</div><div class='gd-h'>Nắm chắc thứ tự trong câu</div><div class='gd-sec'>Tiếng Việt thường nói “mệt” trước rồi mới đến “chết đi được”; tiếng Nhật thì vừa hay <b>ngược lại</b>: nói hình ảnh trước, rồi mới nói là như thế nào.<br>【Hình ảnh】＋ほど＋【Như thế nào】</div><div class='gd-ex-line'>・<span class='gd-jp'>涙が出るほど感動した。</span>(Cảm động đến rơi nước mắt)</div><div class='gd-ex-line'>・<span class='gd-jp'>眠れないほど楽しみにしていた。</span>(Mong chờ đến mức không ngủ được)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: dạng từ điển hoặc dạng ない, thêm ほど trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>涙が出る</span> → <span class='gd-jp'>涙が出るほど</span></span><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないほど</span></span><br><b>Tính từ い</b>: thêm ほど trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いほど</span></span><br><b>Tính từ な</b>: phải thêm な trước, rồi mới thêm ほど.<br><span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なほど</span></span><br><b>Danh từ</b>: thêm ほど trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>山</span> → <span class='gd-jp'>山ほど</span></span></div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>死ぬほど</span>Rất hay dùng trong văn nói, nghĩa là “… chết đi được”, chứ không phải thật sự chết.</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、死ぬほどおいしい。</span>(Tô ramen này ngon chết đi được)</div><div class='gd-sec'><span class='gd-tag'>山ほど</span>Nhiều đến mức chất thành một ngọn núi, tức là “nhiều vô kể”.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題が山ほどある。</span>(Bài tập nhiều như núi)</div><div class='gd-sec'><span class='gd-tag'>痛いほどわかる</span>Hiểu đến mức đau cả lòng, tức là “hoàn toàn thấu hiểu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>その気持ち、痛いほどわかるよ。</span>(Tâm trạng đó của bạn, mình hiểu rõ lắm)</div><div class='gd-sec'><span class='gd-tag'>ほどだ</span>Cũng có thể đặt ở cuối câu: nói nguyên nhân trước, cuối cùng bổ sung một câu về mức độ khoa trương.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒くて、手が動かないほどだった。</span>(Lạnh đến mức tay không cử động nổi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng sắp xếp thứ tự theo tiếng Việt: phải nói <span class='gd-jp'>涙が出るほど感動した</span>, không phải 「感動したほど涙が出る」.<br>・Đừng quên な với tính từ な: là <span class='gd-jp'>不思議なほど</span>, không phải 不思議ほど.<br>・Khi ほど đứng sau <b>số lượng</b> thì nghĩa khác: <span class='gd-jp'>3時間ほど待った</span> là “đã đợi khoảng 3 tiếng”, lúc này là “khoảng”, không phải khoa trương.<br>・Khi phía sau là dạng phủ định cũng là một cách dùng khác: <span class='gd-jp'>今年の夏は去年ほど暑くない</span> nghĩa là “mùa hè năm nay không nóng bằng năm ngoái”, đây là so sánh, không phải “nóng đến mức…”.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>ほど và くらい</b>: khi nói về “mức độ khoa trương”, phần lớn có thể thay thế cho nhau.<br><span class='gd-jp'>涙が出るほど笑った。</span>／<span class='gd-jp'>涙が出るくらい笑った。</span>(Cả hai đều là “cười chảy cả nước mắt”)<br>くらい mang tính khẩu ngữ hơn, ほど trang trọng hơn một chút.<br>Nhưng khi muốn nói “<b>mức độ rất thấp, chẳng đáng là bao</b>” thì chỉ dùng được くらい:<br><span class='gd-jp'>名前くらい自分で書いて。</span>(Ít nhất tên thì tự viết đi)<br>Ở đây không thể đổi thành ほど, vì ほど nghiêng về hướng “rất khoa trương”.</div><div class='gd-sec'><b>ほど và ば〜ほど</b>: <span class='gd-jp'>練習すればするほど上手になる</span> nghĩa là “càng luyện tập càng giỏi”, nói về hai việc cùng thay đổi, khác với “đến mức ～” ở đây.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói “khoa trương đến mức ～” thì ほど và くらい đều được; muốn nói “chuyện nhỏ này, ít nhất là ～” thì chỉ dùng くらい; thấy “～ば～ほど” thì đó là “càng ～ càng ～”.</div>","n3-32":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜くらい」giống như cách nói <b>「đến mức ～」</b> trong tiếng Việt. Bạn hay nói «cười đến đau bụng», «mệt đến mức không muốn nhúc nhích», tức là mượn một hình ảnh cụ thể để diễn tả mức độ nói quá lên. Tiếng Nhật dùng くらい: <span class='gd-jp'>お腹が痛くなるくらい笑った。</span>（Cười đến đau bụng）. <span class='gd-jp'>くらい</span> và <span class='gd-jp'>ぐらい</span> có nghĩa hoàn toàn giống nhau, dùng cái nào cũng được.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói quá lên</span>Đặt một hình ảnh trước くらい, phần phía sau mới là trạng thái thật sự bạn muốn nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>手が震えるくらい緊張した。</span>（Căng thẳng đến mức tay run lên）</div><div class='gd-ex-line'>・<span class='gd-jp'>泣きたいくらい悔しかった。</span>（Tức tối đến mức muốn khóc）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝の電車は動けないくらい混んでいる。</span>（Tàu điện buổi sáng đông đến mức không nhúc nhích nổi）</div><div class='gd-sec'><span class='gd-tag'>Chuyện nhỏ</span>Ngược lại, nói mức độ rất nhỏ, mang cảm giác «có gì đâu mà to tát».</div><div class='gd-ex-line'>・<span class='gd-jp'>これくらい、自分でできるよ。</span>（Chuyện nhỏ này tự mình làm được mà）</div><div class='gd-sec'><span class='gd-tag'>Ít nhất cũng ～ chứ</span>Nói về việc «tối thiểu cũng phải làm được», thường kèm chút phàn nàn.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくても、電話くらいしてよ。</span>（Bận mấy cũng gọi điện một cuộc chứ）</div><div class='gd-sec'><span class='gd-tag'>Không ai bằng ～</span>「Danh từ＋くらい～はない」dùng để khen hết lời hoặc nhấn mạnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんくらい優しい人はいない。</span>（Không ai hiền bằng anh Tanaka）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: ghép trực tiếp với thể từ điển hoặc thể ない; với việc muốn làm thì dùng「たい」cũng được.<br><span class='gd-pair'><span class='gd-jp'>震える</span> → <span class='gd-jp'>震えるくらい</span></span><span class='gd-pair'><span class='gd-jp'>動けない</span> → <span class='gd-jp'>動けないくらい</span></span><span class='gd-pair'><span class='gd-jp'>泣きたい</span> → <span class='gd-jp'>泣きたいくらい</span></span><br><b>Tính từ い</b>: ghép trực tiếp.<span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いくらい</span></span><br><b>Tính từ な</b>: phải thêm「な」trước.<span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なくらい</span></span><br><b>Danh từ</b>: ghép trực tiếp, ở giữa không thêm「の」.<span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これくらい</span></span><span class='gd-pair'><span class='gd-jp'>田中さん</span> → <span class='gd-jp'>田中さんくらい</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Số lượng＋くらい nghĩa là «khoảng», như <span class='gd-jp'>三時間くらい</span>（khoảng ba tiếng）. Còn động từ, tính từ, hoặc danh từ không chỉ số lượng như <span class='gd-jp'>これ</span>、<span class='gd-jp'>田中さん</span>＋くらい thì mới là «đến mức ～».<br>・Đừng đặt ngược trước sau. Phần trước くらい là hình ảnh so sánh, phần sau mới là trạng thái thật: <span class='gd-jp'>手が震えるくらい緊張した</span>, chứ không phải「緊張したくらい手が震えた」.<br>・Động từ phía trước thường chỉ cần dùng thể từ điển hoặc thể ない; chuyện đã qua thì chỉ cần chuyển cuối câu sang quá khứ: <span class='gd-jp'>声が出ないくらい驚いた。</span>（Giật mình đến mức không nói nên lời）<br>・Tính từ な đừng quên「な」, sau danh từ đừng thêm「の」: nói <span class='gd-jp'>これくらい</span>, không nói「これのくらい」.<br>・Cách dùng «chuyện nhỏ» mang sắc thái xem nhẹ, nếu nói với bề trên như <span class='gd-jp'>これくらいできるでしょう</span>（Việc cỡ này thì chắc làm được chứ）, nghe sẽ rất bất lịch sự.</div><div class='gd-h'>Phân biệt với từ trông giống</div><div class='gd-sec'><b>ほど</b> cũng có nghĩa «đến mức ～». Khi nói quá lên thì dùng cái nào cũng được, nhưng <b>くらい mang tính khẩu ngữ hơn, còn ほど trang trọng, thiên về văn viết</b>:<br><span class='gd-jp'>手が震えるくらい緊張した。</span>（Nói chuyện với bạn bè）<br><span class='gd-jp'>手が震えるほど緊張した。</span>（Viết bài, thuyết trình）</div><div class='gd-sec'>Nhưng với nghĩa <b>«chuyện nhỏ»</b> và <b>«ít nhất»</b> thì chỉ dùng được くらい. <span class='gd-jp'>これほど</span> ngược lại là «đến thế này», cho thấy mức độ rất lớn:<br><span class='gd-jp'>これくらい簡単だよ。</span>（Mức này dễ ợt mà）<br><span class='gd-jp'>これほど難しいとは思わなかった。</span>（Không ngờ lại khó đến thế）</div><div class='gd-sec'>Ngoài ra, kiểu so sánh «không ～ bằng ～» phải dùng ほど: <span class='gd-jp'>今年は去年ほど寒くない。</span>（Năm nay không lạnh bằng năm ngoái）</div><div class='gd-warn'>Mẹo phân biệt: muốn nói «chuyện nhỏ, ít nhất cũng ～» thì dùng くらい; muốn nói «không ～ bằng ～» hoặc viết văn trang trọng thì dùng ほど; chỉ đơn thuần nói quá mức độ thì dùng cái nào cũng được, khi nói chuyện thường nghe くらい nhiều hơn.</div>","n3-35":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜気味」tương đương với <b>«hơi ～», «có cảm giác hơi ～»</b> trong tiếng Việt. Ví dụ cổ họng bạn thấy lạ lạ, bạn nói «hình như mình hơi bị cảm», tiếng Nhật sẽ là <span class='gd-jp'>風邪気味です</span>. Thường dùng khi cơ thể hoặc tình trạng xuất hiện <b>dấu hiệu nhỏ không mấy tốt</b>, nhưng chưa nghiêm trọng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tình trạng cơ thể</span>Dùng nhiều nhất. Hơi cảm, hơi mệt, hơi mập, hơi thiếu ngủ.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味なので、今日は早く寝ます。</span>（Mình hơi bị cảm nên hôm nay đi ngủ sớm）</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、ちょっと太り気味なんだ。</span>（Dạo này mình hơi mập lên）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足気味で、授業中に眠くなった。</span>（Hơi thiếu ngủ nên trong giờ học buồn ngủ）</div><div class='gd-sec'><span class='gd-tag'>Tâm trạng, tiến độ công việc</span>Hơi căng thẳng, công việc hơi chậm trễ cũng dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての発表なので、少し緊張気味です。</span>（Lần đầu thuyết trình nên mình hơi căng thẳng）</div><div class='gd-ex-line'>・<span class='gd-jp'>工事が予定より遅れ気味だ。</span>（Công trình hơi chậm so với dự kiến）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: dùng thể ます, bỏ ます rồi ghép thẳng với 気味.<br><span class='gd-pair'><span class='gd-jp'>疲れます</span> → <span class='gd-jp'>疲れ気味</span></span><span class='gd-pair'><span class='gd-jp'>太ります</span> → <span class='gd-jp'>太り気味</span></span><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れ気味</span></span></div><div class='gd-sec'><b>Danh từ</b>: ghép trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪気味</span></span><span class='gd-pair'><span class='gd-jp'>緊張</span> → <span class='gd-jp'>緊張気味</span></span><span class='gd-pair'><span class='gd-jp'>運動不足</span> → <span class='gd-jp'>運動不足気味</span></span></div><div class='gd-sec'>Bản thân「〜気味」hoạt động như một danh từ: cuối câu thêm <span class='gd-jp'>だ／です</span>; khi đứng trước danh từ thì dùng <span class='gd-jp'>の</span>; khi nối sang câu sau thì dùng <span class='gd-jp'>で</span> hoặc <span class='gd-jp'>なので</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味の人は、マスクをしてください。</span>（Người nào hơi bị cảm thì hãy đeo khẩu trang）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi đứng sau từ khác thì đọc là <b>ぎみ</b>, không phải きみ: <span class='gd-jp'>風邪気味</span> đọc là かぜぎみ.<br>・Động từ phải dùng dạng thể ます đã bỏ ます, không dùng thể từ điển: nói <span class='gd-jp'>太り気味</span>, không nói 太る気味.<br>・Tính từ không ghép thẳng với 気味. «Hơi nóng» không nói 暑い気味 mà phải nói <span class='gd-jp'>ちょっと暑い</span>.<br>・Gần như chỉ dùng cho tình trạng không tốt. «Hơi vui», «hơi khỏe khoắn» thì không dùng 気味.<br>・Khi ghép với danh từ thì dùng <span class='gd-jp'>の</span>: <span class='gd-jp'>風邪気味の人</span>, không phải 風邪気味な人.<br>・Dù 気味 đã có nghĩa «hơi», người Nhật vẫn rất hay thêm <span class='gd-jp'>少し</span>、<span class='gd-jp'>ちょっと</span> phía trước, nói vậy rất tự nhiên, không bị coi là thừa.<br>・<span class='gd-jp'>気味が悪い</span>（đọc là きみがわるい）nghĩa là «rợn người, ghê ghê», không liên quan đến mẫu ngữ pháp này, đừng nhầm.</div><div class='gd-h'>Phân biệt với từ trông giống</div><div class='gd-sec'><b>〜がち</b> = <b>hay</b> như thế, dễ như thế (nói về tần suất, thói quen).<br><b>〜気味</b> = <b>hiện tại</b> có dấu hiệu hơi như thế (nói về trạng thái ngay lúc này).</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪気味です。</span>（Hôm nay mình hơi bị cảm）</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきがちです。</span>（Mùa đông hay bị cảm）</div><div class='gd-sec'><b>〜っぽい</b> cũng nói được <span class='gd-jp'>風邪っぽい</span> (hình như bị cảm), nghĩa khá gần với <span class='gd-jp'>風邪気味</span>, nhưng mang tính khẩu ngữ hơn, dùng khi nói chuyện với bạn bè; còn với cấp trên hay bác sĩ thì dùng <span class='gd-jp'>風邪気味です</span> sẽ lịch sự hơn. Phạm vi của っぽい cũng rộng hơn nhiều, <span class='gd-jp'>子どもっぽい</span>（trẻ con）、<span class='gd-jp'>白っぽい</span>（hơi trắng）đều là っぽい, những từ này không thể thay bằng 気味.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói «dạo này hay ～» thì dùng がち; muốn nói «bây giờ hơi ～» thì dùng 気味; nói thoải mái với bạn bè kiểu «hình như ～» thì có thể dùng っぽい.</div>","n3-36":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜っぱなし」nghĩa là <b>“làm xong rồi bỏ đó, không lo xử lý tiếp”, “bật mà không tắt”</b>. Giống như mẹ mắng bạn: “Đèn bật mà không tắt!”, “Cởi quần áo ra là vứt lung tung!”. Tiếng Nhật sẽ nói <span class='gd-jp'>つけっぱなし</span>、<span class='gd-jp'>出しっぱなし</span>、<span class='gd-jp'>脱ぎっぱなし</span>, và thường mang giọng <b>phàn nàn, không hài lòng</b>.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Dùng thể ます, bỏ ます đi rồi thêm「っぱなし」ngay sau đó. Cả ba nhóm động từ đều giống nhau, không cần tách riêng.<br><span class='gd-pair'><span class='gd-jp'>つけます</span> → bỏ ます → <span class='gd-jp'>つけっぱなし</span></span>（bật rồi không tắt）<br><span class='gd-pair'><span class='gd-jp'>出します</span> → <span class='gd-jp'>出しっぱなし</span></span>（lấy ra rồi không cất）<br><span class='gd-pair'><span class='gd-jp'>脱ぎます</span> → <span class='gd-jp'>脱ぎっぱなし</span></span>（cởi ra rồi vứt đó）<br><span class='gd-pair'><span class='gd-jp'>開けます</span> → <span class='gd-jp'>開けっぱなし</span></span>（mở ra rồi không đóng）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đáng ra phải dọn mà không dọn</span>Bạn làm một hành động, sau đó đáng ra phải tắt, phải cất, phải dọn dẹp, nhưng lại bỏ mặc. Đây là cách dùng phổ biến nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>（Mình để tivi bật mà ngủ quên mất）</div><div class='gd-ex-line'>・<span class='gd-jp'>水が出しっぱなしだよ。</span>（Nước chảy mãi mà chưa khóa kìa）</div><div class='gd-ex-line'>・<span class='gd-jp'>服を脱ぎっぱなしにしないで。</span>（Đừng cởi quần áo ra rồi vứt đó nhé）</div><div class='gd-sec'><span class='gd-tag'>Giữ nguyên một trạng thái suốt</span>Cùng một việc cứ kéo dài, không dừng được, thường có cảm giác “lâu quá rồi, mệt quá”.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は一日中立ちっぱなしで、足が痛い。</span>（Hôm nay đứng suốt cả ngày, đau chân quá）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝から働きっぱなしで疲れた。</span>（Làm việc liên tục từ sáng đến giờ, mệt quá）</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'>・<b>〜っぱなしだ</b>：<span class='gd-jp'>窓が開けっぱなしだ。</span>（Cửa sổ cứ mở suốt mà không đóng）<br>・<b>〜っぱなしで、〜</b>：phía sau nối với kết quả “thế là…”, như câu “Để tivi bật mà ngủ quên mất” ở trên.<br>・<b>〜っぱなしにする</b>：để mặc nó như vậy. Muốn bảo ai đừng làm thế thì nói <span class='gd-jp'>〜っぱなしにしないで</span>。<br>・<b>〜っぱなしの＋danh từ</b>：<span class='gd-jp'>出しっぱなしの本</span>（cuốn sách lấy ra rồi không cất）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cái đứng trước là <b>thể ます bỏ ます</b>, không phải thể từ điển: phải nói <span class='gd-jp'>つけっぱなし</span>, không phải つけるっぱなし。<br>・Ở giữa có <b>っ nhỏ</b>, cần ngắt một nhịp khi đọc: 「つけ・っ・ぱなし」, đừng đọc thành つけぱなし。<br>・Cách nói này thường mang sự không hài lòng kiểu “đáng ra phải xử lý mà không xử lý” (nhất là nghĩa “đáng ra phải dọn mà không dọn”). Nếu chỉ đơn giản nói “làm việc gì đó trong một trạng thái nào đó” mà không có ý phàn nàn, dùng「〜たまま」sẽ tự nhiên hơn. Tuy nhiên, nghĩa “đứng suốt, làm việc suốt” (kéo dài quá lâu) thì không thay được bằng たまま: <span class='gd-jp'>立ったまま</span> chỉ là “đứng (mà làm gì đó)”, không có nghĩa “đã đứng rất lâu”.<br>・Trọng tâm của っぱなし là “cứ để nguyên trạng thái đó không động đến”, không nhất thiết là do vô ý. Cố tình để như vậy cũng nói được, ví dụ <span class='gd-jp'>換気のために窓を開けっぱなしにしている。</span>（Để thông gió, cửa sổ được mở suốt）. Nếu muốn nhấn mạnh “chuẩn bị sẵn cho một mục đích”, hãy dùng 〜ておく。</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là “mở cửa sổ rồi ra khỏi nhà”:<br><b>〜たまま</b>＝chỉ nêu trạng thái, không có cảm xúc đặc biệt: <span class='gd-jp'>窓を開けたまま出かけた。</span>（Mở cửa sổ rồi đi ra ngoài）<br><b>〜っぱなし</b>＝mang sự không hài lòng kiểu “đáng ra phải đóng mà không đóng”: <span class='gd-jp'>窓を開けっぱなしで出かけた。</span>（Cửa sổ mở toang mà không đóng đã đi ra ngoài）<br><b>〜ておく</b>＝<b>cố ý</b> để nguyên như vậy, có mục đích: <span class='gd-jp'>暑いから、窓を開けておいた。</span>（Vì nóng nên mình để sẵn cửa sổ mở）<br>Cách nối cũng khác nhau: たまま nối với thể た, ておく nối với thể て, còn っぱなし nối với thể ます bỏ ます。</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn phàn nàn kiểu “sao lại không dọn” thì dùng っぱなし; chỉ nói “giữ nguyên như vậy” thì dùng たまま; “cố ý chuẩn bị sẵn” thì dùng ておく。</div>","n3-37":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả hai đều nói về việc “hợp với một kiểu người nào đó”, khác nhau ở chỗ đồ vật đó <b>có được làm riêng cho họ hay không</b>.<br><b>向き（むき）</b>＝“rất hợp với ～”, xét theo tính chất của bản thân đồ vật, không quan tâm ban đầu nó làm ra cho ai.<br><b>向け（むけ）</b>＝“được thiết kế riêng cho ～”, ngay từ đầu đã nhắm vào nhóm người này, giống như “phiên bản cho trẻ em”, “dành riêng cho người mới bắt đầu” trong tiếng Việt.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Cả hai đều nối thẳng sau <b>danh từ</b>, để chỉ “dành cho ai” hoặc “trong hoàn cảnh nào”.<br>Đặt cuối câu: <span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向きだ</span></span><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向けだ</span></span><br>Khi nối với danh từ phía sau: có thể thêm「の」（<span class='gd-jp'>初心者向けの講座</span>）, cũng hay ghép thẳng thành một từ（<span class='gd-jp'>初心者向け講座</span>、<span class='gd-jp'>子供向け番組</span>）, cả hai đều đúng. Cách ghép thẳng đặc biệt hay gặp trong tiêu đề, quảng cáo, mô tả sản phẩm. Khi tự đặt câu, dùng cách có thêm「の」là an toàn nhất.<br>Khi nối với động từ phía sau: <span class='gd-jp'>向けに</span>＋các động từ như <span class='gd-jp'>作る</span>、<span class='gd-jp'>書く</span>, nghĩa là “làm ra để dành cho ～”.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>向き</span>Điều kiện của bản thân đồ vật vừa hay phù hợp, thường dùng để nhận xét nhà cửa, công việc, tính cách, quần áo.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は一人暮らし向きだ。</span>（Căn phòng này rất hợp cho một người ở）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は営業向きの性格だ。</span>（Tính cách của anh ấy rất hợp để làm kinh doanh）</div><div class='gd-sec'>Khi không phù hợp thì nói <b>不向き</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は長く歩くのには不向きだ。</span>（Đôi giày này không hợp để đi bộ đường dài）</div><div class='gd-sec'><span class='gd-tag'>向け</span>Sản phẩm, chương trình, dịch vụ khi thiết kế đã nhắm vào một nhóm người nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人向けのパンフレットをください。</span>（Cho tôi tờ giới thiệu dành cho người nước ngoài）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは高齢者向けに作られている。</span>（App này được thiết kế cho người lớn tuổi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cách đọc: 向き đọc là <b>むき</b>, 向け đọc là <b>むけ</b>, chỉ khác âm cuối, nên khi nghe phải chú ý.<br>・Muốn nói “làm ra để dành cho ～” phải dùng <span class='gd-jp'>向けに作る</span>, không nói 向きに作る, vì 向き không nói về mục đích sản xuất.<br>・“Không phù hợp” chỉ có <span class='gd-jp'>不向き</span>, không có cách nói「不向け」.<br>・<span class='gd-jp'>南向きの部屋</span> là “phòng hướng nam”, ở đây 向き là <b>hướng</b>, khác nghĩa với “phù hợp”, đừng nhầm lẫn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng nói về mối quan hệ giữa một cuốn sách và trẻ em:<br><span class='gd-jp'>これは子供向けの本だ。</span>（Đây là sách thiếu nhi, vốn được viết ra để trẻ em đọc）<br><span class='gd-jp'>大人向けに書かれた本だが、やさしいので子供向きでもある。</span>（Cuốn sách này vốn được viết cho người lớn, nhưng nội dung dễ hiểu nên trẻ em đọc cũng hợp）<br>Câu thứ hai cho thấy rõ sự khác biệt: làm ra cho ai là <b>向け</b>, kết quả hợp với ai là <b>向き</b>, một cuốn sách có thể dùng cả hai.</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu thay được bằng “làm riêng cho ～” thì dùng 向け; chỉ cảm thấy “rất hợp với ～” thì dùng 向き。</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>向き bắt nguồn từ động từ <span class='gd-jp'>向く</span>（phù hợp）, nên cũng có thể nói thẳng <span class='gd-jp'>この仕事は私に向いている。</span>（Công việc này rất hợp với tôi）、<span class='gd-jp'>私は細かい作業に向いていない。</span>（Tôi không hợp với công việc tỉ mỉ）。</div>","n3-38":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜一方だ」nghĩa là <b>\"chỉ ngày càng ～\", \"có tăng không giảm\", \"ngày một tệ đi\"</b>. Sự việc cứ thay đổi mãi theo một hướng, không dừng lại và cũng không có dấu hiệu quay đầu. Hơn nữa, <b>phần lớn là theo hướng không tốt</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がる一方だ。</span>（Vật giá chỉ tăng chứ không giảm）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ thể từ điển (dạng gốc tra trong từ điển) ＋ 一方だ</b>。<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方だ</span></span>（tăng liên tục）<br><span class='gd-pair'><span class='gd-jp'>悪化する</span> → <span class='gd-jp'>悪化する一方だ</span></span>（xấu đi liên tục）<br>Động từ đứng trước phải là <b>động từ chỉ sự thay đổi</b>, như <span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>上がる</span>、<span class='gd-jp'>下がる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>進む</span>。</div><div class='gd-sec'><span class='gd-tag'>Tính từ</span>Tính từ không nối trực tiếp được. Bạn cần đổi thành「〜くなる」「〜になる」(trở nên ～) rồi mới thêm 一方だ。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → đổi い thành く, thêm なる → <span class='gd-jp'>寒くなる一方だ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → thêm になる → <span class='gd-jp'>不便になる一方だ</span></span></div><div class='gd-h'>Những kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Than phiền tình hình xấu đi</span>Rất hay dùng trên báo chí và khi kể chuyện dạo này với người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、仕事が増える一方だ。</span>（Dạo này công việc chỉ tăng chứ không giảm）</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなる一方だ。</span>（Bệnh của bố cứ nặng thêm mãi）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は人が減って、寂しくなる一方だ。</span>（Thị trấn này người ngày càng ít, ngày càng vắng vẻ）</div><div class='gd-sec'><span class='gd-tag'>Xu hướng trung tính</span>Không nhất thiết là chuyện xấu, bạn cũng có thể dùng để nói đơn giản là \"cứ tăng vù vù\".</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリの利用者は増える一方だ。</span>（Người dùng app này cứ tăng mãi）</div><div class='gd-sec'>Khi nói về chuyện trong quá khứ, dùng <b>一方だった</b>：<span class='gd-jp'>その後、二人の関係は悪くなる一方だった。</span>（Sau đó, quan hệ của hai người ngày càng tệ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng dùng 一方だ để nói \"cứ liên tục làm một hành động nào đó\" (kiểu \"cứ chơi game suốt\" trong tiếng Việt). Cách dùng đó là sai. <b>一方だ chỉ dùng để nói về sự thay đổi</b>：<br>　×<span class='gd-jp'>弟は毎日ゲームをする一方だ。</span><br>　○<span class='gd-jp'>弟は毎日ゲームばかりしている。</span>（Ngày nào em trai cũng chỉ toàn chơi game）<br>・Phía trước nhất định phải là <b>thể từ điển</b>, đừng nối với ている hay ます：×<span class='gd-jp'>増えている一方だ</span>、×<span class='gd-jp'>増えます一方だ</span>。Muốn nói lịch sự hơn thì chỉ cần đổi phần cuối: <span class='gd-jp'>増える一方です</span>。<br>・Đừng nối thẳng tính từ vào: ×<span class='gd-jp'>寒い一方だ</span>, phải nói <span class='gd-jp'>寒くなる一方だ</span>。<br>・Câu này mang sắc thái bất lực kiểu \"không thấy khá lên được\", nên ít khi dùng cho tin tốt.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>〜一方だ</b>（đặt ở cuối câu）＝ cứ thay đổi mãi theo một hướng：<span class='gd-jp'>家賃は高くなる一方だ。</span>（Tiền thuê nhà chỉ ngày càng đắt）<br><b>〜ばかりだ</b>（nối với thể từ điển）＝ nghĩa gần như giống hệt, mang tính khẩu ngữ hơn và hầu như chỉ dùng cho chuyện xấu：<span class='gd-jp'>家賃は高くなるばかりだ。</span>（Tiền thuê nhà chỉ ngày càng đắt）<br><b>〜一方で</b>（đặt ở giữa câu）＝ \"mặt khác\", dùng để đối chiếu hai việc, không liên quan đến sự thay đổi：<span class='gd-jp'>この町は便利な一方で、家賃が高い。</span>（Thành phố này tiện lợi, nhưng mặt khác tiền thuê nhà lại đắt）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: <b>一方だ ở cuối câu</b> là \"chỉ ngày càng ～\"; <b>一方で ở giữa câu</b> là \"mặt khác\". Thấy 一方 thì nhìn xem nó nằm ở đâu trước nhé.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói về quá trình \"dần dần trở nên ～\", bạn có thể học tiếp「〜てくる・〜ていく」：<span class='gd-jp'>だんだん寒くなってきた。</span>（Trời dần dần lạnh đi rồi）</div>","n3-39":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜ようにする」nghĩa là <b>\"mình cố gắng ～\", \"mình có để ý ～\"</b>. Giống như bạn nói \"dạo này mình có cố uống ít nước ngọt thôi\": trọng tâm là bạn có chủ ý cố gắng, chứ không đảm bảo lần nào cũng làm được.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Việc muốn làm: thể từ điển (dạng gốc tra trong từ điển) ＋ ようにする<br><span class='gd-pair'><span class='gd-jp'>早く寝る</span> → <span class='gd-jp'>早く寝るようにする</span>（cố gắng đi ngủ sớm）</span><br>Việc không muốn làm: thể ない ＋ ようにする<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないようにする</span>（cố gắng không quên）</span><br>Muốn nói lịch sự thì chỉ cần đổi phần cuối: <span class='gd-pair'><span class='gd-jp'>ようにする</span> → <span class='gd-jp'>ようにします</span></span></div><div class='gd-h'>Ba kiểu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>Thói quen bạn vẫn đang duy trì gần đây, là dạng dùng nhiều nhất trong đời sống hằng ngày.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎晩10時までに寝るようにしている。</span>（Mình luôn cố đi ngủ trước 10 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>エレベーターより階段を使うようにしている。</span>（Mình luôn cố đi cầu thang bộ thay vì đi thang máy）</div><div class='gd-sec'><span class='gd-tag'>ようにする</span>Từ bây giờ sẽ chú ý.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅刻しないようにします。</span>（Từ giờ tôi sẽ chú ý không đi trễ）</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>Nhờ đối phương cố gắng làm, bác sĩ và giáo viên rất hay nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>水をたくさん飲むようにしてください。</span>（Hãy cố gắng uống nhiều nước）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước chỉ nối được với thể từ điển hoặc thể ない, không nối với thể ます hay thể た. Không được nói 寝ますようにする、寝たようにする; muốn lịch sự thì đổi phần đuôi: <span class='gd-jp'>寝るようにします</span>。<br>・Muốn nói \"bình thường mình vẫn luôn ～\" thì dùng <b>ようにしている</b>; còn <b>ようにする／ようにします</b> nghe như \"từ giờ mình sẽ chú ý\", tức là chưa bắt đầu làm.<br>・Chỉ dùng được cho <b>việc bạn tự kiểm soát được</b>. Ví dụ \"mong trời đừng mưa\" thì không dùng ようにする được, vì mưa hay không không do bạn quyết định.<br>・<span class='gd-jp'>ようにしてください</span> mang giọng nhắc nhở, chỉ dẫn; bác sĩ nói với bệnh nhân hay giáo viên nói với học sinh thì rất tự nhiên, nhưng nói với cấp trên hay khách hàng thì nghe như đang dạy họ làm việc, nên hãy cẩn thận.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng là chuyện \"nói tiếng Nhật\", đổi phần đuôi một chút là nghĩa khác hẳn:<br><b>ようになる</b>＝ dần dần <b>trở nên</b> như vậy (kết quả)：<span class='gd-jp'>日本語が話せるようになった。</span>（Mình đã nói được tiếng Nhật rồi）<br><b>ようにする</b>＝ tự mình <b>chủ ý làm</b> (nỗ lực)：<span class='gd-jp'>毎日日本語を話すようにしている。</span>（Mỗi ngày mình đều cố nói tiếng Nhật）<br><b>ことにする</b>＝ <b>đưa ra một quyết định</b>：<span class='gd-jp'>毎日日本語を話すことにした。</span>（Mình quyết định mỗi ngày sẽ nói tiếng Nhật）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: \"đã trở nên ～\" là ようになる, \"cố gắng ～\" là ようにする, \"quyết định ～\" là ことにする.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜ようになる」(trở nên ～) thường xuất hiện cùng bài này, bạn có thể học tiếp. Ngoài ra còn có một mẫu「〜ように」với nghĩa \"để (cho) ～\", ví dụ: <span class='gd-jp'>忘れないように、メモしておく。</span>（Để không quên, mình ghi chú lại trước）Mẫu này trông rất giống ようにする, khi học đến thì bạn hãy đối chiếu thêm nhé.</div>","n3-40":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようになる」nghĩa là <b>「giờ đã biết ~ rồi」「bắt đầu ~ rồi」</b>. Điểm mấu chốt là <b>trước đây không như vậy, bây giờ đã thay đổi</b>. Ví dụ: 「giờ mình dám đi Nhật chơi một mình rồi」「dạo này bé tự xỏ giày được rồi」. Khi nói về thay đổi đã xảy ra, thường dùng thể quá khứ「<span class='gd-jp'>ようになった</span>」.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Năng lực thay đổi</span>Trước đây chưa làm được, giờ đã làm được: đặt <b>thể khả năng</b> (dạng diễn tả 「có thể ~, biết ~」) ở phía trước.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読める</span> → <span class='gd-jp'>読めるようになった</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span> → <span class='gd-jp'>起きられるようになった</span></span><br><b>Ngoại lệ</b>: các động từ như <span class='gd-jp'>わかる</span>、<span class='gd-jp'>見える</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>できる</span> tự bản thân đã mang nghĩa 「có thể」, nên dùng thẳng thể từ điển: <span class='gd-jp'>わかるようになった</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>息子がひらがなを読めるようになった。</span>(Con trai mình đã đọc được hiragana rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、泳げるようになった。</span>(Sau khi luyện tập, mình đã biết bơi rồi)</div><div class='gd-sec'><span class='gd-tag'>Thói quen thay đổi</span>Trước đây không làm, giờ bắt đầu làm: thể từ điển＋ようになる.</div><div class='gd-ex-line'>・<span class='gd-jp'>結婚してから、毎日料理するようになった。</span>(Từ khi kết hôn, mình bắt đầu nấu ăn mỗi ngày)</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も通ううちに、店員と雑談するようになった。</span>(Đi nhiều lần rồi, dần dần mình cũng trò chuyện phiếm với nhân viên quán)</div><div class='gd-h'>Ôn nhanh thể khả năng</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「え」cùng cột, rồi thêm る.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → đổi む thành め → <span class='gd-jp'>読める</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ る, thêm られる.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><br><b>Nhóm 3 (học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ようになりたい</span>Mong muốn bản thân trở nên làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語がペラペラ話せるようになりたい。</span>(Mình muốn nói tiếng Nhật trôi chảy)</div><div class='gd-sec'><span class='gd-tag'>ようになる</span>Dùng thể hiện tại để nói 「sau này sẽ trở nên ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習すれば、すぐ泳げるようになりますよ。</span>(Nếu luyện tập mỗi ngày thì sẽ biết bơi ngay thôi đó)</div><div class='gd-sec'><span class='gd-tag'>ようになってきた</span>Đang thay đổi từng chút một.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しわかるようになってきた。</span>(Tiếng Nhật dần dần nghe hiểu được một chút rồi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Muốn nói 「học được, đã biết làm」 thì phải dùng thể khả năng: <span class='gd-jp'>泳げるようになった</span> là 「đã biết bơi」; còn <span class='gd-jp'>泳ぐようになった</span> là 「bắt đầu đi bơi」(thành thói quen), nghĩa khác nhau. Tuy nhiên <span class='gd-jp'>わかる</span>、<span class='gd-jp'>見える</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>できる</span> dùng thẳng thể từ điển, không nói わかれる、見えられる.<br>・Khi muốn nói 「không còn ~ nữa」, trong đời thường hay dùng「なくなる」hơn: <span class='gd-jp'>辛いものが食べられなくなった</span>(không còn ăn được đồ cay nữa)、<span class='gd-jp'>タバコを吸わなくなった</span>(không hút thuốc nữa).<br>・Tiếng Việt hay nói 「trở nên」 cho mọi trường hợp, nhưng khi muốn nói 「trở thành một trạng thái nào đó」, <b>tính từ và danh từ không thể nối trực tiếp với ようになる</b>: 「trở nên bận」 là <span class='gd-jp'>忙しくなった</span>, 「trở nên xinh đẹp」 là <span class='gd-jp'>きれいになった</span>, 「trở thành giáo viên」 là <span class='gd-jp'>先生になった</span>. Bổ sung: danh từ＋<span class='gd-jp'>のようになる</span> là 「trở nên giống như ~」, ví dụ <span class='gd-jp'>先生のようになりたい</span>(muốn trở nên giống như thầy/cô), không phải 「trở thành giáo viên」, nghĩa khác nhau nhé.<br>・Kết quả có được nhờ nỗ lực luyện tập cũng dùng được, không chỉ dùng cho những thay đổi 「tự nhiên mà thành」. Trọng tâm của nó là <b>kết quả đã thay đổi</b>.</div><div class='gd-h'>Phân biệt với các mẫu câu giống nhau</div><div class='gd-sec'>Cùng nói về chuyện 「dậy sớm」:<br><b>ようにする</b>＝cố ý nỗ lực: <span class='gd-jp'>毎朝6時に起きるようにしている。</span>(Mình cố gắng mỗi sáng dậy lúc 6 giờ)<br><b>ようになる</b>＝kết quả đã thay đổi: <span class='gd-jp'>朝6時に起きられるようになった。</span>(Giờ mình dậy được lúc 6 giờ sáng rồi)<br><b>ことになる</b>＝được quyết định, được sắp xếp: <span class='gd-jp'>来月から、6時に出勤することになった。</span>(Từ tháng sau, mình sẽ phải đi làm lúc 6 giờ)</div><div class='gd-warn'>Mẹo phân biệt: 「cố gắng ~」 là ようにする, 「giờ đã làm được ~」 là ようになる, 「được quyết định là sẽ ~」 là ことになる.</div>","n3-45":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜はずだ」nghĩa là <b>「theo lẽ thường thì chắc là ~」</b>. Bạn có căn cứ trong tay (điều đã thấy, đã biết, hoặc đã được sắp xếp từ trước), rồi từ đó suy ra một kết luận khá chắc chắn. Ví dụ thấy nhà bạn đang sáng đèn, bạn nghĩ 「chắc là bạn ấy ở nhà」, tiếng Nhật là <span class='gd-jp'>家にいるはずだ</span>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối thẳng với thể thường (cách nói không có ます、です).<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るはずだ</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たはずだ</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはずだ</span></span></div><div class='gd-sec'><b>Tính từ な</b>: đổi だ thành な.<br><span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なはずだ</span></span></div><div class='gd-sec'><b>Danh từ</b>: đổi だ thành の.<br><span class='gd-pair'><span class='gd-jp'>休みだ</span> → <span class='gd-jp'>休みのはずだ</span></span></div><div class='gd-sec'>Muốn nói lịch sự hơn thì đổi だ thành です: <span class='gd-jp'>来るはずです</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Suy đoán có căn cứ</span>Từ sự thật đã biết mà suy ra kết luận.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者だから、詳しいはずだ。</span>(Anh ấy là bác sĩ nên chắc là rành lắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついているから、家にいるはずだ。</span>(Đèn đang sáng nên chắc là anh ấy ở nhà)</div><div class='gd-sec'><span class='gd-tag'>Theo sắp xếp, theo dự định</span>Lịch trình, việc đã hẹn: theo lẽ thường thì sẽ như thế nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは3時に来るはずです。</span>(Anh Tanaka chắc sẽ đến lúc 3 giờ)</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物は明日届くはずです。</span>(Bưu kiện chắc ngày mai sẽ tới)</div><div class='gd-sec'><span class='gd-tag'>Rõ ràng ~ mà lại…</span>Dùng「はずなのに」khi trong lòng rất chắc chắn nhưng kết quả lại không như vậy, mang cảm giác 「lạ thật」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに置いたはずなのに、ない。</span>(Rõ ràng mình để ở đây mà lại không thấy)</div><div class='gd-sec'><span class='gd-tag'>Hèn chi</span>Cảm nhận kết quả trước, sau mới biết nguyên nhân và chợt vỡ lẽ.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いはずだ。雪が降っている。</span>(Hèn chi lạnh thế, thì ra tuyết đang rơi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Từ 「nên」 trong tiếng Việt có hai kiểu dùng: 「chắc là, hẳn là ~」 (suy đoán) và 「phải, nên ~」 (lời khuyên, nghĩa vụ). <b>はず chỉ có nghĩa thứ nhất</b>. 「Bạn nên đi ngủ sớm」 là lời khuyên, không dùng はず được.<br>・Sau danh từ phải thêm の: nói <span class='gd-jp'>医者のはずだ</span>, không phải 「医者だはずだ」; tính từ な thì nói <span class='gd-jp'>便利なはずだ</span>.<br>・Khi không có căn cứ, chỉ đoán bừa thì đừng dùng はず. はず nghe rất chắc chắn, đoán sai sẽ có vẻ võ đoán.<br>・Đừng dùng はず cho việc mình muốn làm. 「Ngày mai mình định đi」 phải nói <span class='gd-jp'>明日行くつもりだ</span>. はず nói về việc theo lẽ thường, theo sắp xếp sẽ xảy ra, không phải ý muốn của bạn.</div><div class='gd-h'>Phân biệt với các mẫu câu giống nhau</div><div class='gd-sec'><b>はずだ</b>＝theo lẽ thường thì sẽ như vậy (suy đoán): <span class='gd-jp'>会議は3時に始まるはずだ。</span>(Theo lịch thì cuộc họp chắc bắt đầu lúc 3 giờ)<br><b>べきだ</b>＝nên làm như vậy (nghĩa vụ, chủ trương): <span class='gd-jp'>会議は時間どおりに始めるべきだ。</span>(Cuộc họp thì nên bắt đầu đúng giờ)</div><div class='gd-sec'><b>ないはずだ</b>＝theo lẽ thường thì sẽ không (suy đoán bình thản): <span class='gd-jp'>彼は今日来ないはずだ。</span>(Theo lẽ thường thì hôm nay anh ấy sẽ không đến)<br><b>はずがない</b>＝không thể nào (phủ định mạnh): <span class='gd-jp'>彼が来るはずがない。</span>(Anh ấy không thể nào đến được)</div><div class='gd-warn'>Mẹo phân biệt: 「theo lẽ thường thì chắc là ~」 dùng はず, 「nên đi làm ~」 dùng べき; 「chắc là sẽ không」 dùng ないはず, 「không thể nào」 dùng はずがない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Chuyển sang quá khứ「はずだった」＝lẽ ra phải ~, nhưng kết quả lại không: <span class='gd-jp'>3時に着くはずだったのに、電車が遅れた。</span>(Lẽ ra phải đến lúc 3 giờ, nhưng tàu bị trễ)<br>Sau đó bạn có thể học tiếp <span class='gd-jp'>〜はずがない</span> diễn tả 「không thể nào」.</div>","n3-46":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜はずがない」tương đương với <b>「không thể nào ～」「làm gì có chuyện ～」</b> trong tiếng Việt. Trong đầu bạn có sẵn một lý do, ví dụ cô ấy rất cẩn thận, cửa có khóa, anh ấy đã luyện tập lâu như vậy. Suy ra từ lý do đó, kết luận là 「chuyện này tuyệt đối không thể là thật」.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Suy luận theo lẽ thường</span>Bạn có căn cứ trong tay nên rất chắc chắn khi nói 「không thể nào」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女があんなミスをするはずがない。</span>（Cô ấy không thể nào mắc lỗi kiểu đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるはずがない。</span>（Đã luyện tập nhiều như vậy thì không thể nào thua được）</div><div class='gd-sec'><span class='gd-tag'>Không tin vào chuyện trước mắt</span>Gặp tình huống bất ngờ, bạn buột miệng nói 「không thể nào chứ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>え、財布がない？そんなはずない。さっきまであったのに。</span>（Hả, mất ví rồi á? Không thể nào, vừa nãy rõ ràng còn mà）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるはずがない</span></span><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑いはずがない</span></span><br><b>Tính từ な</b>: ở giữa phải thêm「な」.<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なはずがない</span></span><br><b>Danh từ</b>: ở giữa phải thêm「の」.<br><span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人のはずがない</span></span><br>Muốn nói 「không thể nào đã làm」 hoặc 「không thể nào không ～」, bạn đặt thì quá khứ hoặc phủ định ngay trước はず:<br><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはずがない</span></span>（không thể nào đã đi）<br><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないはずがない</span></span>（không thể nào không biết）</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ4月だから、そんなに暑いはずがない。</span>（Mới tháng 4 thôi, không thể nào nóng đến vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>10年も日本に住んでいるんだから、日本語が下手なはずがない。</span>（Sống ở Nhật tới 10 năm rồi, tiếng Nhật không thể nào kém được）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに優しい人が犯人のはずがない。</span>（Một người dịu dàng như vậy không thể nào là thủ phạm）</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'>「が」thường được đổi thành「は」để nhấn mạnh hơn; trong văn nói cũng hay bỏ luôn「が」. Câu nghe nhiều nhất là <span class='gd-jp'>そんなはずはない</span>、<span class='gd-jp'>そんなはずない</span>（không thể nào chứ, sao lại thế được）, bạn hãy học thuộc cả câu.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な không được nối trực tiếp: phải nói <span class='gd-jp'>犯人のはずがない</span>, không phải 「犯人だはずがない」.<br>・Tiếng Việt cũng dùng 「không thể」 và 「không được」 cho nhiều nghĩa khác nhau, còn tiếng Nhật thì tách riêng từng nghĩa. はずがない chỉ dùng cho 「không thể nào (xảy ra)」; 「không được phép」 và 「không biết làm (khả năng)」 đều không dùng nó được. 「Ở đây không được hút thuốc」 là <span class='gd-jp'>ここでたばこを吸ってはいけません</span>, 「Tôi không biết bơi」 là <span class='gd-jp'>泳げません</span>.<br>・<span class='gd-jp'>知らないはずがない</span> nghĩa là 「không thể nào không biết」, tức là 「chắc chắn anh ấy biết」, đừng dịch thành 「không thể biết」.<br>・Giọng rất mạnh. Nói thẳng với ai đó <span class='gd-jp'>あなたにできるはずがない</span>（bạn không thể nào làm được）rất dễ làm tổn thương người ta, hãy cẩn thận.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng một chuyện 「anh ấy có đến không」, nhưng sắc thái mỗi mẫu khác nhau:<br><b>はずだ</b>＝chắc là sẽ (có cơ sở): <span class='gd-jp'>彼は来るはずだ。</span>（Anh ấy chắc sẽ đến）<br><b>ないはずだ</b>＝chắc là sẽ không (nghiêng về phủ định nhưng chưa nói chắc): <span class='gd-jp'>彼は来ないはずだ。</span>（Anh ấy chắc sẽ không đến）<br><b>はずがない</b>＝tuyệt đối không thể (nói chắc chắn): <span class='gd-jp'>彼が来るはずがない。</span>（Anh ấy không thể nào đến）<br><b>わけがない</b>＝nghĩa gần như giống はずがない, phần lớn trường hợp dùng thay nhau được. Nó nghe nhiều hơn trong trò chuyện hằng ngày, giọng mạnh hơn và nhiều cảm xúc hơn: <span class='gd-jp'>彼が来るわけがない。</span>（Anh ấy làm gì có chuyện đến）</div><div class='gd-warn'>Mẹo nhỏ: 「chắc là không」 dùng ないはずだ, 「tuyệt đối không thể」 dùng はずがない; khi nói chuyện với bạn bè hoặc lúc cảm xúc dâng cao thì thường đổi sang わけがない.</div>","n3-48":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことだ」giống câu <b>「nghe tôi đi, bạn cứ ～ đi」「～ là chuẩn rồi」</b> mà người lớn tuổi hay đàn anh nói khi cho bạn lời khuyên. Ví dụ đàn anh bảo bạn 「Muốn đậu N3 à? Cứ mỗi ngày học từ vựng là chuẩn」, tiếng Nhật là <span class='gd-jp'>毎日単語を覚えることだ。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Khuyên đối phương làm gì đó: thể từ điển＋ことだ<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことだ</span></span>（cứ nghỉ ngơi cho tử tế đi）<br>Khuyên đối phương đừng làm: thể ない＋ことだ<br><span class='gd-pair'><span class='gd-jp'>無理をしない</span> → <span class='gd-jp'>無理をしないことだ</span></span>（đừng cố quá）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Cho lời khuyên</span>Phía trước thường nói trước 「nếu bạn muốn ～」「để ～」, rồi phía sau dùng ことだ để đưa ra đáp án.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪のときは、ゆっくり休むことだ。</span>（Khi bị cảm thì cứ nghỉ ngơi thật kỹ đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>やせたいなら、甘いものを減らすことだ。</span>（Muốn gầy thì cứ ăn bớt đồ ngọt đi）</div><div class='gd-sec'><span class='gd-tag'>Khuyên đừng làm</span>Dùng thể ない, giọng như 「bạn đừng ～ nữa」.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の前の日は、夜遅くまで勉強しないことだ。</span>（Hôm trước ngày thi thì đừng thức khuya học bài nữa）</div><div class='gd-sec'>Ngoài lời nói trực tiếp, bạn cũng rất hay gặp cách viết này trong sách truyền cảm hứng, chuyên mục báo, hoặc những chia sẻ kinh nghiệm của đàn anh đàn chị.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đây là giọng <b>người trên nói với người dưới</b>, nghe hơi có cảm giác 「tôi hiểu hơn bạn」. Đừng dùng với thầy cô, cấp trên, khách hàng; kể cả đổi thành <span class='gd-jp'>〜ことです</span> thì vẫn bất lịch sự như vậy. Với người lớn tuổi, bạn có thể đổi sang <span class='gd-jp'>〜たほうがいいと思います</span>.<br>・Phía trước chỉ nối thể từ điển hoặc thể ない, không nối thể た: <span class='gd-jp'>休んだことだ</span> không có nghĩa là 「bạn cứ nghỉ đi」.<br>・Nếu phía trước là tính từ, như <span class='gd-jp'>うらやましいことだ</span>、<span class='gd-jp'>残念なことだ</span>, thì đó là bày tỏ cảm xúc (thật đáng ghen tị, thật đáng tiếc), <b>không phải cho lời khuyên</b>, đừng nhầm.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: bạn bị cảm mà vẫn cố đi làm:<br><b>ことだ</b>＝khuyên riêng bạn: <span class='gd-jp'>今日は休むことだ。</span>（Hôm nay bạn cứ xin nghỉ đi）<br><b>べきだ</b>＝nói theo lẽ phải, nên hay không nên: <span class='gd-jp'>病気のときは休むべきだ。</span>（Khi bệnh thì vốn dĩ phải nghỉ ngơi）. べきだ còn có thể dùng để nhìn lại chuyện đã qua: <span class='gd-jp'>昨日休むべきだった。</span>（Hôm qua lẽ ra phải xin nghỉ）, còn ことだ không có cách dùng này.<br><b>ものだ</b>＝nói theo lẽ thường của xã hội: <span class='gd-jp'>体調が悪いときは無理をしないものだ。</span>（Khi trong người không khỏe thì vốn dĩ không nên cố quá）<br><b>ことはない</b>＝「không cần ～」, dùng để trấn an người khác: <span class='gd-jp'>そんなに心配することはない。</span>（Không cần lo lắng đến vậy）. Khác với <span class='gd-jp'>心配しないことだ。</span>（bạn đừng lo nữa）: câu trước nói 「không cần thiết」, câu sau là khuyên bạn 「đừng」.</div><div class='gd-warn'>Mẹo nhỏ: nói với người trước mặt 「bạn cứ ～ đi」 dùng ことだ; nói theo lẽ phải, nên hay không nên dùng べきだ; nói điều ai cũng biết dùng ものだ; nói 「không cần ～」 dùng ことはない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy xem tiếp <span class='gd-jp'>〜ことはない</span>（không cần ～）và <span class='gd-jp'>〜べきだ</span>（nên ～）. Ba mẫu này học chung với nhau thì khó nhầm nhất.</div>","n3-49":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことはない」nghĩa là <b>“không cần ~ đâu”, “việc gì phải ~”</b>. Khi thấy người khác đang lo lắng, đang xin lỗi hay đang cuống lên, bạn nói với họ “không cần phải thế đâu”, thường mang chút an ủi, khuyên họ thả lỏng.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ ở thể từ điển (dạng gốc như bạn tra trong từ điển) + ことはない.<br><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配することはない</span></span>（không cần lo đâu）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝ることはない</span></span>（không cần xin lỗi đâu）<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急ぐことはない</span></span>（không cần vội đâu）<br>Nói lịch sự hơn thì dùng <span class='gd-jp'>ことはありません</span>. Với bạn bè, người ta hay bỏ「は」thành <span class='gd-jp'>ことない</span>, rồi thêm <span class='gd-jp'>よ</span> ở cuối.</div><div class='gd-h'>Những cách nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>An ủi</span>Khi đối phương đang phiền muộn, tự trách mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>大したことじゃないから、気にすることないよ。</span>（Có gì to tát đâu, đừng bận tâm nhé）</div><div class='gd-sec'><span class='gd-tag'>Bảo đối phương đừng mất công</span>Hay đi cùng 「わざわざ（cất công）」.</div><div class='gd-ex-line'>・<span class='gd-jp'>わざわざ来ることはないよ。電話でいいから。</span>（Không cần cất công đến đâu, gọi điện là được rồi）</div><div class='gd-sec'><span class='gd-tag'>Việc gì phải ~</span>Thêm「何も」ở đầu câu thì thành kiểu hơi bực: “việc gì phải thế chứ”.</div><div class='gd-ex-line'>・<span class='gd-jp'>何もそんなに怒ることはないでしょう。</span>（Việc gì phải giận đến thế chứ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định là <b>thể từ điển</b>. Đổi sang thể た thì nghĩa hoàn toàn khác: “chưa từng ~” (so sánh ở phần dưới).<br>・Nó có nghĩa là “<b>không cần thiết</b>”, chứ không phải “<b>không được</b>”. <span class='gd-jp'>行くことはない</span> là “không cần đi”, bạn muốn đi thì vẫn đi được; còn “cấm đi” phải nói <span class='gd-jp'>行ってはいけない</span>.<br>・Câu này mang giọng “mình đã xét giúp bạn rồi: không cần đâu”, nói với bạn bè, người nhỏ tuổi hơn thì rất tự nhiên. Nếu nói thẳng “〜ことはありません” với cấp trên hay khách hàng, nghe có thể hơi như đang chỉ bảo họ, nên nói <span class='gd-jp'>大丈夫です</span> hoặc <span class='gd-jp'>ご心配なく</span> sẽ an toàn hơn.<br>・Đôi khi nó có nghĩa là “<b>sẽ không xảy ra</b>”: <span class='gd-jp'>もう二度と会うことはないだろう。</span>（Chắc sẽ không bao giờ gặp lại nữa đâu）. Trong ngữ cảnh an ủi, khuyên nhủ thì là “không cần”, còn khi nói về khả năng thì là “sẽ không”, bạn hãy dựa vào ngữ cảnh để phân biệt.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'>Cùng nói “đi Nhật”, chỉ cần đổi dạng của động từ phía trước là nghĩa khác hẳn:<br><b>Thể từ điển＋ことはない</b>＝không cần thiết: <span class='gd-jp'>日本へ行くことはない。</span>（Không cần thiết phải đi Nhật）<br><b>Thể た＋ことはない</b>＝chưa từng làm: <span class='gd-jp'>日本へ行ったことはない。</span>（Tôi chưa từng đi Nhật）<br><b>Thể ない＋ことはない</b>＝cũng không phải là không: <span class='gd-jp'>日本へ行かないことはない。</span>（Không phải là tôi không đi Nhật, thỉnh thoảng vẫn đi）</div><div class='gd-warn'>Mẹo nhỏ: nhìn từ đứng ngay trước「こと」. Dạng gốc là “không cần”, た là “chưa từng làm”, ない là “cũng không phải là không”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu đối lập là「〜ことだ」＝nên làm như vậy: <span class='gd-jp'>心配なら、医者に相談することだ。</span>（Nếu lo thì tốt nhất nên đi hỏi bác sĩ）. Một mẫu khuyên bạn nên làm, một mẫu khuyên bạn không cần làm.<br>Một mẫu có nghĩa khá gần nữa là <span class='gd-jp'>心配する必要はない</span>（không cần phải lo）, giọng khách quan và cứng hơn, thường gặp trong văn viết.</div>","n3-50":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả hai đều nói về “quyết định”, khác nhau ở chỗ <b>ai là người chốt</b>.<br><b>ことにする</b>＝chính mình quyết định: “Tôi quyết định bỏ thuốc”.<br><b>ことになる</b>＝không phải mình chốt, mà là công ty sắp xếp, mọi người bàn bạc ra kết quả, hoặc sự việc tự diễn biến thành như vậy: “Công ty điều tôi đi chi nhánh khác rồi”.<br>“Tôi quyết định ~” ứng với ことにする, còn “rốt cuộc thành ra phải ~”, “được sắp xếp là ~” thì là ことになる.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Việc sẽ làm: thể từ điển＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめることにした</span></span><br>Việc không làm: thể ない＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>帰らない</span> → <span class='gd-jp'>帰らないことにした</span></span></div><div class='gd-h'>Những cách nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>Tự mình đưa ra quyết định.</div><div class='gd-ex-line'>・<span class='gd-jp'>タバコをやめることにした。</span>（Tôi đã quyết định bỏ thuốc lá）</div><div class='gd-ex-line'>・<span class='gd-jp'>今年の夏は実家に帰らないことにした。</span>（Hè năm nay tôi quyết định không về quê）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>Công ty, trường học hay người khác đã quyết xong, mình chỉ chấp nhận kết quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになった。</span>（Từ tháng sau tôi sẽ được điều chuyển đến Osaka）</div><div class='gd-sec'><span class='gd-tag'>Thông báo chuyện của chính mình</span>Dù là do mình tự quyết, khi thông báo tin như kết hôn hay nghỉ việc, người Nhật cũng hay dùng <span class='gd-jp'>ことになりました</span>. Nghe khiêm tốn hơn, như kiểu “mọi chuyện đã đi đến bước này”, chứ không giống nhấn mạnh “là tôi muốn thế”.</div><div class='gd-ex-line'>・<span class='gd-jp'>実は、結婚することになりました。</span>（Thật ra là, tôi sắp kết hôn）</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>Quy tắc tự đặt cho bản thân và vẫn luôn giữ.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（Tôi tự đặt quy tắc là không xem điện thoại trước khi ngủ）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>Quy định, thông lệ, hoặc lịch đã được sắp xếp sẵn.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋では靴を脱ぐことになっています。</span>（Phòng này quy định phải cởi giày）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、田中さんと会うことになっている。</span>（Ngày mai tôi đã hẹn gặp anh Tanaka）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi nói “mình quyết định rồi”, tiếng Nhật thường dùng thì quá khứ <span class='gd-jp'>ことにした</span>, thể hiện quyết định đã được chốt xong.<br>・Với danh từ như 旅行、勉強 có thể thêm する, phải chuyển thành động từ rồi mới ghép: <span class='gd-jp'>旅行することにした</span>, chứ không phải 旅行ことにした. (Danh từ thông thường thì ghép thẳng với にする, ví dụ <span class='gd-jp'>コーヒーにする</span> nghĩa là “chọn ~”, khác với cách dùng ở đây.)<br>・<span class='gd-jp'>ことになる</span> không nhất thiết có người đứng ra quyết định, nó cũng có thể là “cứ thế này thì kết quả sẽ thành ~”: <span class='gd-jp'>今やめたら、後で後悔することになるよ。</span>（Bây giờ bỏ cuộc thì sau này sẽ hối hận đấy）<br>・<span class='gd-jp'>ことにしている</span> là quy tắc do <b>chính mình</b> đặt, còn <span class='gd-jp'>ことになっている</span> là quy định từ <b>bên ngoài</b>, đừng lẫn lộn hai cái này.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'>Cùng nói về “dậy sớm”:<br><b>ことにする</b>＝tự mình quyết định: <span class='gd-jp'>明日から6時に起きることにした。</span>（Tôi quyết định từ ngày mai sẽ dậy lúc 6 giờ）<br><b>ことになる</b>＝được sắp xếp, hoàn cảnh thành ra như vậy: <span class='gd-jp'>仕事の関係で、毎朝6時に起きることになった。</span>（Vì công việc nên mỗi sáng tôi phải dậy lúc 6 giờ）<br><b>ようにする</b>＝cố gắng làm cho được: <span class='gd-jp'>毎朝6時に起きるようにしている。</span>（Mỗi sáng tôi đều cố gắng dậy lúc 6 giờ）<br><b>ようになる</b>＝dần dần trở nên làm được: <span class='gd-jp'>6時に起きられるようになった。</span>（Tôi đã dậy nổi lúc 6 giờ rồi）</div><div class='gd-warn'>Mẹo nhỏ: cảm giác “quyết định” thì dùng こと, “cố gắng, trở nên” thì dùng よう. Sau đó xem ai là người quyết: tự mình chốt thì dùng する, người khác sắp xếp hoặc tự nhiên thành như vậy thì dùng なる.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>ことにする</span> đi với thì quá khứ còn có thể mang nghĩa “coi như là ~”: <span class='gd-jp'>今の話は聞かなかったことにする。</span>（Chuyện vừa nãy tôi coi như chưa nghe thấy gì）</div>","n3-51":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようだ」「〜みたいだ」tương đương với <b>「hình như ~」「có vẻ là ~」</b> trong tiếng Việt. Khi bạn nhìn, nghe hoặc cảm nhận được một vài manh mối rồi tự suy ra một nhận định nhưng chưa chắc chắn 100%, bạn dùng mẫu này. Hai mẫu có nghĩa giống nhau: <b>みたい là bản nói chuyện, thoải mái hơn</b>, còn ようだ trang trọng hơn, viết văn cũng dùng được.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đoán dựa trên manh mối</span>Manh mối là thứ <b>chính bạn</b> nhìn thấy, nghe thấy hoặc cảm nhận được.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋、電気が消えている。留守のようだ。</span>(Phòng bên cạnh tắt đèn, hình như không có ai ở nhà)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵がない。どこかで落としたみたい。</span>(Ơ, mất chìa khóa rồi, hình như mình làm rơi ở đâu đó)</div><div class='gd-sec'>Khi nói về tình trạng cơ thể của chính mình cũng rất hay dùng, với ý「mình cảm thấy là vậy, nhưng không chắc」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと熱があるみたい。</span>(Hình như mình hơi bị sốt)</div><div class='gd-sec'><span class='gd-tag'>Giống như ~</span>Rõ ràng không phải vậy nhưng trông rất giống. Thường đi cùng <span class='gd-jp'>まるで</span> (cứ như là).</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢みたい。</span>(Cứ như đang mơ vậy)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春のように暖かい。</span>(Hôm nay ấm áp như mùa xuân)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối thẳng với thể thường (tức cách nói không có ます, です), hai mẫu giống nhau.<br><span class='gd-pair'><span class='gd-jp'>降っている</span> → <span class='gd-jp'>降っているようだ</span></span>／<span class='gd-jp'>降っているみたいだ</span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いようだ</span></span>／<span class='gd-jp'>寒いみたいだ</span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: ở đây hai mẫu khác nhau, bạn nhớ kỹ nhé.<br>Danh từ + ようだ phải thêm「の」trước: <span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守のようだ</span></span><br>Danh từ + みたいだ nối thẳng: <span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守みたいだ</span></span><br>Tính từ な + ようだ phải thêm「な」trước: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようだ</span></span><br>Tính từ な + みたいだ nối thẳng: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいだ</span></span></div><div class='gd-sec'>Khi nói chuyện quá khứ, danh từ và tính từ な chuyển thành「だった」rồi mới nối, lúc này hai mẫu lại giống nhau: <span class='gd-pair'><span class='gd-jp'>留守だった</span> → <span class='gd-jp'>留守だったようだ</span></span>／<span class='gd-jp'>留守だったみたいだ</span><br>Muốn nói lịch sự thì đổi だ thành です: <span class='gd-jp'>ようです</span>、<span class='gd-jp'>みたいです</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Khi đứng trước danh từ, nó biến thành <b>ような／みたいな</b>; khi đứng trước động từ hoặc tính từ, nó biến thành <b>ように／みたいに</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>お寿司みたいな日本料理が好きです。</span>(Tôi thích các món Nhật như sushi)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人みたいに日本語を話したい。</span>(Tôi muốn nói tiếng Nhật như người Nhật)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ: ようだ cần「の」, còn みたいだ thì không. <span class='gd-jp'>学生のようだ</span>、<span class='gd-jp'>学生みたいだ</span> đều đúng, còn「学生のみたい」「学生ようだ」đều sai.<br>・Nhiều bạn nghĩ thể thường phải có「だ」nên viết thành「留守だみたい」, như vậy là sai. Danh từ ở thì hiện tại nối thẳng: <span class='gd-jp'>留守みたい</span>.<br>・みたい đọc giống「見たい」(muốn xem), nên phải dựa vào ngữ cảnh: <span class='gd-jp'>子供みたい</span> là「giống trẻ con」, còn <span class='gd-jp'>映画が見たい</span> là「muốn xem phim」.<br>・みたい là khẩu ngữ. Khi viết báo cáo, bài luận, thư trang trọng thì dùng ようです; nói chuyện với người lớn tuổi dùng みたいです cũng được, nhưng trong hoàn cảnh trang trọng thì ようです lịch sự hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là「trời mưa」, bạn xem thông tin đến từ đâu:<br><b>ようだ／みたいだ</b> = tự mình thấy manh mối rồi suy ra: <span class='gd-jp'>みんな傘をさしている。雨が降っているみたいだ。</span>(Mọi người đều che ô, hình như trời đang mưa)<br><b>らしい</b> = nghe người khác nói, bản thân chưa xác nhận: <span class='gd-jp'>田中さんの話では、外は雨が降っているらしい。</span>(Nghe anh Tanaka nói, bên ngoài hình như đang mưa)<br><b>そうだ</b> (dáng vẻ) = trước mắt trông như sắp xảy ra, việc đó chưa xảy ra: <span class='gd-jp'>空が暗い。雨が降りそうだ。</span>(Trời tối quá, trông sắp mưa rồi). Cách nối của mẫu này khác: bỏ ます khỏi thể ます rồi thêm そうだ: <span class='gd-pair'><span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそうだ</span></span></div><div class='gd-warn'>Mẹo phân biệt: tự mình thấy, cảm nhận được rồi suy đoán thì dùng ようだ／みたい; nghe người khác nói thì dùng らしい; trông có vẻ「sắp ~」thì dùng そうだ.</div>","n3-52":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「らしい」có hai nghĩa, giống như hai cách nói khác nhau trong tiếng Việt:<br>①<b>「nghe nói ~」「hình như ~」</b>: suy đoán dựa trên thông tin nghe được, đọc được, hoặc những manh mối khách quan nhìn thấy, không phải điều bạn tự mình chắc chắn.<br>②<b>「đúng kiểu ~」「rất ra dáng ~」</b>: giống như bạn nói「đúng chất mùa xuân」「đúng là việc anh ấy sẽ làm」.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>①Nghe nói・Hình như</span>Thuật lại thông tin nghe được, nhìn thấy, đồng thời ngầm nói「mình chỉ nghe nói thôi, không đảm bảo đâu」.</div><div class='gd-ex-line'>・<span class='gd-jp'>来週から気温が下がるらしい。</span>(Nghe nói từ tuần sau nhiệt độ sẽ giảm)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、会社を辞めるらしいよ。</span>(Nghe nói anh Tanaka sắp nghỉ việc đấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメン、すごくおいしいらしい。</span>(Nghe nói mì ramen quán đó ngon lắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>地面が濡れている。雨が降ったらしい。</span>(Mặt đất ướt, hình như vừa mưa xong)</div><div class='gd-sec'><span class='gd-tag'>②Đúng kiểu ~</span>Đặt danh từ phía trước, nghĩa là「hoàn toàn đúng với cảm giác vốn có của thứ đó」, thường mang ý khen.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>(Hôm nay thời tiết đúng chất mùa xuân nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言はいかにも彼らしい。</span>(Phát biểu của anh ấy đúng là phong cách của anh ấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻するなんて、彼らしくない。</span>(Lại đi trễ, không giống anh ấy chút nào)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Nghĩa ①</b><br>Động từ, tính từ い: nối thẳng, quá khứ và phủ định đều được.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span><br>Tính từ な, danh từ: <b>bỏ だ</b> rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → bỏ だ → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>Thì quá khứ thì giữ だった: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'><b>Nghĩa ②</b><br>Danh từ + らしい: <span class='gd-jp'>春らしい</span>、<span class='gd-jp'>学生らしい</span>、<span class='gd-jp'>彼らしい</span><br>Hay thêm <span class='gd-jp'>いかにも</span>、<span class='gd-jp'>本当に</span> để nhấn mạnh, ví dụ <span class='gd-jp'>いかにも先生らしい話し方</span> (cách nói chuyện đúng kiểu thầy cô).</div><div class='gd-sec'>Bản thân「らしい」biến đổi giống tính từ い: <span class='gd-jp'>らしくない</span>、<span class='gd-jp'>らしかった</span>、<span class='gd-jp'>らしいです</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な, danh từ đừng thêm だ: đúng là <span class='gd-jp'>静からしい</span>, không phải 静かだらしい.<br>・<b>Khi nối thẳng với danh từ, cả hai nghĩa đều có thể xảy ra</b>, phải dựa vào ngữ cảnh. Ví dụ <span class='gd-jp'>先生らしい人が来た</span> thường là nghĩa ①「có một người trông có vẻ là giáo viên đến」, chứ không phải「một người rất ra dáng thầy cô」.<br>・Phủ định phải đặt đúng vị trí:「nghe nói anh ấy không đến」là <span class='gd-jp'>来ないらしい</span> (①, phủ định động từ phía trước); còn <span class='gd-jp'>彼らしくない</span> là ②「không giống anh ấy」.<br>・① là「mình nghe được」, nên việc chính mình trải qua thì không dùng được. Nếu chính bạn ngày mai sẽ đi thì nói <span class='gd-jp'>明日行きます</span>, nói「明日行くらしい」nghe như đang kể chuyện của người khác.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>らしい (①)</b> = nghe nói: <span class='gd-jp'>午後から雨が降るらしい。</span>(Nghe nói từ chiều sẽ mưa)<br><b>そうだ (truyền đạt)</b> = nói rõ là thuật lại từ một nguồn tin nào đó: <span class='gd-jp'>天気予報によると、午後から雨が降るそうだ。</span>(Theo dự báo thời tiết, từ chiều sẽ mưa)<br><b>ようだ・みたいだ</b> = tự mình thấy, cảm nhận được: <span class='gd-jp'>傘を持った人が入ってきた。雨が降っているみたい。</span>(Có người cầm ô bước vào, hình như bên ngoài đang mưa)<br>Ngoài ra, khi thấy dấu hiệu ngay trước mắt và cảm thấy sắp xảy ra, dùng <span class='gd-jp'>雨が降りそうだ</span> (trông sắp mưa rồi).</div><div class='gd-warn'>Mẹo phân biệt: chỉ thuật lại nguyên văn tin đã nghe thì dùng そうだ; suy đoán kiểu「chắc là vậy」dựa trên tin nghe được hoặc manh mối khách quan thì dùng らしい; phán đoán theo cảm nhận, trải nghiệm của bản thân thì dùng ようだ・みたいだ.</div><div class='gd-sec'><b>らしい (②) và っぽい</b> cũng hay bị nhầm:<br><span class='gd-jp'>子どもらしい笑顔</span> (nụ cười hồn nhiên đúng kiểu trẻ con): vốn là trẻ con và đúng với dáng vẻ trẻ con nên thiên về khen.<br><span class='gd-jp'>大人なのに子どもっぽい。</span> (Đã là người lớn mà còn trẻ con): không phải trẻ con nhưng lại giống trẻ con, thường mang nghĩa tiêu cực.</div><div class='gd-warn'>Mẹo phân biệt:「vốn là như vậy và rất có cái chất đó」dùng らしい;「thật ra không phải nhưng hơi giống」dùng っぽい.</div>","n3-53":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ために」có hai nghĩa. Nghĩa hay dùng nhất là <b>「để～」</b>, nói về mục đích. Nghĩa còn lại trang trọng hơn, là <b>「vì～」</b>, nói về nguyên nhân. Tiếng Việt có hai từ riêng là \"để\" và \"vì\", còn tiếng Nhật dùng chung một ために, nên bạn phải dựa vào ngữ cảnh để phân biệt.</div><div class='gd-h'>Cách dùng 1: để～ (mục đích)</div><div class='gd-sec'><span class='gd-tag'>Để làm được việc gì đó</span>Động từ dùng <b>thể từ điển</b> (dạng gốc tra trong từ điển) ＋ ために. Danh từ thì phải thêm「の」trước, thành danh từ＋のために.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に留学するために、アルバイトでお金をためている。</span>(Để đi du học Nhật, mình đang làm thêm để tiết kiệm tiền)</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝歩いている。</span>(Vì sức khỏe, sáng nào mình cũng đi bộ)</div><div class='gd-sec'><span class='gd-tag'>Vì ai đó</span>Đặt một người ở phía trước thì nghĩa là \"vì ai\".</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、毎日がんばって働いている。</span>(Vì gia đình, mình cố gắng làm việc mỗi ngày)</div><div class='gd-h'>Cách dùng 2: vì～ (nguyên nhân)</div><div class='gd-sec'><span class='gd-tag'>\"Vì\" kiểu trang trọng</span>Phía trước có thể là: động từ thể た hoặc thể gốc, tính từ い, tính từ な＋な, danh từ＋の. Cách này rất hay gặp trong tin tức, thông báo ở nhà ga và thông cáo. Người ta cũng hay bỏ に và chỉ nói「ため」. Vế sau thường là kết quả đã xảy ra và không mấy tốt, nhưng không phải lúc nào cũng vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、電車が止まった。</span>(Vì tuyết rơi dày, tàu điện đã ngừng chạy)</div><div class='gd-ex-line'>・<span class='gd-jp'>事故があったために、道が混んでいる。</span>(Vì có tai nạn, đường đang bị kẹt xe)</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、今日の授業は休みです。</span>(Vì bão, hôm nay nghỉ học)</div><div class='gd-h'>Làm sao biết là nghĩa nào?</div><div class='gd-sec'>Nếu vế trước là <b>điều bạn muốn đạt được, chưa xảy ra</b>, còn vế sau là nỗ lực để đạt nó, thì đó là \"để\".<br>Nếu vế trước là <b>việc đã xảy ra hoặc một trạng thái</b>, còn vế sau là kết quả do nó gây ra, thì đó là \"vì\".<br>Thấy thể た (<span class='gd-jp'>あった</span>, <span class='gd-jp'>降った</span>) thì chắc chắn là nguyên nhân. Danh từ＋のために có thể là cả hai, nên phải xem vế sau: <span class='gd-jp'>試験のために勉強する</span> (học để thi), <span class='gd-jp'>雪のために遅れた</span> (vì tuyết nên bị trễ).</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải có の: không nói 健康ために, mà phải nói <span class='gd-jp'>健康のために</span>.<br>・Không nối với thể ます: không nói 合格しますために, mà phải nói <span class='gd-jp'>合格するために</span>.<br>・Với ために nghĩa \"để\", hai vế thường có <b>cùng một chủ thể</b>, và vế trước phải là <b>hành động mà bản thân có thể quyết định làm</b>. Những thứ như \"nói được\", \"nghe thấy\", \"hiểu được\" là khả năng hoặc trạng thái, nên phải dùng ように (sẽ so sánh ở dưới).<br>・ために nghĩa \"vì\" rất trang trọng, vế sau không được là lời nhờ vả, rủ rê hay mệnh lệnh. Không nói 雨のために傘を持っていこう, mà nói <span class='gd-jp'>雨だから、傘を持っていこう。</span>(Trời mưa rồi, mang ô đi nhé). Khi trò chuyện bình thường, nói nguyên nhân chỉ cần dùng から, ので là đủ.</div><div class='gd-h'>Phân biệt với mẫu câu giống nó</div><div class='gd-sec'>ために nghĩa \"để\" và <b>ように</b> đều có thể dịch là \"để\", nhưng thứ đặt ở phía trước thì khác nhau.<br>Cùng một việc có thể nói bằng cả hai cách, chỉ là góc nhìn khác nhau:<br>・<span class='gd-jp'>N2に合格するために、毎日勉強している。</span>(Để đậu N2, mình học mỗi ngày): 合格する là việc bạn sẽ chủ động đi đạt được.<br>・<span class='gd-jp'>N2に合格できるように、毎日勉強している。</span>(Hy vọng có thể đậu N2, mình học mỗi ngày): 合格できる là trạng thái bạn mong muốn đạt được.<br>Những câu như dưới đây chỉ dùng được ように:<br>・<span class='gd-jp'>みんなに聞こえるように、大きな声で話した。</span>(Để mọi người đều nghe thấy, mình đã nói thật to)<br>・<span class='gd-jp'>子どもにも読めるように、ひらがなで書いた。</span>(Để trẻ con cũng đọc được, mình đã viết bằng chữ hiragana)<br>聞こえる và 読める là khả năng hoặc trạng thái. Ở câu thứ hai, chủ thể của hai vế còn khác nhau (người viết là mình, người đọc là trẻ con), nên không dùng được ために.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu vế trước là \"hành động bạn chủ động làm\" thì dùng ために. Nếu vế trước là khả năng hay trạng thái như「できる、わかる、聞こえる、見える」, hoặc chủ thể hai vế khác nhau, thì dùng ように.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Về mục đích, bạn xem tiếp「〜ように」(n3-54). Về nguyên nhân, bạn có thể so sánh「〜おかげで」(nhờ～, kết quả tốt) và「〜せいで」(tại～, kết quả xấu). Hai mẫu này còn thể hiện cả sự biết ơn hoặc than phiền của người nói.</div>","n3-54":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ように」tương đương với <b>\"để cho～\"</b> và <b>\"kẻo～\"</b> trong tiếng Việt. Vế trước nói kết quả bạn mong muốn xảy ra, vế sau nói bạn đã làm gì để có kết quả đó: <span class='gd-jp'>後ろの人にも聞こえるように、マイクを使った。</span>(Để người phía sau cũng nghe thấy, mình đã dùng micro)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Khi mong muốn \"có thể～, biết～\": thể từ điển＋ように<br><span class='gd-pair'><span class='gd-jp'>聞こえる</span> → <span class='gd-jp'>聞こえるように</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → trước tiên đổi thành \"nói được\" <span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span><br>Khi mong muốn \"đừng～\": thể ない＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span></div><div class='gd-h'>Phía trước thường đặt những loại nào</div><div class='gd-sec'>Điểm mấu chốt: thứ đặt trước ように là <b>kết quả bạn không thể trực tiếp quyết định</b>, chỉ có thể cố gắng để nó xảy ra. Thường gặp các loại sau:</div><div class='gd-sec'><span class='gd-tag'>Có thể～</span>Phía trước là cách nói \"biết～, có thể～\" (thể khả năng).</div><div class='gd-ex-line'>・<span class='gd-jp'>字幕なしでドラマが見られるように、毎日日本語を聞いています。</span>(Để xem được phim Nhật mà không cần phụ đề, mình nghe tiếng Nhật mỗi ngày)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話せるように、毎日練習している。</span>(Để có thể nói chuyện bằng tiếng Nhật, mình luyện tập mỗi ngày)</div><div class='gd-sec'><span class='gd-tag'>Việc tự nhiên xảy ra</span>Đó là những việc không phải cứ muốn làm là làm được, như <span class='gd-jp'>聞こえる</span> (nghe thấy), <span class='gd-jp'>間に合う</span> (kịp), <span class='gd-jp'>治る</span> (khỏi bệnh).</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪が早く治るように、薬を飲んで寝た。</span>(Để cảm mau khỏi, mình uống thuốc rồi đi ngủ)</div><div class='gd-ex-line'>・<span class='gd-jp'>最終便に間に合うように、早めに空港へ向かった。</span>(Để kịp chuyến bay cuối, mình ra sân bay sớm)</div><div class='gd-sec'><span class='gd-tag'>Đừng～</span>Thể ない＋ように＝kẻo～, để không～. Trường hợp này, ngay cả hành động bản thân kiểm soát được cũng dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておこう。</span>(Kẻo quên, ghi lại trước đi)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅れないように、早めに家を出た。</span>(Để không bị trễ, mình ra khỏi nhà sớm)</div><div class='gd-h'>Bổ sung: chủ thể hai vế có thể khác nhau</div><div class='gd-sec'>Đây không phải một cách dùng khác, mà là một đặc điểm của ように: người ở vế trước có thể khác người ở vế sau. Ở câu dưới đây, người \"hiểu\" là trẻ con, còn người \"giải thích\" là mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもにも分かるように、簡単な言葉で説明した。</span>(Để trẻ con cũng hiểu được, mình đã giải thích bằng từ đơn giản)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Với hành động mà bản thân có thể quyết định làm hay không, <b>dạng khẳng định</b> không được nối thẳng với ように:<br>× 日本語を勉強するように、日本へ来た。<br>○ <span class='gd-jp'>日本語を勉強するために、日本へ来た。</span>(Mình đến Nhật để học tiếng Nhật)<br>・Danh từ＋「のように」nghĩa là \"giống như～\", không liên quan đến nghĩa \"để\" ở đây: <span class='gd-jp'>子どものように笑う</span> (cười như trẻ con).<br>・Sau <span class='gd-jp'>ように</span> là một hành động mới; còn <span class='gd-jp'>ようにする</span> nghĩa là \"mình sẽ cố gắng～\", đừng lẫn lộn: <span class='gd-jp'>忘れないように、メモする</span> (ghi lại để không quên) vs <span class='gd-jp'>忘れないようにする</span> (mình sẽ cố gắng không quên).</div><div class='gd-h'>Phân biệt với mẫu câu giống nó</div><div class='gd-sec'>Cùng là tiết kiệm tiền để đi du học:<br><span class='gd-jp'>留学するために、お金をためている。</span>(Để đi du học, mình đang tiết kiệm tiền)<br><span class='gd-jp'>留学できるように、お金をためている。</span>(Để có thể đi du học, mình đang tiết kiệm tiền)<br>Trước <b>ために</b> là <b>việc chính bạn quyết định làm</b>, \"du học\" chính là mục tiêu. Trước <b>ように</b> là <b>có được hay không, làm được hay không</b>, \"có thể đi du học\" còn phụ thuộc vào việc tiền có đủ hay không.<br>Ngoài ra, hai vế của ために phải cùng một chủ thể, còn ように thì có thể khác chủ thể. ために nối thẳng được với danh từ (<span class='gd-jp'>健康のために</span>), còn ように thì không.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: hành động phía trước do bạn tự quyết định thì dùng ために. Nếu phía trước là \"có thể～\", \"đừng～\", hoặc phải nhờ may mắn hay người khác, thì dùng ように.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜ようにと」dùng để dẫn ra nội dung cầu nguyện hoặc dặn dò, ví dụ <span class='gd-jp'>合格できるようにと祈った</span> (cầu mong đậu được). Bạn cũng có thể quay lại so sánh「〜ようにする」và「〜ようになる」.</div>","n3-55":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようにと」dùng để <b>thuật lại lời dặn của người khác</b>, giống như trong tiếng Việt bạn nói “thầy bảo tụi mình phải đúng giờ” hay “bác sĩ dặn mình ăn bớt muối”. Bạn không lặp lại nguyên văn từng chữ, mà chỉ nói ra ý chính: “người đó muốn mình làm gì”. 「と」 ở cuối giống như dấu ngoặc kép, cho biết phần phía trước là nội dung được dặn.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Việc muốn đối phương làm: thể từ điển＋ようにと　<span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るようにと</span></span><br>Việc muốn đối phương đừng làm: thể ない＋ようにと　<span class='gd-pair'><span class='gd-jp'>遅れない</span> → <span class='gd-jp'>遅れないようにと</span></span><br>Phía sau đi với các động từ “truyền đạt”: <span class='gd-jp'>言う</span>、<span class='gd-jp'>伝える</span>、<span class='gd-jp'>注意する</span>、<span class='gd-jp'>頼む</span>, và cả những động từ diễn tả sự cầu mong như <span class='gd-jp'>祈る</span>、<span class='gd-jp'>願う</span>.</div><div class='gd-sec'>Trong văn nói, 「と」 thường bị lược đi thành 「〜ように言われた」, nghĩa vẫn y hệt. Khi có 「と」 thì nhấn mạnh hơn rằng “đây là nội dung người kia dặn”.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Được dặn</span>「〜ようにと言われた」: ai đó bảo bạn phải làm việc gì đó, đây là dạng dùng nhiều nhất trong đời sống.</div><div class='gd-ex-line'>・<span class='gd-jp'>母に早く帰るようにと言われた。</span>(Mẹ bảo mình về nhà sớm)</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲まないようにと言われた。</span>(Bác sĩ dặn mình đừng uống rượu)</div><div class='gd-sec'><span class='gd-tag'>Nhờ nhắn lại</span>「〜ようにと伝えてください」: nhờ bạn nhắn lại giúp cho người thứ ba.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに、明日は8時に来るようにと伝えてください。</span>(Nhờ bạn nhắn anh Tanaka là ngày mai đến lúc 8 giờ nhé)</div><div class='gd-sec'><span class='gd-tag'>Cầu mong</span>「〜ようにと祈る」: mong một điều gì đó sẽ thành hiện thực.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できるようにと祈った。</span>(Mình đã cầu mong sẽ thi đậu)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Hành động đứng trước ように là việc <b>người được dặn</b> phải làm, không phải người đưa ra lời dặn. Ví dụ <span class='gd-jp'>母に早く帰るように言われた</span>: người phải về nhà sớm là mình, không phải mẹ.<br>・Nội dung lời dặn dùng thể từ điển hoặc thể ない, đừng dùng thể た: nói <span class='gd-jp'>帰るように言われた</span>, không nói 「帰ったように言われた」. Với các động từ như 「言う」「注意する」, trước ように cũng đừng dùng thể ます.<br>・「ように言う」mang sắc thái <b>ra chỉ thị</b>, hợp khi người trên nói với người dưới hoặc với người ngang hàng. Khi nhờ thầy cô hay cấp trên làm việc gì, nếu dùng 「ように言った」 sẽ nghe như đang ra lệnh cho họ; lúc này nói 「〜てくださいとお願いした」 sẽ lịch sự hơn.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>「」と言った</b>＝trích dẫn trực tiếp đúng nguyên văn: <span class='gd-jp'>先生は「時間を守りなさい」と言った。</span>(Thầy nói: “Hãy giữ đúng giờ!”)<br><b>ようにと言った</b>＝thuật lại phần ý chính: <span class='gd-jp'>先生は時間を守るようにと言った。</span>(Thầy bảo tụi mình phải đúng giờ)<br>「〜なさい」「〜てください」 trong lời gốc, khi thuật lại sẽ biến thành 「〜ように」.</div><div class='gd-sec'><b>ように (để)</b>＝tự mình làm việc gì đó vì một mục đích: <span class='gd-jp'>忘れないようにメモした。</span>(Mình ghi chú lại để không quên)<br><b>ようにと (lời dặn)</b>＝người khác bảo mình làm việc gì đó: <span class='gd-jp'>忘れないようにと言われた。</span>(Có người dặn mình đừng quên)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu sau ように là các động từ truyền đạt như 「言う、伝える、注意する、頼む」 thì là “lời dặn”; nếu sau đó là hành động của chính mình thì là “để (mục đích)”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi việc được dặn trở thành thói quen của chính mình, ta có 「〜ようにしている」: <span class='gd-jp'>医者に言われてから、塩分を控えるようにしている。</span>(Từ khi được bác sĩ nhắc, mình cố gắng ăn ít muối)</div>","n3-56":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことから」nghĩa là <b>“từ điểm ~ mà ra ~”</b>. Giống hướng dẫn viên du lịch giới thiệu: “Ngọn núi này trông giống cái nồi nên được gọi là 鍋山”; cũng giống thám tử suy luận: “Nhìn cửa sổ bị vỡ thì biết là có trộm vào rồi”. Phía trước đặt một <b>sự thật nhìn thấy được</b>, phía sau nói về <b>cái tên</b> hoặc <b>kết luận</b> rút ra từ sự thật đó.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nguồn gốc cái tên</span>Giải thích vì sao có tên này, vì sao được gọi như vậy. Phía sau thường đi với 「<span class='gd-jp'>〜と呼ばれる</span>」「<span class='gd-jp'>〜という名前がついた</span>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>山の形が鍋に似ていることから、「鍋山」という名前がついた。</span>(Vì hình dáng ngọn núi giống cái nồi nên được đặt tên là 「鍋山」)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつも笑顔でいることから、彼は「太陽」と呼ばれている。</span>(Vì lúc nào cũng tươi cười nên anh ấy được mọi người gọi là 「太陽」)</div><div class='gd-sec'><span class='gd-tag'>Căn cứ để phán đoán</span>Từ một manh mối mà suy ra kết luận. Phía sau thường đi với 「<span class='gd-jp'>〜と分かる</span>」「<span class='gd-jp'>〜と考えられる</span>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が割れていることから、泥棒に入られたと分かった。</span>(Nhìn cửa sổ bị vỡ, biết là có trộm đột nhập)</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、夜の間に雨が降ったと考えられる。</span>(Thấy mặt đường ướt, có thể đoán là ban đêm đã mưa)</div><div class='gd-sec'><span class='gd-tag'>Nêu bối cảnh</span>Trong các bài giới thiệu, bài giải thích, dùng để nói một điều gì đó bắt nguồn từ đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>この地域は温泉が湧いていることから、観光地として知られている。</span>(Vì khu vực này có suối nước nóng phun lên nên nổi tiếng là điểm du lịch)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối trực tiếp với thể thường (cách nói không có ます、です), dùng được cho hiện tại, quá khứ và phủ định.<br><span class='gd-pair'><span class='gd-jp'>似ている</span> → <span class='gd-jp'>似ていることから</span></span><span class='gd-pair'><span class='gd-jp'>割れた</span> → <span class='gd-jp'>割れたことから</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いことから</span></span><br><b>Tính từ な</b>: giữ 「な」, hoặc đổi thành 「である」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなことから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かであることから</span></span><br><b>Danh từ</b>: thêm 「である」 phía sau.<br><span class='gd-pair'><span class='gd-jp'>港町</span> → <span class='gd-jp'>港町であることから</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ phải dùng <b>である</b>: là <span class='gd-jp'>港町であることから</span>, không phải 「港町だことから」, cũng không phải 「港町のことから」.<br>・Đây là cách nói mang tính <b>văn viết, trang trọng</b>, hay xuất hiện trong báo chí, hướng dẫn du lịch, văn giải thích. Nói chuyện với bạn bè mà dùng 「〜ことから」 sẽ rất cứng, bình thường cứ dùng 「から」「ので」 là được.<br>・Phía sau chỉ đặt được <b>sự thật, tên gọi, nhận định</b>, không đi với lời rủ rê, nhờ vả, ra lệnh kiểu “~ nhé”, “hãy ~”, “~ đi”.<br>・Lý do ở phía trước phải là <b>sự thật ai cũng thấy, có thể kiểm chứng</b>, không hợp để đặt cảm xúc hay lý do biện hộ của bản thân. Muốn nói “Vì mình mệt nên về trước nhé” thì dùng 「から」「ので」.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'>Cùng là chuyện “đường ướt”:<br><b>から・ので</b>＝“vì” trong đời thường, phía sau nói gì cũng được, nhắc nhở, rủ rê, nhờ vả đều ổn.</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれているから、気をつけてね。</span>(Đường ướt đấy, cẩn thận nhé)</div><div class='gd-sec'><b>ことから</b>＝“từ sự thật này suy ra kết luận”, phía sau chỉ có thể là nhận định hoặc tên gọi.</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、雨が降ったと分かる。</span>(Từ việc đường ướt, có thể biết là trời đã mưa)</div><div class='gd-sec'>Nếu nói 「道がぬれていることから、気をつけてね」 thì sai, vì phía sau trở thành lời nhắc nhở đối phương.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu tiếng Việt thay được bằng “từ điểm ~ (có thể thấy / nên được gọi là)” thì dùng ことから; còn chỉ đơn giản là “vì” thì dùng から hoặc ので.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi nói về nguồn gốc tên gọi, phía sau gần như luôn là thể bị động 「<span class='gd-jp'>〜と呼ばれている</span>」 (được gọi là ~), nhân tiện bạn có thể ôn lại 「～（ら）れる（受身）」.</div>","n3-57":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たびに」nghĩa là <b>「mỗi lần ~ là lại ~」</b>. Hễ việc phía trước xảy ra thì việc phía sau cũng xảy ra theo, gần như không có ngoại lệ. Ví dụ như \"mỗi lần nghe bài hát này là muốn khóc\" hay \"mỗi lần đi công tác đều mua quà về\" đều dùng mẫu này.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cảm xúc, phản ứng lần nào cũng có</span>Gặp một việc nào đó là trong lòng lại trào lên cùng một cảm giác.</div><div class='gd-ex-line'>・<span class='gd-jp'>この写真を見るたびに、学生時代を思い出す。</span> (Mỗi lần nhìn tấm ảnh này, mình lại nhớ về thời học sinh)</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くたびに、泣いてしまう。</span> (Mỗi lần nghe bài hát này là mình lại khóc)</div><div class='gd-sec'><span class='gd-tag'>Việc lần nào cũng làm</span>Một việc xảy ra là bạn lại làm một hành động cố định.</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のたびにお土産を買って帰る。</span> (Mỗi lần đi công tác, mình đều mua quà mang về)</div><div class='gd-sec'><span class='gd-tag'>Lần nào gặp cũng thấy thay đổi</span>Mỗi lần gặp lại là bạn nhận ra có điều gì đó khác đi.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に会うたびに、背が伸びている。</span> (Mỗi lần gặp cậu ấy, cậu ấy lại cao thêm)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: dùng thể từ điển (dạng gốc bạn tra được trong từ điển) rồi thêm たびに.<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うたびに</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るたびに</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るたびに</span></span></div><div class='gd-sec'><b>Danh từ</b>: thêm「の」ở giữa.<br><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行のたびに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験のたびに</span></span><br>Danh từ đứng trước phải là <b>một sự việc có thể lặp lại</b>, như <span class='gd-jp'>出張</span>, <span class='gd-jp'>旅行</span>, <span class='gd-jp'>試験</span>, <span class='gd-jp'>引っ越し</span>. Cả <span class='gd-jp'>雨のたびに</span> lẫn <span class='gd-jp'>雨が降るたびに</span> đều dùng được.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Dù nói về quá khứ, <b>vế trước vẫn dùng thể từ điển</b>, còn「た」của quá khứ chỉ đặt ở cuối câu thôi: <span class='gd-jp'>子供のころ、祖母の家に行くたびに、お菓子をもらった。</span> (Hồi nhỏ, mỗi lần đến nhà bà là mình đều được cho bánh kẹo) Đừng nói thành「行ったたびに」nhé.<br>・Việc phía trước phải là việc <b>xảy ra nhiều lần</b>. Việc đời người chỉ có một lần (sinh ra, tốt nghiệp đại học) thì không dùng được.<br>・Danh từ phía trước phải chỉ \"một sự việc\". Những danh từ không phải sự việc như <span class='gd-jp'>本</span>, <span class='gd-jp'>先生</span> thì không được, hãy đổi sang động từ: <span class='gd-jp'>本を読むたびに</span> (mỗi lần đọc sách).<br>・Với những việc thường ngày hiển nhiên như đánh răng, ăn sáng, người Nhật thường nói thẳng <span class='gd-jp'>毎朝</span>, <span class='gd-jp'>いつも</span>. Dùng たびに sẽ như đang nhấn mạnh một việc đặc biệt, nghe hơi lạ.<br>・たびに cũng hay được viết bằng chữ Hán là <span class='gd-jp'>度に</span>, cách đọc y hệt, thấy thì đừng tưởng là mẫu ngữ pháp khác.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là việc \"đi Nhật\":<br><span class='gd-jp'>日本へ行くたびに、ラーメンを食べる。</span> (Mỗi lần đi Nhật mình đều ăn ramen)<br>　→ Nhấn mạnh \"lần nào cũng vậy, không bỏ sót lần nào\".<br><span class='gd-jp'>日本へ行くときは、いつもラーメンを食べる。</span> (Khi đi Nhật, mình luôn ăn ramen)<br>　→ Nghĩa gần như giống nhau, nhưng giọng nhẹ nhàng, đời thường hơn.<br><span class='gd-jp'>二年ごとに日本へ行く。</span> (Cứ hai năm mình đi Nhật một lần)<br>　→ Trước <b>ごとに</b> có thể đặt số đếm để nói \"cứ cách bao lâu, cứ mỗi bao nhiêu\". たびに không dùng như vậy được, không thể nói「二年のたびに」.</div><div class='gd-warn'>Mẹo phán đoán: phía trước là <b>con số hoặc khoảng thời gian</b> thì dùng ごとに; phía trước là <b>một sự việc</b> và bạn muốn nói \"mỗi lần ~ là ~\" thì dùng たびに, còn muốn nói nhẹ nhàng hơn thì có thể dùng「ときはいつも」.</div>","n3-58":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を中心に」nghĩa là <b>「lấy ~ làm trung tâm」「lấy ~ làm chính」「chủ yếu là ~」</b>. Coi một thứ nào đó là cốt lõi để mọi việc xoay quanh nó; hoặc dùng để nói trọng tâm, phạm vi chính của một việc nằm ở đâu.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Địa điểm</span>Lấy một nơi làm trung tâm rồi lan rộng, phân bố ra xung quanh.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅を中心に店が並んでいる。</span> (Lấy nhà ga làm trung tâm, các cửa hàng nằm san sát xung quanh)</div><div class='gd-ex-line'>・<span class='gd-jp'>九州を中心に大雨が降った。</span> (Mưa lớn chủ yếu rơi ở khu vực Kyushu)</div><div class='gd-sec'><span class='gd-tag'>Người</span>Lấy một người làm hạt nhân, mọi người hành động xoay quanh người đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんを中心に、新しいチームができた。</span> (Lấy anh Tanaka làm hạt nhân, một nhóm mới đã được lập ra)</div><div class='gd-sec'><span class='gd-tag'>Phạm vi chính・trọng điểm</span>Là \"chủ yếu là ~\", nhưng không có nghĩa là chỉ có mỗi thứ đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>このアニメは子どもを中心に人気がある。</span> (Bộ anime này được yêu thích chủ yếu ở trẻ em)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は文法を中心に復習しよう。</span> (Hôm nay mình ôn tập chủ yếu về ngữ pháp nhé)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước nhất định là <b>danh từ</b>, phía sau nối với hành động hoặc trạng thái:<br><span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅を中心に</span></span>　Cũng có thể nói <span class='gd-jp'>駅を中心にして</span>, <span class='gd-jp'>駅を中心として</span>, nghĩa giống nhau.<br>Khi muốn bổ nghĩa trực tiếp cho danh từ phía sau, đổi thành <b>を中心とした</b> (hoặc <span class='gd-jp'>を中心とする</span>):</div><div class='gd-ex-line'>・<span class='gd-jp'>野菜を中心とした食事</span> (bữa ăn lấy rau củ làm chính)</div><div class='gd-ex-line'>・<span class='gd-jp'>東京を中心とした関東地方</span> (vùng Kanto lấy Tokyo làm trung tâm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ là <b>を</b>: <span class='gd-jp'>駅を中心に</span>, không phải「駅に中心に」hay「駅が中心に」.<br>・Phía trước không thể đặt thẳng động từ, mà phải đặt danh từ. Muốn nói \"lấy việc học làm chính\" thì dùng <span class='gd-jp'>勉強を中心に</span>.<br>・「を中心に」khác với「<b>の</b>中心に」. <span class='gd-jp'>公園の中心に噴水がある。</span> nghĩa là \"ngay chính giữa công viên có một đài phun nước\", chỉ nói về vị trí, không phải \"lấy ~ làm trung tâm rồi triển khai\".<br>・\"Lấy ~ làm chính\" không có nghĩa là \"chỉ có\": <span class='gd-jp'>若者を中心に人気だ</span> nghĩa là giới trẻ đông nhất, nhưng các độ tuổi khác cũng có người thích.<br>・Khi cần bổ nghĩa cho danh từ phía sau, đừng viết「野菜を中心にの食事」, mà phải dùng <span class='gd-jp'>野菜を中心とした食事</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>をはじめ（として）</b> = \"đứng đầu là A, ngoài ra còn B, C…\", tức là <b>nêu ra một ví dụ tiêu biểu</b>, trọng tâm nằm ở chỗ phía sau còn có những thứ khác.<br><b>を中心に</b> = \"chủ yếu là A\", trọng tâm là <b>A là cốt lõi, chiếm tỷ trọng lớn nhất</b>.<br>Thử so sánh trong cùng một tình huống:</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京を中心に人気がある。</span> (Loại bánh kẹo này được yêu thích chủ yếu ở Tokyo)</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京をはじめ、大阪や福岡でも人気がある。</span> (Loại bánh kẹo này được yêu thích ở Tokyo, và cả ở Osaka, Fukuoka nữa)</div><div class='gd-warn'>Mẹo phán đoán: muốn nói \"chủ yếu ở A, xoay quanh A\" thì dùng を中心に; muốn nói \"A là đại diện, B, C cũng như vậy\" thì dùng をはじめ.</div>","n3-59":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を通じて」「〜を通して」có hai nghĩa. Nghĩa thứ nhất là <b>「thông qua ～」</b>: sự việc thành hình nhờ đi qua một người hay một kênh trung gian nào đó, ví dụ \"quen nhau thông qua bạn bè\", \"liên lạc qua mạng\". Nghĩa thứ hai là <b>「suốt cả ～」</b>: phía trước đặt một khoảng thời gian, cho biết từ đầu đến cuối lúc nào cũng như vậy, giống \"quanh năm suốt tháng\" trong tiếng Việt.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Rất đơn giản, gắn thẳng vào sau danh từ:<br><span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達を通じて</span></span><span class='gd-pair'><span class='gd-jp'>一年</span> → <span class='gd-jp'>一年を通して</span></span><br>Khi đặt trước danh từ để bổ nghĩa cho danh từ đó, ở giữa thêm「の」：<span class='gd-jp'>ボランティアを通しての出会い</span>（cuộc gặp gỡ nhờ làm tình nguyện）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thông qua người hoặc kênh</span>Có người đứng giữa làm cầu nối cho bạn, hoặc đi qua các kênh như internet, điện thoại, truyền thông.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を通じて、今の彼女と知り合った。</span>（Tôi quen bạn gái hiện tại thông qua bạn bè）</div><div class='gd-ex-line'>・<span class='gd-jp'>インターネットを通じて、世界中の人と話せる。</span>（Qua internet, có thể trò chuyện với mọi người trên khắp thế giới）</div><div class='gd-sec'><span class='gd-tag'>Thông qua trải nghiệm</span>Trải qua một việc nào đó rồi học được hoặc cảm nhận được điều gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトを通して、敬語の使い方を覚えた。</span>（Qua việc làm thêm, tôi đã học được cách dùng kính ngữ）</div><div class='gd-sec'><span class='gd-tag'>Suốt cả khoảng thời gian</span>Phía trước đặt một khoảng thời gian như「一年」「一生」, cho biết trong suốt khoảng thời gian đó lúc nào cũng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>この島は一年を通して暖かい。</span>（Hòn đảo này quanh năm đều ấm áp）</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父は一生を通じて、同じ会社で働いた。</span>（Ông tôi làm việc ở cùng một công ty suốt cả đời）</div><div class='gd-h'>を通じて và を通して khác nhau chỗ nào</div><div class='gd-sec'>Trong hầu hết trường hợp, <b>hai cách này dùng thay nhau được</b>, nghĩa gần như nhau, bạn không cần căng thẳng. Nếu cứ muốn phân biệt thì:<br><b>を通じて</b> hay dùng với các \"kênh\" như internet, điện thoại, các mối quan hệ.<br><b>を通して</b> mang cảm giác \"tự mình chủ động đi qua, tự mình trải nghiệm\", nên khi nói về kinh nghiệm, luyện tập, thí nghiệm thì rất hay dùng.<br>Lúc không chắc, chọn cái nào cũng không sai quá đâu.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Phương tiện giao thông và dụng cụ thông thường thì không dùng mẫu này</b>: \"đi bằng xe buýt\" là <span class='gd-jp'>バスで行く</span>, \"cắt bằng kéo\" là <span class='gd-jp'>はさみで切る</span>. Không thể nói バスを通して行く. を通じて nói về \"người hoặc kênh đứng ở giữa\", không phải dụng cụ cầm trong tay.<br>・「Thông qua」trong tiếng Việt khá giống を通じて, nhưng \"đỗ kỳ thi / vượt qua kỳ thi\" thì không phải ngữ pháp này, phải nói <span class='gd-jp'>試験に合格する</span>.<br>・Trợ từ phía trước là <b>を</b>, đừng viết thành に.<br>・Với cách dùng \"suốt cả khoảng thời gian\", phía trước phải đặt <b>một khoảng thời gian</b>, ví dụ một năm, cả đời, bốn mùa. Nghĩa là \"suốt cả khoảng đó\", không phải \"sau khi khoảng thời gian đó trôi qua\".<br>・Sắc thái khá trang trọng, rất hay gặp trong tin tức, bài viết, phần tự giới thiệu. Khi trò chuyện với bạn bè mà muốn nói \"bạn giới thiệu\", văn nói thường dùng <span class='gd-jp'>友達の紹介で</span>.</div><div class='gd-h'>Phân biệt với các mẫu trông giống</div><div class='gd-sec'>Cùng là \"nhắn lại cho thầy cô\":<br><span class='gd-jp'>メールで先生に伝えた。</span>（Tôi báo cho thầy bằng email）：<b>で</b>＝dùng công cụ, phương thức nào, là cách bình thường nhất trong đời sống.<br><span class='gd-jp'>先輩を通じて先生に伝えた。</span>（Tôi nhờ đàn anh chuyển lời cho thầy）：<b>を通じて</b>＝có người hoặc kênh ở giữa giúp bạn chuyển lời đi.<br><br>Một mẫu nữa dễ lẫn là <b>によって</b>, nó nói về \"nhờ phương pháp nào mà làm được\" hoặc \"do nguyên nhân nào mà xảy ra\":<br><span class='gd-jp'>この研究によって、病気の原因が分かった。</span>（Nhờ nghiên cứu này, người ta đã tìm ra nguyên nhân của bệnh）<br>Còn nếu quen ai đó nhờ bạn bè giới thiệu, phải nói <span class='gd-jp'>友達を通じて知り合った</span>, không nói友達によって知り合った.</div><div class='gd-warn'>Mẹo phán đoán nhanh: có \"người, kênh, trải nghiệm\" đứng giữa làm cầu nối thì dùng を通じて／を通して; chỉ đơn giản là dùng dụng cụ, đi phương tiện giao thông thì dùng で; nói về phương pháp hoặc nguyên nhân thì dùng によって.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng dạng 「danh từ＋を＋〜」, bạn có thể xem tiếp <span class='gd-jp'>〜を中心に</span>（lấy ～ làm trung tâm）và <span class='gd-jp'>〜をはじめ</span>（mở đầu bằng ～, tiêu biểu là ～）. Mấy mẫu này thường xuất hiện cùng nhau trong một bài viết.</div>","n3-60":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に基づいて」nghĩa là <b>「dựa trên ～」「căn cứ vào ～」</b>, cho biết khi làm một việc thì lấy cái gì làm cơ sở. Đầu phim thường ghi \"phim dựa trên một câu chuyện có thật\", tiếng Nhật chính là <span class='gd-jp'>この映画は実話に基づいている。</span><br>Phía trước đặt cơ sở của việc \"dựa vào đâu mà làm như vậy\", ví dụ sự thật, dữ liệu, quy định, kinh nghiệm.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Phía sau là hành động</span>Danh từ＋に基づいて＋động từ</div><div class='gd-ex-line'>・<span class='gd-jp'>規則に基づいて判断します。</span>（Tôi sẽ phán đoán dựa theo quy định）</div><div class='gd-ex-line'>・<span class='gd-jp'>データに基づいて計画を立てた。</span>（Tôi lập kế hoạch dựa trên số liệu）</div><div class='gd-sec'><span class='gd-tag'>Phía sau là danh từ</span>Danh từ＋に基づく／に基づいた＋danh từ, cả hai dạng đều rất thường gặp.</div><div class='gd-ex-line'>・<span class='gd-jp'>調査結果に基づく報告書</span>（báo cáo viết dựa trên kết quả khảo sát）</div><div class='gd-ex-line'>・<span class='gd-jp'>経験に基づいたアドバイス</span>（lời khuyên dựa trên kinh nghiệm）</div><div class='gd-sec'><span class='gd-tag'>Đặt cuối câu</span>Dùng <span class='gd-jp'>〜に基づいている</span>, nghĩa là \"dựa trên ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>この話は事実に基づいています。</span>（Câu chuyện này dựa trên sự thật）</div><div class='gd-sec'>Trong tin tức, văn bản hành chính bạn còn gặp <span class='gd-jp'>に基づき</span>, nghĩa giống に基づいて, chỉ là mang tính văn viết hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải đặt <b>căn cứ</b>, không thể đặt thẳng một người. \"Theo lời thầy nói\" phải nói <span class='gd-jp'>先生の話に基づいて</span>, không thể nói「先生に基づいて」.<br>・Khi phía sau là danh từ thì phải dùng <b>基づく／基づいた</b>, đừng viết thành「データに基づいて計画」.<br>・Đọc là <b>もとづいて</b>, kana là「づ」chứ không phải「ず」, khi gõ máy phải gõ motodu.<br>・Sắc thái khá trang trọng, thường xuất hiện trong báo cáo, tin tức, môi trường công việc. Khi trò chuyện với bạn bè thì ít dùng.</div><div class='gd-h'>Phân biệt với các mẫu trông giống</div><div class='gd-sec'>Cùng lấy \"dữ liệu\" làm chủ đề, ba cách nói có nghĩa khác nhau:<br><span class='gd-jp'>データについて説明します。</span>（Tôi sẽ giải thích <b>về chính bản dữ liệu này</b>）<br><span class='gd-jp'>データに基づいて説明します。</span>（Tôi sẽ giải thích <b>lấy dữ liệu làm căn cứ</b>, ví dụ giải thích kế hoạch hay kết luận）<br><span class='gd-jp'>データによると、売り上げが増えています。</span>（<b>Theo dữ liệu cho thấy</b>, doanh số đang tăng）<br>「によると」dùng để nêu nguồn tin, phía sau là \"dữ liệu nói gì\", không thể nối với hành động do chính mình làm.</div><div class='gd-warn'>Mẹo phán đoán nhanh: tiếng Việt là \"về ～\" thì dùng について; \"theo ～ cho thấy／nghe nói\" thì dùng によると; \"lấy ～ làm căn cứ để làm, để phán đoán\" thì dùng に基づいて.</div>","n3-62":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「<span class='gd-jp'>〜ものだから</span>」「<span class='gd-jp'>〜もので</span>」giống như tiếng Việt nói <b>\"tại vì … mà, nên mới…\"</b>. Khi đi trễ, bạn nói với sếp: \"Xin lỗi, tại tàu điện bị trễ mà…\". Cái giọng <b>hơi biện hộ một chút, mong đối phương thông cảm</b> đó chính là cách dùng của nó.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Giải thích khi xin lỗi</span>Khi làm sai hoặc gây phiền cho người khác, bạn thêm lý do để nói rằng \"mình không cố ý\".</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、電車が止まっていたものですから。</span>（Xin lỗi, tại tàu điện bị dừng chạy…）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊したもので、遅れてしまいました。</span>（Vì ngủ quên nên mình đã đến trễ）</div><div class='gd-sec'>Ở câu đầu tiên「<span class='gd-jp'>電車が止まっていたものですから。</span>」, câu dừng lại ngay ở「<span class='gd-jp'>ものですから。</span>」. Người nói chỉ nêu lý do, còn vế sau thì bỏ lửng không nói. Kiểu này rất hay nghe khi xin lỗi.</div><div class='gd-sec'><span class='gd-tag'>Giải thích hoàn cảnh của mình</span>Dùng để nhẹ nhàng giải thích vì sao mình không làm được việc gì đó, hoặc vì sao mình làm như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもがまだ小さいもので、夜はあまり出かけられないんです。</span>（Vì con còn nhỏ nên buổi tối mình không đi ra ngoài được nhiều）</div><div class='gd-sec'><span class='gd-tag'>Quá ～ nên đã…</span>Dùng để nói rằng mình không kìm được mà đã làm việc gì đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにおいしかったものだから、全部食べちゃった。</span>（Vì ngon quá nên mình ăn hết sạch luôn）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp với thể thường　<span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊したものだから</span></span><br><b>Tính từ い</b>: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいものだから</span></span><br><b>Tính từ な</b>: phải thêm「な」　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだから</span></span><br><b>Danh từ</b>: cũng phải thêm「な」　<span class='gd-pair'><span class='gd-jp'>初めて</span> → <span class='gd-jp'>初めてなもので</span></span><br>Khi nói chuyện, nó thường được rút gọn thành <span class='gd-jp'>もんだから</span>、<span class='gd-jp'>もんで</span>. Với người lớn tuổi hoặc khách thì nói <span class='gd-jp'>ものですから</span>. Bản thân <span class='gd-jp'>もので</span> đã khá lịch sự nên cũng rất hay dùng trong những dịp trang trọng.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ là「な」chứ không phải「だ」: nói <span class='gd-jp'>静かなものだから</span>, không nói「静かだものだから」.<br>・Vế sau <b>không được dùng mệnh lệnh, nhờ vả, rủ rê hay ý định của bản thân</b>. <span class='gd-jp'>雨が降っているものだから、傘を持っていってください。</span> là câu sai, phải sửa thành <span class='gd-jp'>雨が降っているから、傘を持っていってください。</span>（Trời đang mưa, bạn mang ô đi nhé）<br>・Nó dùng để nói về <b>hoàn cảnh của bản thân, lý do mang tính riêng tư</b>. Ở những chỗ nêu nguyên nhân một cách khách quan như tin tức, báo cáo thì không dùng, mà dùng <span class='gd-jp'>ので</span>、<span class='gd-jp'>ため</span>.<br>・Rõ ràng là lỗi của mình mà cứ dùng mãi thì nghe sẽ giống như đang viện cớ. Khi thật sự có lỗi, xin lỗi cho tử tế trước mới là quan trọng.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>から／ので</b> = chỉ đơn thuần nêu lý do: <span class='gd-jp'>電車が遅れたので、遅刻しました。</span>（Vì tàu điện bị trễ nên mình đã đến muộn）<br><b>ものだから</b> = nêu lý do, rồi thêm ý \"không phải mình cố ý, mong bạn thông cảm\": <span class='gd-jp'>電車が遅れたものですから、遅刻してしまいました。</span>（Tại tàu điện bị trễ mà, nên mình mới đến muộn…）<br>Nếu vế sau là bảo người khác làm gì đó, thì chỉ dùng được から／ので: <span class='gd-jp'>電車が遅れているから、タクシーで行こう。</span>（Tàu điện đang trễ, mình đi taxi đi）</div><div class='gd-sec'><b>ものだ</b> (cuối câu) = cảm thán kiểu \"vốn dĩ là như vậy mà\", không phải để nêu lý do: <span class='gd-jp'>時間が経つのは早いものだ。</span>（Thời gian trôi nhanh thật đấy）<br>Còn <b>ものだから</b> phía sau có thêm「から」hoặc「で」, nên chắc chắn là đang nói về <b>lý do</b>.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: muốn đối phương thông cảm và đang giải thích hoàn cảnh của mình thì dùng ものだから／もので. Nếu vế sau là bảo người ta làm gì hoặc rủ người ta, hãy đổi sang から／ので. Còn câu dừng ở「ものだ。」là cảm thán, không phải lý do.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Trong hội thoại hằng ngày còn có cách nói ngắn hơn và nũng nịu hơn, dùng thẳng <span class='gd-jp'>もん</span> ở cuối câu: <span class='gd-jp'>だって、知らなかったんだもん。</span>（Tại mình đâu có biết mà）Chỉ nói với người rất thân thôi nhé.</div>","n3-63":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「<span class='gd-jp'>さえ</span>」nghĩa là <b>\"ngay cả ～ cũng…\"</b>. Nó cố ý chọn một ví dụ <b>cơ bản nhất, hiển nhiên nhất</b> để nói, với ý \"đến cả cái này còn như vậy thì những cái khác càng khỏi phải nói\". Ví dụ \"bận đến mức không có cả thời gian ăn cơm\", tiếng Nhật nói: <span class='gd-jp'>忙しくて、ご飯を食べる時間さえない。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Nối với danh từ</span>Thêm thẳng <span class='gd-jp'>さえ</span> sau danh từ. 「<span class='gd-jp'>が</span>」「<span class='gd-jp'>を</span>」vốn có phải bỏ đi, để <span class='gd-jp'>さえ</span> thay thế.<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間さえない</span></span>（đến thời gian cũng không có）<br><span class='gd-pair'><span class='gd-jp'>自分の名前を書けない</span> → <span class='gd-jp'>自分の名前さえ書けない</span></span>（đến tên mình cũng không viết được）</div><div class='gd-sec'><span class='gd-tag'>Giữ lại các trợ từ khác</span>「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」thì không cần bỏ, cứ đặt <span class='gd-jp'>さえ</span> ngay phía sau.<br><span class='gd-pair'><span class='gd-jp'>家族に話していない</span> → <span class='gd-jp'>家族にさえ話していない</span></span>（đến người nhà cũng chưa nói）</div><div class='gd-sec'><span class='gd-tag'>Nói \"ngay cả ai đó\"</span>Khi muốn nhấn mạnh \"ngay cả người này cũng ～\", người ta rất hay nói「<span class='gd-jp'>でさえ</span>」: <span class='gd-jp'>子供でさえ知っている。</span>（Ngay cả trẻ con cũng biết）</div><div class='gd-sec'><span class='gd-tag'>Nối với động từ</span>Muốn nói \"ngay cả ～ cũng không ～\", bạn bỏ ます của động từ rồi thêm <span class='gd-jp'>さえしない</span>.<br><span class='gd-pair'><span class='gd-jp'>見ます</span> → bỏ ます → <span class='gd-jp'>見さえしない</span></span>（nhìn cũng không thèm nhìn）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は私の顔を見さえしなかった。</span>（Anh ấy còn không thèm liếc nhìn mặt mình một cái）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Phía sau là phủ định</span>Đây là cách dùng phổ biến nhất: ngay cả việc cơ bản nhất cũng không có, không làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、水を飲む時間さえなかった。</span>（Bận đến mức không có cả thời gian uống nước）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くて、歩くことさえできない。</span>（Chân đau đến mức đi bộ cũng không nổi）</div><div class='gd-sec'><span class='gd-tag'>Phía sau là khẳng định</span>Ngay cả người ít có khả năng nhất cũng biết, cũng làm được, hàm ý là \"người khác càng nên biết, nên làm được\".</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは、子供でさえ知っている。</span>（Chuyện như vậy ngay cả trẻ con cũng biết）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は、先生でさえ間違えた。</span>（Bài này ngay cả thầy cô cũng làm sai）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「<span class='gd-jp'>が</span>」「<span class='gd-jp'>を</span>」nhất định phải bỏ: nói「時間がさえない」là sai, phải nói <span class='gd-jp'>時間さえない</span>. Nhưng「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」thì phải giữ lại, nên là <span class='gd-jp'>家族にさえ</span>, không phải 家族さえ.<br>・<span class='gd-jp'>さえ</span> có sắc thái mạnh hơn và cũng trang trọng hơn. Khi nói chuyện với bạn bè, nhiều người dùng thẳng「<span class='gd-jp'>も</span>」: <span class='gd-jp'>時間もない</span>, nghĩa gần giống nhau, chỉ là cảm giác \"đến cả cái này\" không nặng bằng.<br>・Khi <span class='gd-jp'>さえ</span> đứng một mình thì nghĩa là \"ngay cả ～ cũng\", <b>không phải \"chỉ cần\"</b>. Nhiều bạn thấy <span class='gd-jp'>さえ</span> là dịch ngay thành \"chỉ cần\", nhưng muốn dịch là \"chỉ cần\" thì phía sau nhất định phải có cách nói điều kiện (xem phần tiếp theo).</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về \"thời gian\", nhưng phía sau nối khác nhau thì nghĩa khác hẳn:<br><b>さえ</b> = ngay cả ～ cũng: <span class='gd-jp'>最近は寝る時間さえない。</span>（Dạo này ngay cả thời gian ngủ cũng không có）<br><b>さえ〜ば</b> = chỉ cần ～ là: <span class='gd-jp'>時間さえあれば、旅行に行きたい。</span>（Chỉ cần có thời gian là mình muốn đi du lịch）<br><b>さえ〜たら／なら</b> cũng là \"chỉ cần ～ là\": <span class='gd-jp'>時間さえあったら、行けるのに。</span>（Giá mà có thời gian thì mình đã đi được rồi）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu phía sau <span class='gd-jp'>さえ</span> có cách nói điều kiện kiểu \"nếu ～\" thì đó là \"chỉ cần ～ là\". Cách nói này gồm「〜ば」, và cũng gồm「〜たら」「〜なら」, ví dụ <span class='gd-jp'>あれば</span>、<span class='gd-jp'>あったら</span>、<span class='gd-jp'>あるなら</span>. Nếu phía sau không có cách nói điều kiện như vậy, thì đó là \"ngay cả ～ cũng\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo hãy học「<span class='gd-jp'>〜さえ〜ば</span>」(chỉ cần ～ là): <span class='gd-jp'>この薬さえ飲めば、すぐ治りますよ。</span>（Chỉ cần uống thuốc này là sẽ khỏi ngay thôi）</div>","n3-64":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜こそ」giống như dùng <b>bút dạ quang</b> tô đậm từ đứng trước. Nghĩa là 「<b>chính là cái này</b>」「<b>cái này mới là ～</b>」「<b>lần này nhất định ～</b>」. <span class='gd-jp'>今年頑張る</span> chỉ là \"năm nay sẽ cố gắng\". Còn <span class='gd-jp'>今年こそ頑張る</span> thành \"năm nay nhất định phải cố hết sức\", giọng mạnh hơn hẳn.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Lần này nhất định</span>Trước đó bạn từng thất bại, lần này quyết tâm làm cho bằng được. Hay đi cùng <span class='gd-jp'>今年</span>、<span class='gd-jp'>明日</span>、<span class='gd-jp'>次</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>今年こそ合格するぞ。</span>(Năm nay nhất định phải đậu!)</div><div class='gd-ex-line'>・<span class='gd-jp'>次こそ負けないよ。</span>(Lần sau chắc chắn sẽ không thua đâu)</div><div class='gd-sec'><span class='gd-tag'>Tôi mới là người ～</span>Khi đối phương cảm ơn, xin lỗi hoặc nói \"mong được giúp đỡ\", bạn đáp lại kiểu \"Không đâu, tôi mới là người phải nói câu đó\". <span class='gd-jp'>こちらこそ</span> có thể dùng thành một câu độc lập, rất tiện.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：いつもありがとう。　B：こちらこそ。</span>(A: Lúc nào cũng cảm ơn bạn nhé. B: Tôi mới phải cảm ơn bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>A：遅れてすみません。　B：いえ、こちらこそすみません。</span>(A: Xin lỗi vì tôi đến muộn. B: Không sao, tôi mới là người phải xin lỗi)</div><div class='gd-sec'><span class='gd-tag'>Chính là cái này</span>Nhấn mạnh \"không phải cái khác, chính là nó\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今こそ挑戦するときだ。</span>(Bây giờ chính là lúc để thử thách)</div><div class='gd-ex-line'>・<span class='gd-jp'>これこそ私が探していた本だ。</span>(Đây chính là cuốn sách tôi đã tìm bấy lâu)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Về cơ bản là <b>danh từ＋こそ</b>. Nếu câu gốc có <span class='gd-jp'>は</span> hoặc <span class='gd-jp'>が</span>, bạn đổi thẳng nó thành <span class='gd-jp'>こそ</span>:<br><span class='gd-pair'><span class='gd-jp'>今年は頑張る</span> → <span class='gd-jp'>今年こそ頑張る</span></span><br><span class='gd-pair'><span class='gd-jp'>これが大切だ</span> → <span class='gd-jp'>これこそ大切だ</span></span><br><span class='gd-jp'>を</span> thường cũng được bỏ đi, gắn <span class='gd-jp'>こそ</span> trực tiếp.<br>Còn với các trợ từ như <span class='gd-jp'>に</span>、<span class='gd-jp'>で</span> thì giữ lại, <span class='gd-jp'>こそ</span> đứng sau chúng:</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたにこそ見てほしい。</span>(Người tôi muốn xem nhất chính là bạn)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>は</span>・<span class='gd-jp'>が</span> không được đặt trước <span class='gd-jp'>こそ</span>. Những câu như <span class='gd-jp'>今年はこそ</span>、<span class='gd-jp'>私がこそ</span> đều sai, phải bỏ chúng đi trước. <span class='gd-jp'>を</span> cũng vậy, bình thường sẽ bỏ. Tuy nhiên đặt sau <span class='gd-jp'>こそ</span> thì được, ví dụ <span class='gd-jp'>今年こそは</span>、<span class='gd-jp'>これこそが</span> đều là cách nói thường gặp.<br>・<span class='gd-jp'>こちらこそ</span> rất lịch sự, nhưng đổi thành <span class='gd-jp'>あなたこそ</span>、<span class='gd-jp'>お前こそ</span> thì thường là vặc lại khi cãi nhau: <span class='gd-jp'>お前こそ何してるんだよ。</span>(Mày mới là đang làm cái quái gì thế hả). Đừng tùy tiện dùng với bề trên.<br>・<span class='gd-jp'>こそ</span> có sắc thái rất mạnh, dùng để tô đậm điểm nhấn. Từ nào cũng thêm vào thì giống như tô dạ quang cả trang, cuối cùng chẳng còn điểm nhấn nào.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng nói về kỳ thi năm nay:<br><span class='gd-jp'>今年は合格したい。</span>(Năm nay tôi muốn đậu): nói bình thường, không có cảm xúc đặc biệt.<br><span class='gd-jp'>今年こそ合格したい。</span>(Năm nay nhất định phải đậu): trước đó chưa đậu, lần này quyết tâm.<br><span class='gd-jp'>こそ</span> thường được học cùng <span class='gd-jp'>さえ</span>, nhưng hai mẫu này đi theo hướng hoàn toàn ngược nhau. <span class='gd-jp'>さえ</span> nghĩa là \"đến cả ～\": nêu một ví dụ cực đoan để ngầm nói những cái khác thì khỏi cần bàn, dùng được cho cả khẳng định lẫn phủ định. Ví dụ <span class='gd-jp'>簡単な問題さえできなかった。</span>(Đến cả bài dễ cũng không làm được), <span class='gd-jp'>子供でさえ知っている。</span>(Đến cả trẻ con cũng biết). Còn <span class='gd-jp'>こそ</span> thì đưa từ đó lên làm nhân vật chính.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"chính là nó\", \"lần này nhất định\", \"tôi mới là người ～\" thì dùng こそ; muốn nói \"đến cả ～\" thì dùng さえ; chỉ nói bình thường thì dùng は.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>からこそ</span>＝\"chính vì ～ nên mới\", nhấn mạnh lý do: <span class='gd-jp'>好きだからこそ、厳しく言うんだ。</span>(Chính vì quan tâm đến bạn nên tôi mới nói nghiêm khắc thế). <span class='gd-jp'>だからこそ</span> cũng rất hay nghe, nghĩa là \"chính vì vậy\".</div>","n3-65":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜そうだ」 nghĩa là <b>\"trông có vẻ ～\"</b>. Bánh chưa ăn, chỉ nhìn thôi đã thấy \"trông ngon quá\", tiếng Nhật nói là <span class='gd-jp'>おいしそう</span>. Điểm mấu chốt là <b>nhìn vẻ bề ngoài trước mắt rồi đoán theo trực giác</b>, chưa thật sự xác nhận.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đoán qua vẻ ngoài</span>Tính từ thêm そう, nghĩa là \"trông có vẻ ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう。</span>(Cái bánh này trông ngon quá)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、今日は元気そうですね。</span>(Anh Tanaka hôm nay trông khỏe nhỉ)</div><div class='gd-sec'><span class='gd-tag'>Sắp xảy ra</span>Động từ thêm そう, phần lớn có nghĩa \"có vẻ sắp ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗くなってきた。雨が降りそうだ。</span>(Trời tối sầm lại rồi, có vẻ sắp mưa)</div><div class='gd-ex-line'>・<span class='gd-jp'>シャツのボタンが取れそう。</span>(Cúc áo sơ mi có vẻ sắp tuột rồi)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Tính từ い</b>: bỏ い ở cuối rồi thêm そう.<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → bỏ い → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高そう</span></span></div><div class='gd-sec'><b>Tính từ な</b>: thêm そう trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>Động từ</b>: chuyển sang dạng ます, bỏ ます rồi thêm そう.<br><span class='gd-pair'><span class='gd-jp'>降ります</span> → bỏ ます → <span class='gd-jp'>降りそう</span></span><span class='gd-pair'><span class='gd-jp'>落ちます</span> → <span class='gd-jp'>落ちそう</span></span></div><div class='gd-sec'><b>Hai trường hợp đặc biệt cần học thuộc</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span></div><div class='gd-sec'>Phía sau muốn nối danh từ thì dùng <b>そうな</b>, nối động từ thì dùng <b>そうに</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>高そうな時計ですね。</span>(Chiếc đồng hồ trông đắt tiền nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>(Bọn trẻ đang chơi trông rất vui)</div><div class='gd-h'>Muốn nói \"trông có vẻ không ～\"</div><div class='gd-sec'>Tính từ: <span class='gd-jp'>おいしくなさそう</span> (trông không ngon), <span class='gd-jp'>暇じゃなさそう</span> (trông không rảnh)<br>Động từ: dùng 「そうにない」 hoặc 「そうもない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は今日中に終わりそうにない。</span>(Công việc này có vẻ không xong trong hôm nay)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>いい</span> không nói được 「いそう」, phải nói <span class='gd-jp'>よさそう</span>: <span class='gd-jp'>天気がよさそうだ</span> (Thời tiết trông có vẻ đẹp).<br>・<b>Danh từ không thể thêm そう kiểu này trực tiếp</b>: ×学生そうだ. Muốn nói \"trông giống sinh viên\" thì dùng <span class='gd-jp'>学生みたいだ</span>.<br>・Việc nhìn là biết ngay, không cần đoán thì không dùng そう: bông hoa màu đỏ cứ nói thẳng <span class='gd-jp'>赤い</span>, không nói 「赤そう」.<br>・<span class='gd-jp'>かわいそう</span> là \"tội nghiệp quá\", không phải \"trông dễ thương\". Thấy dễ thương thì nói thẳng <span class='gd-jp'>かわいい</span>.<br>・そう đi với động từ thường có nghĩa \"sắp ～\": <span class='gd-jp'>泣きそう</span> là \"sắp khóc rồi\", không phải \"hình như đang khóc\".</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cách nói <b>\"nghe nói\" với そうだ</b> (ngữ pháp tiếp theo) trông gần như y hệt, nhưng nghĩa hoàn toàn khác. So sánh trên cùng một việc nhé:<br><span class='gd-jp'>雨が降りそうだ。</span>(Nhìn bầu trời, có vẻ sắp mưa)<br><span class='gd-jp'>雨が降るそうだ。</span>(Nghe dự báo thời tiết nói sẽ mưa)<br><span class='gd-jp'>おいしそうだ。</span>(Trông có vẻ ngon)<br><span class='gd-jp'>おいしいそうだ。</span>(Nghe nói ngon)<br><span class='gd-jp'>元気そうだ。</span>(Trông có vẻ khỏe)<br><span class='gd-jp'>元気だそうだ。</span>(Nghe nói khỏe)<br>Danh từ chỉ có dạng \"nghe nói\": <span class='gd-jp'>学生だそうだ。</span>(Nghe nói là sinh viên)</div><div class='gd-warn'>Mẹo phân biệt:<br>・Động từ, tính từ い: phần trước そう bị cắt ngắn (<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>) ＝ trông có vẻ; phần trước là dạng đầy đủ (<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>) ＝ nghe nói.<br>・Tính từ な, danh từ: xem có 「だ」 hay không. <span class='gd-jp'>元気そうだ</span>＝trông có vẻ khỏe; <span class='gd-jp'>元気だそうだ</span>＝nghe nói khỏe; <span class='gd-jp'>学生だそうだ</span>＝nghe nói là sinh viên.</div><div class='gd-sec'>Ngoài ra, <b>ようだ・みたいだ</b> cũng có nghĩa \"hình như\", nhưng giống một nhận định được đưa ra sau khi tổng hợp nhiều manh mối; còn そう là <b>ấn tượng đầu tiên chỉ qua một cái nhìn</b>. Nhìn thấy cái bánh thì nói <span class='gd-jp'>おいしそう</span>; thấy mọi người ăn rất vui vẻ mới nói <span class='gd-jp'>おいしいみたい</span>.</div>","n3-66":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜そうだ」chính là <b>“nghe nói～”, “theo như người ta nói～”</b> trong tiếng Việt. Khi bạn nghe được một chuyện từ bản tin, từ bạn bè hay từ dự báo thời tiết rồi muốn kể lại cho người khác, bạn chỉ cần thêm そうだ vào cuối câu. Điểm mấu chốt: <b>chuyện này không phải bạn tự nhìn thấy hay tự đoán, mà là do người khác nói</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Truyền đạt tin nghe được</span>Kể lại nguyên văn điều người khác đã nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうです。</span>（Nghe nói anh Tanaka tháng sau sẽ kết hôn）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は今日、会社に来ないそうです。</span>（Nghe nói hôm nay trưởng phòng không đến công ty）</div><div class='gd-sec'><span class='gd-tag'>Nêu nguồn tin</span>Phía trước thường thêm「<span class='gd-jp'>〜によると</span>」「<span class='gd-jp'>〜の話では</span>」để nói rõ tin này nghe từ đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span>（Theo dự báo thời tiết, ngày mai trời sẽ mưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の話では、来週テストがあるそうです。</span>（Nghe thầy cô nói, tuần sau có bài kiểm tra）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước hết đưa nội dung cần truyền đạt về <b>thể thông thường</b> (tức là cách nói không có ます, です), rồi nối そうだ vào sau. Hiện tại hay quá khứ, khẳng định hay phủ định đều được biến đổi ở vế phía trước.<br><b>Động từ</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないそうだ</span></span><br><b>Tính từ い</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いそうだ</span></span><span class='gd-pair'><span class='gd-jp'>寒かった</span> → <span class='gd-jp'>寒かったそうだ</span></span><br><b>Tính từ な</b>：phải thêm だ　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうだ</span></span><br><b>Danh từ</b>：cũng phải thêm だ　<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうだ</span></span><span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったそうだ</span></span><br>Khi nói với thầy cô hoặc khách hàng, hãy đổi phần cuối thành <span class='gd-jp'>そうです</span>.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Giữa bạn bè</span>Khi nói chuyện, người ta hay dùng「<span class='gd-jp'>〜って</span>」「<span class='gd-jp'>〜んだって</span>」hơn, nghĩa vẫn là “nghe nói～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、来月結婚するんだって。</span>（Nghe nói Tanaka tháng sau cưới đấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、雨だって。</span>（Nghe nói mai trời mưa đấy）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ và tính từ な thì <b>không được bỏ だ</b>. Nếu viết <span class='gd-jp'>静かそうだ</span> thì nghĩa thành “trông có vẻ yên tĩnh”, hoàn toàn khác; muốn nói “nghe nói rất yên tĩnh” phải là <span class='gd-jp'>静かだそうだ</span>.<br>・<b>Bản thân そうだ không thể chuyển sang phủ định hay quá khứ</b>. Không thể nói ×<span class='gd-jp'>来るそうではない</span>、×<span class='gd-jp'>来るそうだった</span>. Muốn đổi thì đổi ở vế trước: <span class='gd-jp'>来ないそうだ</span>（nghe nói không đến）、<span class='gd-jp'>来たそうだ</span>（nghe nói đã đến）.<br>・Trong tiếng Việt, “nghe nói” thường đứng ở đầu câu, còn そうだ của tiếng Nhật nhất định phải đặt ở <b>cuối câu</b>.<br>・<span class='gd-jp'>いい</span> khi nói lại tin nghe được là <span class='gd-jp'>いいそうだ</span>（nghe nói khá tốt）; còn <span class='gd-jp'>よさそうだ</span> nghĩa là “trông có vẻ tốt”, thuộc một そうだ khác.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'><b>そうだ chỉ dáng vẻ (n3-65)</b>: chính bạn nhìn thấy, cảm nhận được rằng “trông có vẻ～ / sắp～”. Với động từ thì bỏ ます khỏi thể ます, với tính từ thì bỏ い, rồi nối そうだ.<br><b>そうだ truyền văn (bài này)</b>: người khác nói cho bạn nghe, “nghe nói～”, phía trước nối thể thông thường đầy đủ.<br>Cùng nói về thời tiết:</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだ。</span>（Trông trời sắp mưa: bạn tự nhìn bầu trời và thấy vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降るそうだ。</span>（Nghe nói trời sẽ mưa: nghe từ dự báo）</div><div class='gd-sec'>Cùng nói về cái bánh:</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしそうだ。</span>（Cái bánh này trông có vẻ ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしいそうだ。</span>（Nghe nói cái bánh này ngon）</div><div class='gd-sec'><b>らしい (n3-52)</b> cũng có thể dịch là “nghe nói”, nhưng そうだ là có người nói rõ ràng và bạn kể lại đúng như vậy; còn らしい giống như “hình như là vậy”, nguồn tin mơ hồ hơn, hoặc là bạn tự suy ra từ những gì nghe và thấy.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうだ。</span>（Nghe nói anh Tanaka tháng sau sẽ kết hôn: có người nói với mình như vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するらしい。</span>（Hình như anh Tanaka tháng sau sẽ kết hôn: mình nghe phong thanh）</div><div class='gd-warn'>Mẹo nhận biết: nếu phía trước là dạng đầy đủ「<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>雨だ</span>」thì là “nghe nói”; nếu phía trước là dạng bị cắt ngắn「<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>」thì là “trông có vẻ”.</div>","n3-67":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Hãy tưởng tượng「くる」「いく」là hai mũi tên: <b>くる＝tiến lại gần “chỗ tôi, thời điểm hiện tại”</b>, <b>いく＝rời xa “chỗ tôi, thời điểm hiện tại” để đi ra ngoài</b>. Những cách nói tiếng Việt như “…đến, …lại, …lên, …dần” phần lớn tương ứng với <span class='gd-jp'>てくる</span>, còn “…đi, …tiếp, …mãi” phần lớn tương ứng với <span class='gd-jp'>ていく</span>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang thể て rồi nối くる hoặc いく.<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えて</span> → <span class='gd-jp'>増えてくる</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なっていく</span></span><br>くる và いく phía sau biến đổi như bình thường: <span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきた</span>、<span class='gd-jp'>ていきます</span>、<span class='gd-jp'>ていった</span>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Hướng di chuyển trong không gian</span>Đồ vật hoặc người di chuyển về phía bạn thì dùng てくる; rời khỏi chỗ bạn thì dùng ていく. <b>Quan trọng là lúc nói bạn đang ở đâu.</b></div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていこう。</span>（Trời có vẻ sắp mưa, mang theo ô ra ngoài đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達がケーキを持ってきてくれた。</span>（Bạn mang bánh đến cho mình）</div><div class='gd-sec'><span class='gd-tag'>Đi làm một việc rồi quay lại</span>てくる còn có nghĩa “đi làm việc gì đó, làm xong thì quay về”. Câu <span class='gd-jp'>行ってきます</span> khi ra khỏi nhà chính là “con đi rồi con về”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっとコンビニで飲み物を買ってくる。</span>（Mình đi mua chút đồ uống ở cửa hàng tiện lợi, về ngay）</div><div class='gd-sec'><span class='gd-tag'>Biến đổi: từ trước đến nay</span><span class='gd-jp'>てきた</span>＝thay đổi dần từ trước đến bây giờ, và bây giờ đã cảm nhận được.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が少し分かってきた。</span>（Dạo này mình dần hiểu được một chút tiếng Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここ数年、オンライン会議が増えてきた。</span>（Mấy năm nay, các cuộc họp trực tuyến ngày càng nhiều）</div><div class='gd-sec'><span class='gd-tag'>Biến đổi: từ bây giờ về sau</span><span class='gd-jp'>ていく</span>＝từ bây giờ trở đi, sự việc sẽ tiếp tục thay đổi, tiếp tục diễn ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからどんどん寒くなっていく。</span>（Từ giờ trời sẽ ngày càng lạnh hơn）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語の勉強を続けていきたい。</span>（Từ nay mình cũng muốn tiếp tục học tiếng Nhật）</div><div class='gd-sec'><span class='gd-tag'>Bắt đầu xuất hiện</span><span class='gd-jp'>てきた</span> cũng thường dùng để nói một trạng thái “bắt đầu xuất hiện”, giống như “…lên rồi”, “bắt đầu…rồi” trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（A, trời bắt đầu mưa rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（Mình bắt đầu đói bụng rồi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Hướng được xác định theo <b>vị trí của bạn lúc nói</b>, không phải theo người nghe. Ví dụ ở trường, bạn hứa trực tiếp với thầy cô; bản thân bạn đang ở nơi mà đồ vật sẽ được mang đến, nên nói <span class='gd-jp'>はい、明日持ってきます。</span> rất tự nhiên.<br>・Tiếng Việt nói “mình đi mua”, nếu mua xong sẽ quay lại thì người Nhật thường nói <span class='gd-jp'>買ってくる</span>. Còn <span class='gd-jp'>買っていく</span> là “mua rồi mang đến nơi khác”, ví dụ <span class='gd-jp'>お土産を買っていく</span>（mua quà mang đến đó）.<br>・Khi nói về thời gian, không được lẫn “cho đến bây giờ” với “từ bây giờ trở đi”: phía trước có <span class='gd-jp'>これから</span> thì phải dùng ていく, không thể nói thành「これから寒くなってきた」.<br>・Ở đây くる、いく thường viết bằng hiragana. Thể quá khứ là <span class='gd-jp'>てきた</span>, không phải「てくた」; thể quá khứ của ていく là <span class='gd-jp'>ていった</span>.<br>・Trong văn nói, người ta hay rút ていく thành「てく」: <span class='gd-jp'>寒くなってく</span>, nghe thấy đừng tưởng là ngữ pháp khác.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói “trời trở lạnh”:<br><span class='gd-jp'>寒くなってきた。</span>（Trời đã lạnh dần rồi, bây giờ đã cảm nhận được）<br><span class='gd-jp'>寒くなっていく。</span>（Từ giờ trời sẽ ngày càng lạnh）<br><span class='gd-jp'>寒くなる一方だ。</span>（Cứ lạnh mãi không dừng, thường mang chút bất lực）<br>Hai câu đầu khác nhau ở hướng thời gian, còn <span class='gd-jp'>一方だ</span> nhấn mạnh “cứ phát triển mãi theo một hướng”.</div><div class='gd-warn'>Mẹo nhận biết: nhìn từ quá khứ đến hiện tại thì dùng てきた; nhìn từ hiện tại về sau thì dùng ていく; muốn nói “cứ đi theo hướng xấu, không dừng lại được” thì dùng 一方だ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm ている sau てきた sẽ thành <span class='gd-jp'>てきている</span>, diễn tả “sự thay đổi này hiện vẫn đang tiếp diễn”: <span class='gd-jp'>外国人観光客が増えてきている。</span>（Khách du lịch nước ngoài ngày càng nhiều, và vẫn đang tăng）</div>","n3-68":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả ba mẫu này đều là 「thể て + một cái đuôi nhỏ」, khác nhau ở điều bạn muốn nói:<br><b>ている</b>＝trạng thái hiện tại (đang làm, hoặc một trạng thái cứ được giữ nguyên)<br><b>てある</b>＝đồ vật đã được ai đó làm xong và để nguyên ở đó (nhìn là biết có người cố ý làm)<br><b>ておく</b>＝làm trước, làm sẵn để chuẩn bị cho về sau (tiếng Việt hay nói “làm trước”, “làm sẵn”, “chuẩn bị sẵn”)<br>Hãy tưởng tượng bạn bước vào phòng họp và thấy cửa sổ đang mở. Chỉ tả “cửa sổ đang mở” thì dùng ている. Nói “cửa sổ đã có người mở sẵn rồi” thì dùng てある. Trước giờ họp, bạn tự nói “để tôi mở cửa sổ trước” thì dùng ておく.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Đều gắn vào sau thể て của động từ:<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けて</span></span> → <span class='gd-jp'>開けている</span>／<span class='gd-jp'>開けてある</span>／<span class='gd-jp'>開けておく</span></div><div class='gd-h'>ている：trạng thái hiện tại</div><div class='gd-sec'><span class='gd-tag'>Đang làm</span>Hành động đang diễn ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べている。</span>（Bây giờ tôi đang ăn cơm）</div><div class='gd-sec'><span class='gd-tag'>Giữ trạng thái</span>Sự việc đã xảy ra, và kết quả vẫn còn được giữ nguyên.</div><div class='gd-ex-line'>・<span class='gd-jp'>エアコンがついている。</span>（Máy lạnh đang bật）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚している。</span>（Chị tôi đã kết hôn rồi）</div><div class='gd-h'>てある：có người làm xong, để nguyên đó</div><div class='gd-sec'><span class='gd-tag'>Kết quả + do người làm</span>Trọng tâm là “đồ vật bây giờ đang ở trạng thái này, và là do ai đó cố ý làm”. Người làm là ai thì thường không nhắc đến. Danh từ đứng trước phần lớn dùng <b>が</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアに名前が書いてある。</span>（Trên cửa có viết tên）</div><div class='gd-ex-line'>・<span class='gd-jp'>ビールが冷やしてある。</span>（Bia đã được ướp lạnh sẵn rồi）</div><div class='gd-h'>ておく：làm sẵn trước</div><div class='gd-sec'><span class='gd-tag'>Chuẩn bị trước</span>Làm xong việc đó trước để chuẩn bị cho về sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の前に、ホテルを予約しておく。</span>（Trước chuyến du lịch, đặt khách sạn sẵn）</div><div class='gd-sec'><span class='gd-tag'>Giữ nguyên hiện trạng</span>Cố ý để nó như vậy, tạm thời đừng đụng vào.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓は開けておいてください。</span>（Xin cứ để cửa sổ mở, đừng đóng）</div><div class='gd-sec'>Khi nói chuyện thường rút gọn thành <b>とく</b>：<span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ジュース、買っとくね。</span>（Nước trái cây để mình mua sẵn nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước hết hãy phân biệt hai loại động từ: động từ <b>đồ vật tự biến thành như vậy</b> (<span class='gd-jp'>開く</span>、<span class='gd-jp'>つく</span>、<span class='gd-jp'>閉まる</span>, đi với が) và động từ <b>có người tác động vào nó</b> (<span class='gd-jp'>開ける</span>、<span class='gd-jp'>つける</span>、<span class='gd-jp'>閉める</span>, đi với を).<br>・てある phải đi với loại “có người tác động”: <span class='gd-jp'>窓が開けてある</span> mới đúng, không nói <span class='gd-jp'>窓が開いてある</span>.<br>・<span class='gd-jp'>窓が開けている</span> là sai, vì nghe như “cửa sổ đang mở một thứ gì đó”. Phải nói <span class='gd-jp'>窓が開いている</span> hoặc <span class='gd-jp'>窓が開けてある</span>.<br>・<span class='gd-jp'>結婚している</span> là “đã kết hôn”, không phải “đang làm đám cưới”. <span class='gd-jp'>知っている</span> là “biết”. Đừng thấy ている là dịch ngay thành “đang”.<br>・「てる」trong khẩu ngữ là dạng rút gọn của ている, còn 「とく」mới là của ておく, đừng nhầm lẫn.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'>Cùng một cái cửa sổ, có bốn cách nói:<br>・<span class='gd-jp'>窓が開いている。</span>（Cửa sổ đang mở: chỉ tả cái mình thấy）<br>・<span class='gd-jp'>窓が開けてある。</span>（Cửa sổ đã được ai đó mở sẵn: có cảm giác người ta cố ý mở vì một mục đích）<br>・<span class='gd-jp'>窓を開けておく。</span>（Tôi mở cửa sổ trước: để lát nữa dùng）<br>・<span class='gd-jp'>田中さんが窓を開けている。</span>（Anh Tanaka đang mở cửa sổ: trọng tâm là hành động của người）<br>Ngoài ra, sau khi làm xong <b>ておいた</b>, trạng thái của đồ vật sẽ trở thành <b>てある</b>：<span class='gd-jp'>昨日資料を準備しておいたから、もう準備してある。</span>（Hôm qua đã chuẩn bị sẵn tài liệu rồi, nên giờ đã có sẵn）</div><div class='gd-warn'>Mẹo phán đoán: chỉ tả hình dạng, trạng thái của đồ vật thì dùng 「が＋ている」; muốn nhấn mạnh “có người làm xong và để đó” thì dùng 「が＋てある」; muốn nói “làm sẵn để chuẩn bị cho về sau” thì dùng 「を＋ておく」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜っぱなし」cũng là để đồ vật giữ nguyên như vậy, nhưng phần lớn là <b>quên dọn, bỏ mặc không lo</b>, mang sắc thái không tốt: <span class='gd-jp'>窓を開けっぱなしにした。</span>（Mở cửa sổ rồi để đó không đóng）. Nó hoàn toàn trái ngược với <span class='gd-jp'>開けておく</span>, tức là cố ý để mở.</div>","n3-69":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt chỉ cần nói “giúp” hay “cho” là xong: anh ấy giúp tôi, tôi giúp anh ấy, tôi nhờ anh ấy giúp. Còn tiếng Nhật thì thêm <b>くれる、あげる、もらう</b> sau động từ để cho biết “ơn nghĩa” này đi theo hướng nào.<br><b>くれる</b>：người khác → tôi (người khác làm giúp tôi)<br><b>あげる</b>：tôi → người khác (tôi làm giúp người khác)<br><b>もらう</b>：tôi nhận được sự giúp đỡ từ người khác (tôi nhờ người khác làm giúp)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Chia động từ sang thể て trước, rồi gắn trực tiếp vào sau.<br><span class='gd-pair'><span class='gd-jp'>手伝う</span> → <span class='gd-jp'>手伝って</span> → <span class='gd-jp'>手伝ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>教える</span> → <span class='gd-jp'>教えて</span> → <span class='gd-jp'>教えてもらう</span></span></div><div class='gd-h'>Xem riêng từng mẫu: điểm mấu chốt là trợ từ</div><div class='gd-sec'><span class='gd-tag'>てくれる</span>Nhân vật chính là <b>đối phương</b>, người làm đi với <b>が</b>. “Tôi” thường không nói ra. Người nhà của tôi cũng được tính là “phía tôi”, nên cũng dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が引っ越しを手伝ってくれた。</span>（Bạn đã giúp tôi chuyển nhà）</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>（Mẹ đã làm cơm hộp cho tôi）</div><div class='gd-sec'><span class='gd-tag'>てもらう</span>Nhân vật chính là <b>tôi</b>, người làm đi với <b>に</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅員さんに道を教えてもらった。</span>（Tôi đã được nhân viên nhà ga chỉ đường）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生にほめてもらった。</span>（Tôi được thầy/cô khen）</div><div class='gd-sec'><span class='gd-tag'>てあげる</span>Nhân vật chính là tôi. Đối phương đi với trợ từ nào thì <b>tùy vào động từ gốc</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげた。</span>（Tôi đọc sách cho em gái nghe）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を駅まで送ってあげた。</span>（Tôi tiễn bạn ra ga）</div><div class='gd-h'>Dạng hay nghe nhất: nhờ vả người khác</div><div class='gd-sec'>Chuyển thành câu hỏi sẽ thành “bạn giúp tôi ～ được không?”, càng về cuối càng lịch sự.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれる？</span>（Giúp mình một chút được không? Dùng với bạn bè）</div><div class='gd-ex-line'>・<span class='gd-jp'>この書類、確認してもらえますか。</span>（Anh/chị xác nhận giúp tôi tài liệu này được không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少しゆっくり話してもらえませんか。</span>（Anh/chị nói chậm hơn một chút được không ạ?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Nhầm hướng</b>: くれる chỉ hướng về “phía tôi”. “Tôi dạy bạn” không thể nói <span class='gd-jp'>友達に教えてくれた</span>, mà phải nói <span class='gd-jp'>友達に教えてあげた</span>.<br>・<b>Nhầm trợ từ</b>: くれる đi với が, もらう đi với に. <span class='gd-jp'>友達に手伝ってくれた</span> là sai.<br>・<b>Dịch từng chữ sẽ nghe lạnh nhạt</b>: “Anh ấy mua giúp tôi” mà chỉ nói <span class='gd-jp'>彼が買った</span> thì đúng ngữ pháp, nhưng nghe như không hề biết ơn. Khi người khác làm gì cho mình, người Nhật gần như luôn thêm <span class='gd-jp'>くれた</span>.<br>・<b>てあげる rất bất lịch sự với người trên</b>: nó mang cảm giác “tôi ban ơn cho bạn”. Nói với thầy/cô <span class='gd-jp'>荷物を持ってあげます</span> là không được, phải nói <span class='gd-jp'>お持ちします</span> (để em xách giúp ạ). Ngay cả với bạn bè, nói thẳng 「～てあげる」cũng có thể nghe như đang bề trên, nên thường đổi thành <span class='gd-jp'>手伝おうか？</span> (để mình giúp nhé?).<br>・<b>もらう không nhất thiết là “nhờ”</b>: như <span class='gd-jp'>ほめてもらった</span>, bạn đâu có nhờ thầy/cô khen, chỉ là nhận được điều tốt thôi.</div><div class='gd-h'>Phân biệt với các mẫu dễ nhầm</div><div class='gd-sec'>てくれる và てもらう thường nói về <b>cùng một việc</b>, khác ở chỗ ai là nhân vật chính.<br><span class='gd-jp'>田中さんが傘を貸してくれた。</span>（Anh Tanaka cho tôi mượn ô: nhân vật chính là anh Tanaka, trọng tâm là lòng tốt của anh ấy）<br><span class='gd-jp'>田中さんに傘を貸してもらった。</span>（Tôi mượn được ô từ anh Tanaka: nhân vật chính là tôi, thường mang cảm giác “là tôi mở lời trước”）</div><div class='gd-warn'>Mẹo phán đoán: sau người làm là <b>が</b> thì dùng くれる, là <b>に</b> thì dùng もらう. Muốn nhấn mạnh thiện ý của đối phương thì dùng くれる, muốn nói “tôi nhờ người ta, nhận được sự giúp đỡ” thì dùng もらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Với thầy/cô, cấp trên cần đổi sang kính ngữ: くれる → <span class='gd-jp'>くださる</span>, もらう → <span class='gd-jp'>いただく</span>.<br>・<span class='gd-jp'>先生が教えてくださいました。</span>（Thầy/cô đã dạy cho tôi）<br>・<span class='gd-jp'>先生に教えていただきました。</span>（Tôi đã được thầy/cô dạy cho）</div>","n3-70":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜させる」nghĩa là <b>「bắt ai làm ~」「cho ai làm ~」「để ai làm ~」</b>. Mẹ bắt con ăn rau, sếp cho nhân viên về sớm đều dùng mẫu này. Có thể là ép đối phương làm, cũng có thể là đồng ý cho họ làm, bạn phải dựa vào ngữ cảnh.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bắt ai làm</span>Yêu cầu đối phương làm một việc gì đó, thường là người trên nói với người dưới, ví dụ bố mẹ với con, cấp trên với nhân viên.</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせた。</span>（Mẹ bắt con ăn rau）</div><div class='gd-sec'><span class='gd-tag'>Cho ai làm</span>Đối phương vốn đã muốn làm, bạn đồng ý và để họ làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は私を一人で旅行に行かせてくれた。</span>（Bố cho tôi đi du lịch một mình）</div><div class='gd-sec'><span class='gd-tag'>Khiến ai có cảm xúc nào đó</span>Làm ai khóc, làm ai vui, làm ai lo lắng.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女を泣かせてしまった。</span>（Tôi lỡ làm bạn gái khóc mất rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>（Tôi không muốn làm bố mẹ lo lắng）</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm cột「あ」cùng hàng, rồi thêm「せる」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><br>Động từ kết thúc bằng「う」cần đặc biệt chú ý, 「う」đổi thành <b>わ</b>: <span class='gd-pair'><span class='gd-jp'>買う</span> → đổi う thành わ → <span class='gd-jp'>買わせる</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」ở cuối, thêm「させる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べさせる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>（こさせる）</span></div><div class='gd-sec'>「〜させる」sau khi chia xong tự nó là một động từ nhóm 2, nên các dạng sau chia theo quy tắc nhóm 2: <span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせて</span>、<span class='gd-jp'>書かせない</span>.</div><div class='gd-h'>Ai bắt, ai làm: đặt trợ từ thế nào</div><div class='gd-sec'>Mẫu câu cơ bản: <b>người bắt</b> + は／が, <b>người làm</b> + に hoặc を, cuối câu là 〜させる. Người làm dùng に hay を thì xem bản thân hành động có sẵn「を」hay không:<br><b>Hành động vốn đã có「を」đi kèm</b> (đọc sách, ăn cơm, làm bài tập): người làm dùng <b>に</b>, vì を đã dành cho tân ngữ rồi.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に教科書を読ませた。</span>（Thầy cô bắt học sinh đọc sách giáo khoa）</div><div class='gd-sec'><b>Hành động bản thân không có「を」</b> (đi, chơi, khóc, chờ): người làm thường dùng <b>を</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供を公園で遊ばせる。</span>（Cho con chơi ở công viên）</div><div class='gd-sec'>Trường hợp thứ hai cũng có thể dùng に, ví dụ <span class='gd-jp'>子供に自由に遊ばせる</span>, nghe giống kiểu「tôn trọng đối phương, để họ muốn làm gì thì làm」hơn. Mới học thì chỉ cần nhớ quy tắc cơ bản ở trên là đủ.</div><div class='gd-h'>Những dạng bạn hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>〜させてください</span>「Xin hãy cho tôi ~」, dùng khi bạn muốn làm việc gì đó và lịch sự xin đối phương cho phép.</div><div class='gd-ex-line'>・<span class='gd-jp'>少し考えさせてください。</span>（Xin hãy cho tôi suy nghĩ một chút）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで働かせてください。</span>（Xin hãy cho tôi làm việc ở đây）</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>「Để ai phải chờ」, cực kỳ hay dùng khi xin lỗi.</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめん。</span>（Xin lỗi vì để bạn phải chờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>（Xin lỗi đã để quý khách chờ lâu）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ kết thúc bằng「う」phải đổi thành わ: <span class='gd-jp'>買わせる</span>、<span class='gd-jp'>会わせる</span>、<span class='gd-jp'>使わせる</span>, không phải 買あせる.<br>・<span class='gd-jp'>来させる</span> đọc là <b>こさせる</b>, không phải きさせる.<br>・Nhóm 1 đừng thêm「さ」thừa: đúng là <span class='gd-jp'>読ませる</span>, không phải 読まさせる. Người Nhật cũng hay nói sai kiểu này, nhưng thường được coi là không đúng.<br>・Với thầy cô, cấp trên, khách hàng thì không dùng させる, vì nghe như bạn đang ra lệnh cho họ. Muốn nhờ người trên làm gì, hãy dùng「〜てもらう」「〜ていただく」: <span class='gd-jp'>先生に説明していただきました。</span>（Thầy cô đã giải thích giúp tôi）<br>・Tiếng Việt hay nói「Bộ phim này làm mình rất xúc động」, nhưng tiếng Nhật nói thẳng <span class='gd-jp'>この映画に感動した</span> sẽ tự nhiên hơn. Nếu dịch word-by-word thành この映画は私を感動させた thì nghe rất giống văn dịch.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng là việc「dọn phòng」, hãy xem ai bảo, ai làm:<br><b>させる</b>: <span class='gd-jp'>母は私に部屋を掃除させた。</span>（Mẹ bắt tôi dọn phòng: mẹ bảo, tôi làm）<br><b>させられる</b>: <span class='gd-jp'>私は母に部屋を掃除させられた。</span>（Tôi bị mẹ ép phải dọn phòng: vẫn là tôi làm, nhưng nói từ phía tôi thì mang cảm giác không tự nguyện）<br><b>てもらう</b>: <span class='gd-jp'>私は母に部屋を掃除してもらった。</span>（Tôi nhờ mẹ dọn phòng giúp: tôi nhờ, mẹ làm）</div><div class='gd-warn'>Mẹo phân biệt: chủ ngữ bảo người khác làm là させる; chủ ngữ bị ép phải làm là させられる; chủ ngữ nhờ người khác làm giúp mình là てもらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm thể bị động vào させる, ta có <span class='gd-jp'>〜させられる</span>（使役受身）với nghĩa「bị ép làm ~」: <span class='gd-jp'>子供のころ、毎日ピアノを練習させられた。</span>（Hồi nhỏ ngày nào tôi cũng bị ép tập đàn piano）</div>","n3-71":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜（ら）れる」nghĩa là <b>「bị / được ~」</b>. Trọng tâm đặt vào「người chịu tác động」: không phải「thầy mắng tôi」mà là「tôi bị thầy mắng」. Tiếng Nhật còn có một cách dùng đặc biệt: khi có chuyện khiến bạn rất phiền, bạn cũng dùng nó để than phiền kiểu「sao mình xui thế」.</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm cột「あ」cùng hàng, rồi thêm「れる」.<br><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → đổi ぶ thành ば → <span class='gd-jp'>呼ばれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br><b>Động từ kết thúc bằng う cần đặc biệt chú ý</b>: う không đổi thành あ mà đổi thành <b>わ</b>.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買われる</span></span><br>Cách nghĩ đỡ phải nhớ nhất: chia sang thể ない, bỏ ない đi, rồi thêm れる. <span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言われる</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」ở cuối, thêm「られる」.<br><span class='gd-pair'><span class='gd-jp'>褒める</span> → <span class='gd-jp'>褒められる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Chia xong, tự nó là một động từ nhóm 2, nên tiếp tục chia theo quy tắc nhóm 2:<br><span class='gd-pair'><span class='gd-jp'>褒められる</span> → <span class='gd-jp'>褒められた</span></span><span class='gd-pair'><span class='gd-jp'>褒められます</span></span><span class='gd-pair'><span class='gd-jp'>褒められない</span></span></div><div class='gd-h'>Cách ghép câu</div><div class='gd-sec'>Mẫu câu cơ bản: <b>tôi は + người làm hành động に + thể bị động</b>. Sau người làm hành động dùng「に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に叱られた。</span>（Tôi bị thầy mắng）</div><div class='gd-ex-line'>・<span class='gd-jp'>上司にアイデアを褒められた。</span>（Ý tưởng của tôi được sếp khen）</div><div class='gd-sec'>Không nhất thiết là chuyện xấu, được khen hay được chọn cũng dùng được.</div><div class='gd-h'>Những dạng bạn hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Cơ thể, đồ vật bị tác động</span>Bị giẫm chân, bị trộm ví: tiếng Nhật quen nói「tôi + đồ vật を + thể bị động」, nhân vật chính vẫn là「tôi」.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（Bị giẫm vào chân trên tàu điện）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で財布を盗まれた。</span>（Bị trộm mất ví ở nhà ga）</div><div class='gd-sec'><span class='gd-tag'>Xui xẻo, phiền phức</span>Việc người khác làm (thậm chí là thời tiết) khiến bạn khổ sở. Kiểu này tiếng Việt thường không nói được trực tiếp với「bị」(ví dụ「bị em bé khóc」nghe rất lạ), đây là nét rất đặc trưng của tiếng Nhật.</div><div class='gd-ex-line'>・<span class='gd-jp'>帰りに雨に降られた。</span>（Trên đường về bị mưa ướt hết）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に赤ちゃんに泣かれて、全然寝られなかった。</span>（Nửa đêm em bé cứ khóc, làm tôi hoàn toàn không ngủ được）</div><div class='gd-sec'><span class='gd-tag'>Miêu tả khách quan</span>Hay dùng trong tin tức, phần giới thiệu, không mang cảm xúc và không nói ai là người làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>このお寺は500年前に建てられた。</span>（Ngôi chùa này được xây từ 500 năm trước）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ kết thúc bằng う đổi thành <b>わ</b>: đúng là <span class='gd-jp'>買われる</span>, không phải 買あれる.<br>・Người làm hành động dùng「に」: <span class='gd-jp'>先生に叱られた</span> là「tôi bị thầy mắng」; nếu viết <span class='gd-jp'>先生が叱られた</span> thì thành「thầy bị mắng」.<br>・Tiếng Việt nói「chân của mình bị giẫm」, nhưng tiếng Nhật không nói 私の足が踏まれた, mà nói <span class='gd-jp'>足を踏まれた</span>.<br>・Thể bị động của nhóm 2 giống hệt thể khả năng:  <span class='gd-jp'>食べられる</span> có thể là「bị ăn」, cũng có thể là「ăn được」, phải dựa vào ngữ cảnh.<br>・<span class='gd-jp'>来られる</span> đọc là <b>こられる</b>, không phải きられる.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>られる (bị động)</b> = hành động của người khác rơi lên người tôi, tôi là người「chịu」:<br><span class='gd-jp'>弟にケーキを食べられた。</span>（Bánh bị em trai ăn mất rồi）<br><b>させる (sai khiến)</b> = tôi bảo, tôi cho người khác làm:<br><span class='gd-jp'>弟にケーキを食べさせた。</span>（Tôi cho em trai ăn bánh）<br><b>てもらう</b> = người khác làm giúp tôi, tôi biết ơn:<br><span class='gd-jp'>先生に作文を褒めてもらった。</span>（Thầy cô đã khen bài văn của tôi, tôi rất vui）<br>Cùng một việc mà dùng <span class='gd-jp'>褒められた</span> thì chỉ đang nói sự thật「được khen」, không đặc biệt thể hiện lòng biết ơn.</div><div class='gd-warn'>Mẹo phân biệt:「bị / được ~」dùng れる・られる,「bảo ai ~」dùng せる・させる,「người ta giúp tôi ~ (rất biết ơn)」dùng てもらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Ghép sai khiến với bị động lại, ta có nghĩa「bị ép làm ~」: <span class='gd-jp'>母に野菜を食べさせられた。</span>（Bị mẹ ép ăn rau）</div>","n3-72":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜させられる」nghĩa là <b>「bị bắt phải ～」「bị sai đi ～」</b>. Việc đó là <b>chính bạn động tay làm</b>, nhưng bạn không muốn làm, là người khác bắt bạn làm. Khi nói thường mang chút ấm ức, than phiền.</div><div class='gd-h'>Nó từ đâu ra</div><div class='gd-sec'>Đây là hai mẫu ngữ pháp chồng lên nhau: 「させる」＝bắt/sai người khác làm, 「られる」＝bị.<br>Mẹ bảo mình dọn dẹp, nếu nói từ góc nhìn của mẹ thì là:</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私に部屋を掃除させた。</span>（Mẹ bắt tôi dọn phòng）</div><div class='gd-sec'>Đổi sang góc nhìn của <b>tôi</b>, nó thành \"tôi bị mẹ sai đi dọn dẹp\":</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母に部屋を掃除させられた。</span>（Tôi bị mẹ bắt dọn phòng）</div><div class='gd-sec'>Nhân vật chính giờ là \"tôi\", còn người bắt bạn làm thì đi kèm <b>に</b>.</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ năm đoạn)</b>: đổi âm cuối sang âm hàng「あ」cùng hàng, rồi thêm 「される」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わされる</span></span><br>Chú ý: động từ kết thúc bằng 「う」 thì đổi thành 「わ」, không phải 「あ」.<br>Đây là dạng rút gọn hay dùng trong văn nói, dạng đầy đủ là <span class='gd-jp'>書かせられる</span>. Cả hai đều đúng, nhưng trong đời thường bạn sẽ nghe dạng rút gọn nhiều hơn.</div><div class='gd-sec'><b>Ngoại lệ trong nhóm 1: động từ kết thúc bằng 「す」</b> không dùng được dạng rút gọn, phải thêm 「させられる」.<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話させられる</span></span><span class='gd-pair'><span class='gd-jp'>出す</span> → <span class='gd-jp'>出させられる</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ một đoạn)</b>: bỏ 「る」 ở cuối, thêm 「させられる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめさせられる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>（こさせられる）</span><br>Dạng \"danh từ＋する\" như <span class='gd-jp'>残業する</span>、<span class='gd-jp'>スピーチする</span> cũng chia giống vậy：<span class='gd-pair'><span class='gd-jp'>残業する</span> → <span class='gd-jp'>残業させられる</span></span></div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Bị bắt làm</span>Cách dùng cơ bản nhất, để than phiền về việc mình không muốn làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、毎日ピアノを練習させられた。</span>（Hồi nhỏ ngày nào tôi cũng bị bắt tập piano）</div><div class='gd-ex-line'>・<span class='gd-jp'>飲み会でお酒をたくさん飲まされた。</span>（Ở buổi nhậu tôi bị ép uống rất nhiều rượu）</div><div class='gd-sec'><span class='gd-tag'>Bị bắt chờ</span><span class='gd-jp'>待たされる</span> cực kỳ hay dùng, nghĩa là \"bị bắt chờ lâu thật lâu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>病院で一時間も待たされた。</span>（Ở bệnh viện tôi bị bắt chờ cả một tiếng đồng hồ）</div><div class='gd-sec'><span class='gd-tag'>Không khỏi (cảm thấy)</span>Đi với những từ như \"suy nghĩ, cảm động\", nghĩa là \"khiến người ta không thể không ～\", không mang ý than phiền.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画にはいろいろ考えさせられた。</span>（Bộ phim này khiến tôi phải suy nghĩ rất nhiều）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>話す</span> thành <span class='gd-jp'>話させられる</span>, không được nói 「話さされる」. Mọi động từ kết thúc bằng 「す」 đều như vậy.<br>・Người bắt bạn làm thì đi với <b>に</b>：<span class='gd-jp'>先生に作文を書かされた。</span>（Bị thầy cô bắt viết bài văn）<br>・Mẫu này mang cảm giác \"tôi không muốn\". Nếu người ta tốt bụng cho bạn làm và bạn rất biết ơn mà dùng mẫu này thì sẽ thành than phiền, nghe rất bất lịch sự.<br>・Đừng nhầm <span class='gd-jp'>書かされる</span> với thể bị động thông thường <span class='gd-jp'>書かれる</span>: chỉ thêm một chữ 「さ」 là nghĩa đã đổi từ \"bị viết\" thành \"bị bắt phải viết\".</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>られる</b>＝người khác <b>làm gì đó với tôi</b>, người ra tay là đối phương：<span class='gd-jp'>母に叱られた。</span>（Bị mẹ mắng, người mắng là mẹ）<br><b>させられる</b>＝người khác <b>bắt tôi làm</b>, người ra tay là tôi, và tôi không muốn：<span class='gd-jp'>母に掃除させられた。</span>（Bị mẹ sai đi dọn dẹp, người dọn là tôi）</div><div class='gd-sec'>Còn có 「させてもらう」, cũng là người khác cho bạn làm, nhưng tâm trạng hoàn toàn ngược lại:<br><b>させてもらう</b>＝tôi muốn làm, đối phương <b>cho phép</b> tôi, tôi rất biết ơn：<span class='gd-jp'>店長に頼んで、休ませてもらった。</span>（Tôi nhờ quản lý và được cho nghỉ）<br><b>させられる</b>＝tôi không muốn, đối phương <b>ép</b> tôi：<span class='gd-jp'>熱があって、店長に無理やり休まされた。</span>（Tôi bị sốt, bị quản lý ép về nhà nghỉ）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: hỏi trước \"ai ra tay?\". Đối phương ra tay là られる; tôi ra tay mà không tự nguyện là させられる; tôi ra tay và chính tôi muốn làm thì là させてもらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nếu 「させる」「られる」 bạn chưa vững, hãy ôn lại <span class='gd-jp'>〜させる</span> (thể sai khiến) và <span class='gd-jp'>〜られる</span> (thể bị động). Mẫu ngữ pháp này chỉ là hai mẫu đó chồng lên nhau thôi.</div>","n3-73":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ても」nghĩa là <b>\"dù ～ thì cũng ～\", \"bất kể ～ đều ～\"</b>. Dù phía trước xảy ra chuyện gì, kết quả phía sau vẫn <b>không bị ảnh hưởng</b>, vẫn như cũ. Giống như bạn nói \"dù trời mưa tôi cũng đi\", mưa cũng không thay đổi được việc bạn sẽ đi.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っても、行きます。</span>（Dù trời mưa tôi cũng sẽ đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買いたい。</span>（Dù đắt tôi cũng muốn mua）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: chia sang thể て trước, rồi thêm も.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span><br>Động từ mà thể て vốn là 「で」 thì thêm も sẽ thành 「でも」：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span></div><div class='gd-sec'><b>Tính từ い</b>: đổi 「い」 ở cuối thành 「くても」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しくても</span></span></div><div class='gd-sec'><b>Tính từ な・danh từ</b>: thêm thẳng 「でも」.<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手でも</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>料理が下手でも、大丈夫です。</span>（Dù nấu ăn không giỏi cũng không sao）</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日でも、仕事がある。</span>（Dù là Chủ nhật cũng phải làm việc）</div><div class='gd-sec'><b>Phủ định \"dù không ～\"</b>: đổi ない thành なくても.<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Từ nghi vấn＋ても</span>Đặt các từ như \"cái gì, ai, ở đâu, khi nào\" ở phía trước thì thành \"bất kể ～ đều ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>何を食べても、おいしい。</span>（Ăn gì cũng ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつ行っても、混んでいる。</span>（Lúc nào đi cũng đông）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度確認しても、ミスが見つからない。</span>（Kiểm tra bao nhiêu lần vẫn không tìm ra lỗi）</div><div class='gd-sec'><span class='gd-tag'>どんなに／いくら〜ても</span>\"Dù ～ đến mấy cũng ～\", nhấn mạnh rằng mức độ cao đến đâu cũng vô ích.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ご飯は必ず食べる。</span>（Dù bận đến mấy tôi vẫn nhất định ăn sáng）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら練習しても、上手にならない。</span>（Luyện tập bao nhiêu cũng không giỏi lên）</div><div class='gd-sec'><span class='gd-tag'>たとえ〜ても</span>\"Dù cho có ～ đi nữa\", giọng kiên quyết hơn, thường dùng để nói về quyết tâm.</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ反対されても、留学したい。</span>（Dù có bị phản đối, tôi vẫn muốn đi du học）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な thì thêm thẳng <b>でも</b>：<span class='gd-jp'>下手でも</span>, không phải 「下手くても」.<br>・<span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よくても</span>, không phải 「いくても」.<br>・Động từ nhất định phải chia sang thể て trước：<span class='gd-jp'>読んでも</span>, không phải 「読むでも」.<br>・Kết quả phía sau phải <b>trái với</b> điều người ta thường mong đợi thì mới dùng ても. Uống thuốc thì hạ sốt là kết quả đương nhiên, nên không thể nói 「薬を飲んでも、熱が下がった」, mà phải nói <span class='gd-jp'>薬を飲んだら、熱が下がった。</span>（Uống thuốc xong thì hết sốt）; còn nếu dùng ても thì sẽ là <span class='gd-jp'>薬を飲んでも、熱が下がらない。</span>（Uống thuốc rồi mà vẫn không hạ sốt）</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là chuyện ra ngoài khi trời mưa, đổi mẫu ngữ pháp là nghĩa khác ngay:<br><b>たら</b>＝nếu ～ thì (điều kiện xảy ra thì kết quả theo sau)：<span class='gd-jp'>雨が降ったら、行かない。</span>（Nếu trời mưa thì không đi）<br><b>ても</b>＝dù ～ cũng (điều kiện không thay đổi được kết quả)：<span class='gd-jp'>雨が降っても、行く。</span>（Dù trời mưa cũng đi）<br><b>のに</b>＝rõ ràng ～ mà lại (sự thật đã xảy ra, mang cảm giác bất ngờ hoặc không hài lòng kiểu \"sao lại thế\")：<span class='gd-jp'>雨が降っているのに、傘を持たないで出かけた。</span>（Rõ ràng trời đang mưa mà lại ra ngoài không mang ô）</div><div class='gd-sec'>ても có thể dùng cho giả định chưa xảy ra, và phía sau còn có thể đi với lời rủ rê hay lời nhờ vả như \"nhé\", \"xin hãy\"：<span class='gd-jp'>雨が降っても、行きましょう。</span>（Dù trời mưa cũng đi nhé）. のに nói về chuyện đã xảy ra, phía sau không đi được với lời rủ rê hay nhờ vả, nên không thể nói 「雨が降っているのに、行きましょう」.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: khi muốn nói \"nếu ～ thì\" dùng たら, \"dù/bất kể ～ đều\" dùng ても, \"rõ ràng ～ mà lại\" dùng のに.</div>","n3-78":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜っけ」dùng khi bạn <b>vốn biết, nhưng giờ nhất thời không nhớ ra</b>. Giống như trong tiếng Việt bạn vừa nghĩ vừa hỏi: \"Ơ, mai họp mấy giờ nhỉ? Mình quên mất rồi\", \"Sinh nhật anh ấy là tuần sau phải không nhỉ?\".</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Không nhớ ra</span>Hỏi người khác, hoặc tự lẩm bẩm một mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のミーティングは何時からだっけ？</span>（Cuộc họp ngày mai mấy giờ bắt đầu nhỉ? Mình quên mất rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵どこに置いたっけ？</span>（Ơ, mình để chìa khóa ở đâu rồi nhỉ?）</div><div class='gd-sec'><span class='gd-tag'>Xác nhận trí nhớ</span>Trong đầu bạn đã có sẵn một đáp án, chỉ muốn chắc là mình không nhớ nhầm.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の誕生日は来週だっけ？</span>（Sinh nhật anh ấy là tuần sau, đúng không nhỉ?）</div><div class='gd-sec'><span class='gd-tag'>Hoài niệm chuyện cũ</span>Tự nói với chính mình về chuyện đã qua. Cuối câu không lên giọng, mang cảm giác \"hồi đó nhỉ……\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、よくこの公園で遊んだっけ。</span>（Hồi nhỏ mình hay chơi ở công viên này nhỉ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ, tính từ な</b>: thêm 「だ」 hoặc 「だった」 trước, rồi thêm っけ.<br><span class='gd-pair'><span class='gd-jp'>明日</span> → <span class='gd-jp'>明日だっけ</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだったっけ</span></span></div><div class='gd-sec'><b>Động từ</b>: khi hỏi chuyện đã xảy ra, dùng thể た rồi thêm っけ.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったっけ</span></span><br>Khi hỏi chuyện chưa xảy ra, nói 「〜んだっけ」 thường tự nhiên hơn.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るんだっけ</span></span>（Anh ấy sẽ đến, đúng không nhỉ?）</div><div class='gd-sec'><b>Tính từ い</b>: đổi い thành かった, rồi thêm っけ.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったっけ</span></span>（Quán đó đắt à? Mình quên mất rồi）</div><div class='gd-sec'><b>Muốn nói lịch sự hơn</b>: dùng 「でしたっけ」「ましたっけ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、お名前は何でしたっけ？</span>（Xin lỗi, tên anh/chị là gì ạ…… tôi nhất thời không nhớ ra）</div><div class='gd-ex-line'>・<span class='gd-jp'>前に言いましたっけ？</span>（Trước đây tôi đã nói với anh/chị chưa nhỉ?）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ không được thêm っけ trực tiếp: nói <span class='gd-jp'>明日っけ</span> là sai, phải nói <span class='gd-jp'>明日だっけ</span>.<br>・Điều kiện để dùng っけ là bạn <b>đã từng biết</b> điều đó. Lần đầu hỏi đường người lạ thì không thể nói <span class='gd-jp'>駅はどこだっけ？</span>, mà phải nói <span class='gd-jp'>駅はどこですか。</span><br>・Chuyện ngày mai vẫn có thể dùng thể quá khứ: <span class='gd-jp'>明日の会議、何時からだったっけ？</span> 「た」 ở đây không có nghĩa là cuộc họp đã kết thúc, mà chỉ \"chuyện bạn đã nghe trước đây\".<br>・「だっけ」 là kiểu nói với bạn bè. Với cấp trên, khách hàng thì đổi sang 「でしたっけ」「ましたっけ」, ở công sở nghe rất thường xuyên; nhưng khi phỏng vấn hay viết thư trang trọng thì đừng dùng.<br>・Chữ 「っ」 nhỏ phải ngắt một nhịp: <span class='gd-jp'>だっけ</span> đọc là dakke. Nếu thiếu nhịp đó và đọc thành <span class='gd-jp'>だけ</span> thì nghĩa sẽ thành \"chỉ\".</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là hỏi bạn \"mai họp mấy giờ\":<br><span class='gd-jp'>明日の会議、何時から？</span>: cách hỏi thông thường, vì bạn vốn không biết.<br><span class='gd-jp'>明日の会議、何時からだっけ？</span>: bạn đã nghe rồi nhưng quên mất.<br><span class='gd-jp'>明日の会議、何時からかな。</span>: tự nghĩ trong đầu, không nhất thiết cần người kia trả lời.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: \"trước biết, giờ quên\" thì dùng っけ; \"vốn không biết\" thì dùng câu hỏi thông thường.</div>","n3-79":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜反面」giống như tiếng Việt nói <b>\"có mặt tốt cũng có mặt xấu\", \"hai mặt của một vấn đề\"</b>. Với cùng một sự việc, bạn nói một mặt của nó trước, rồi nói <b>mặt đối lập còn lại</b>. Ví dụ \"công việc này lương khá, nhưng bận lắm\": kiểu \"cùng một việc, hai mặt trái ngược nhau\" thì dùng 反面.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Một tốt một xấu</span>Cách dùng phổ biến nhất: cùng một người, cùng một thứ, vừa có ưu điểm vừa có khuyết điểm.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は給料がいい反面、休みが少ない。</span>（Công việc này lương tốt, nhưng ít ngày nghỉ）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしは自由な反面、寂しいこともある。</span>（Sống một mình thì tự do, nhưng đôi khi cũng cô đơn）</div><div class='gd-sec'><span class='gd-tag'>Tâm trạng mâu thuẫn</span>Trong lòng cùng lúc có hai cảm giác trái ngược nhau, cũng rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>卒業はうれしい反面、少し寂しい。</span>（Tốt nghiệp thì vui, nhưng cũng hơi lưu luyến）</div><div class='gd-sec'><span class='gd-tag'>Đặt đầu câu</span>Sau khi nói xong câu trước, câu tiếp theo mở đầu bằng 「その反面」, nghĩa là \"nhưng mặt khác\".</div><div class='gd-ex-line'>・<span class='gd-jp'>スマホは便利だ。その反面、使いすぎると目が疲れる。</span>（Điện thoại thông minh rất tiện. Nhưng mặt khác, dùng quá nhiều thì mắt sẽ mỏi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp, thể quá khứ cũng được.<br><span class='gd-pair'><span class='gd-jp'>便利になった</span> → <span class='gd-jp'>便利になった反面</span></span><br><b>Tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>速い</span> → <span class='gd-jp'>速い反面</span></span><br><b>Tính từ な</b>: phải thêm 「な」, hoặc dùng 「である」 trang trọng hơn.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な反面</span>／<span class='gd-jp'>便利である反面</span></span><br><b>Danh từ</b>: thêm 「である」.<br><span class='gd-pair'><span class='gd-jp'>有名人</span> → <span class='gd-jp'>有名人である反面</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は有名人である反面、自由な時間が少ない。</span>（Cô ấy là người nổi tiếng, nhưng đổi lại có ít thời gian tự do）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な không được nối trực tiếp: hãy nói <span class='gd-jp'>便利な反面</span>, đừng nói 「便利反面」 hay 「便利だ反面」.<br>・Danh từ phải dùng <span class='gd-jp'>である</span>, đừng nói 「学生な反面」.<br>・反面 nói về hai mặt của <b>cùng một đối tượng</b>. Nếu đem hai người khác nhau ra so sánh, ví dụ \"anh trai cao, em trai thấp\", thì dùng 反面 sẽ nghe lạ.<br>・反面 thiên về văn viết, khá trang trọng, rất hay gặp trong bài văn, tin tức, báo cáo. Khi trò chuyện với bạn bè thì thường dùng <span class='gd-jp'>けど</span> là đủ: <span class='gd-jp'>給料はいいけど、忙しい。</span>（Lương thì tốt đấy, nhưng bận lắm）<br>・Cách đọc là <b>はんめん</b>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>反面</b> = hai mặt của <b>cùng một</b> đối tượng: <span class='gd-jp'>兄は優しい反面、気が弱い。</span>（Anh trai hiền lành, nhưng mặt khác tính cách lại yếu đuối）<br><b>一方で</b> = có thể nói hai mặt của cùng một đối tượng, <b>cũng có thể</b> đem hai đối tượng khác nhau ra đối chiếu: <span class='gd-jp'>兄はスポーツが好きな一方で、弟は本が好きだ。</span>（Anh trai thích thể thao, còn em trai thì thích đọc sách）<br><b>に対して</b> = chuyên dùng để đối chiếu <b>hai đối tượng khác nhau</b>: <span class='gd-jp'>兄は背が高いのに対して、弟は低い。</span>（Anh trai cao, còn em trai thì thấp）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: chỉ có một nhân vật chính, nói về mặt tốt và mặt xấu của nó thì dùng 反面; có hai nhân vật chính, đem ra so với nhau thì dùng 一方で hoặc に対して.<br>Ngoài ra, <span class='gd-jp'>一方だ</span> đặt ở cuối câu có nghĩa là \"ngày càng ～\", khác hẳn với 「一方で」 đang nói ở đây, đừng nhầm lẫn.</div>","n3-76":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả ba mẫu này đều giống kiểu nói <b>「～đến không chịu nổi」「～chết đi được」「～muốn phát điên」</b> trong tiếng Việt. Nóng không chịu nổi, nhớ nhà chết đi được, lo muốn chết: khi cảm giác mạnh đến mức bạn không kìm nén được thì dùng mẫu này. Ba mẫu nghĩa gần giống nhau, khác ở sắc thái và hoàn cảnh dùng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cảm giác cơ thể</span>Nóng, lạnh, đau, buồn ngủ, đói, ngứa.</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹が空いてたまらない。</span>（Đói đến không chịu nổi）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くてしかたがない。</span>（Chân đau chết đi được）</div><div class='gd-sec'><span class='gd-tag'>Tâm trạng</span>Vui, buồn, cô đơn, lo lắng, để tâm.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の結果が心配でならない。</span>（Lo kết quả thi muốn chết）</div><div class='gd-sec'><span class='gd-tag'>Rất muốn làm</span>Đặt「〜たい」ở phía trước, nghĩa là「muốn ～ đến mức không chịu nổi」.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族に会いたくてたまらない。</span>（Nhớ gia đình, muốn gặp đến không chịu nổi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Điểm mấu chốt là từ đứng trước phải chuyển sang dạng「て」, và ba loại từ biến đổi khác nhau:<br><b>Động từ</b>: dùng thể て　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になって</span>しかたがない</span><br><b>Tính từ đuôi い</b>: đổi「い」ở cuối thành「くて」　<span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑くて</span>たまらない</span><br><b>Tính từ đuôi な</b>: thêm「で」trực tiếp　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配で</span>ならない</span><br>「〜たい」biến đổi giống tính từ đuôi い: <span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくて</span></span></div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là「buồn ngủ chết đi được」:<br>・<span class='gd-jp'>眠くてたまらない。</span>（Trực tiếp nhất, cảm giác rõ nhất, hay dùng khi nói chuyện）<br>・<span class='gd-jp'>眠くてしかたがない。</span>（Buồn ngủ liên tục, làm gì cũng không dứt được. Khi nói thường biến thành <span class='gd-jp'>眠くてしょうがない</span>）<br>・<span class='gd-jp'>眠くてならない。</span>（Nghĩa giống nhau, nhưng trang trọng hơn, thiên về văn viết, ít dùng khi trò chuyện hằng ngày）</div><div class='gd-sec'><b>ならない</b>có một cách kết hợp đặc biệt hay gặp:「<b>cứ cảm thấy ～, không gạt ý nghĩ đó đi được</b>」. Trường hợp này hay dùng ならない nhất, còn たまらない rất ít khi dùng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>何か忘れているような気がしてならない。</span>（Cứ có cảm giác hình như mình quên mất điều gì đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話は嘘のように思えてならない。</span>（Nghĩ thế nào cũng thấy anh ấy đang nói dối）</div><div class='gd-warn'>Mẹo nhỏ: nói với bạn bè kiểu「～chết đi được」thì dùng たまらない hoặc しょうがない là chuẩn; viết văn hoặc nói「cứ cảm thấy ～」thì dùng ならない.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ đuôi い đừng nối thẳng với て: đúng là <span class='gd-jp'>暑くてたまらない</span>, không phải 暑いてたまらない. Tính từ đuôi な là <span class='gd-jp'>心配で</span>, không phải 心配て。<br>・Mẫu này nói về cảm giác của <b>chính mình</b>. Nói về người khác thì phải thêm <span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>: <span class='gd-jp'>弟は寂しくてたまらないようだ。</span>（Em trai có vẻ cô đơn lắm）<br>・Chỉ đi với cảm giác, cảm xúc, không dùng để miêu tả thuần túy: 「căn phòng này rộng kinh khủng」không thể nói 広くてたまらない, phải dùng cách nói như <span class='gd-jp'>すごく広い</span>.<br>・<span class='gd-jp'>てならない</span> không giống <span class='gd-jp'>てはならない</span>! Thêm một chữ「は」ở giữa, nghĩa đổi thành「không được ～」: <span class='gd-jp'>ここに入ってはならない。</span>（Không được vào đây）<br>・<span class='gd-jp'>しかたがない</span> đứng một mình có nghĩa là「hết cách rồi」: <span class='gd-jp'>雨だから、しかたがない。</span>（Trời mưa rồi, đành chịu thôi）. Chỉ khi đứng sau thể て mới có nghĩa「～ không chịu nổi」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>たまらない</span> đứng một mình thường có nghĩa「tuyệt đến mức không chịu nổi」: <span class='gd-jp'>仕事の後のビール、たまらない！</span>（Tan làm làm ly bia, sướng không chịu được!）</div>","n3-77":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜どおりに／〜とおりに」giống kiểu nói <b>「theo ～」「giống như ～」</b> trong tiếng Việt. Nấu ăn theo công thức, đi theo kế hoạch, viết theo lời thầy nói đều dùng được mẫu này. Chữ Hán viết là「通り」, bạn có thể hình dung mẫu đã vẽ sẵn con đường, và bạn chỉ cần đi dọc theo đó.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm theo</span>Trong tay có một mẫu, ví dụ công thức, sách hướng dẫn, kế hoạch, lời người khác nói, và bạn làm theo nó.</div><div class='gd-ex-line'>・<span class='gd-jp'>説明書どおりに組み立てた。</span>（Đã lắp xong theo sách hướng dẫn）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生が言ったとおりに書いてください。</span>（Hãy viết theo lời thầy đã nói）</div><div class='gd-sec'><span class='gd-tag'>Đúng như dự đoán</span>Kết quả giống với điều đã nghĩ, đã dự đoán, hơi giống「quả nhiên」trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>予想どおり、試験は難しかった。</span>（Đúng như dự đoán, bài thi rất khó）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったとおり、彼は来なかった。</span>（Quả nhiên đúng như mình nghĩ, anh ấy không đến）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Điểm mấu chốt là <b>phía trước là danh từ hay động từ</b>, vì cách đọc sẽ khác nhau:<br><b>Danh từ nối trực tiếp</b>: đọc là <b>どおり</b> (có dấu đục)<br><span class='gd-pair'><span class='gd-jp'>計画</span> → <span class='gd-jp'>計画どおり</span></span><span class='gd-pair'><span class='gd-jp'>予定</span> → <span class='gd-jp'>予定どおり</span></span><br><b>Danh từ thêm「の」ở giữa</b>: đọc là <b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>説明書</span> → <span class='gd-jp'>説明書のとおり</span></span><br><b>Động từ</b>: dùng thể từ điển hoặc thể た, đọc là <b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うとおり</span></span><span class='gd-pair'><span class='gd-jp'>教わった</span> → <span class='gd-jp'>教わったとおり</span></span><br>Ngoài ra, <span class='gd-jp'>そのとおりです</span>（đúng vậy, bạn nói đúng rồi）là câu đồng tình rất hay dùng khi đối phương nói đúng.</div><div class='gd-sec'>Phía sau thì tùy vào thứ đi kèm:<br>Đi với hành động thì dùng「に」, khi nói thường lược bỏ: <span class='gd-jp'>計画どおり進んでいる。</span>（Đang tiến hành đúng kế hoạch）<br>Đi với danh từ thì dùng「の」: <span class='gd-jp'>予想どおりの結果だった。</span>（Là kết quả đúng như dự đoán）<br>Đặt cuối câu thì dùng「だ／です」: <span class='gd-jp'>結果は期待どおりだった。</span>（Kết quả đúng như mong đợi）</div><div class='gd-h'>Chọn thể từ điển hay thể た</div><div class='gd-sec'><span class='gd-tag'>Thể た</span>Mẫu <b>đã xảy ra rồi</b>, như đã được dạy, đã được nói, đã được xem. Hay dùng nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>見たとおりに話してください。</span>（Hãy kể đúng như bạn đã thấy）</div><div class='gd-sec'><span class='gd-tag'>Thể từ điển</span>Mẫu <b>đang diễn ra</b>, hoặc nói chung về việc「nghe theo lời ai đó」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私が言うとおりに書いてください。</span>（Hãy viết theo những gì tôi（đang）đọc）</div><div class='gd-ex-line'>・<span class='gd-jp'>親の言うとおりにする。</span>（Làm theo lời bố mẹ）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ nối <b>trực tiếp</b> thì mới đọc どおり, có の ở giữa thì thành とおり: <span class='gd-jp'>説明書のとおり</span> mới đúng, không phải 説明書のどおり; <span class='gd-jp'>計画どおり</span> mới đúng, không phải 計画とおり。<br>・Sau động từ đọc là <b>とおり</b>, đừng viết thành どおり có dấu đục.<br>・Đừng nghĩ theo kiểu「làm gì đó + を」: trong tiếng Nhật phía trước <b>không thêm を</b>, 計画をどおりに là sai.<br>・Phía sau nối danh từ thì nhất định phải có の: <span class='gd-jp'>予想どおりの結果</span>, không thể nói 予想どおり結果。<br>・Khi thấy tên đường như <span class='gd-jp'>銀座通り</span> ở Nhật, 「通り」 ở đó có nghĩa là「con phố」, không liên quan đến mẫu ngữ pháp này.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>どおりに</b> = cách làm <b>y hệt</b> mẫu: <span class='gd-jp'>マニュアルどおりに対応した。</span>（Xử lý hoàn toàn theo sổ tay）<br><b>に基づいて</b> = lấy nó làm <b>căn cứ, nền tảng</b>: <span class='gd-jp'>マニュアルに基づいて対応した。</span>（Xử lý dựa trên sổ tay）<br>Ngoài ra,「kết quả giống như dự đoán」chỉ dùng được どおり, như <span class='gd-jp'>予想どおり</span>, không thể thay bằng に基づいて.</div><div class='gd-warn'>Mẹo nhỏ: làm theo, làm y hệt, hoặc「quả nhiên đúng như nghĩ」thì dùng どおり／とおり; chỉ lấy làm căn cứ, làm nền tảng thì dùng に基づいて.</div>","n3-74":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たことがある」tương đương với <b>“đã từng ～”</b> hoặc <b>“có kinh nghiệm ～”</b> trong tiếng Việt. Trọng tâm không phải là ngày nào bạn làm gì, mà là trong cuộc đời bạn <b>có trải nghiệm này hay chưa</b>. Giống như khi bạn bè hỏi “Bạn đã từng ăn mắm tôm chưa?”, đó chính là đang hỏi về điều này.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山に登ったことがある。</span>（Tôi đã từng leo núi Phú Sĩ）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の温泉に入ったことがありますか。</span>（Bạn đã từng tắm onsen Nhật Bản chưa?）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><b>Thể た</b> của động từ（tức là cách nói quá khứ「〜た」）＋<span class='gd-jp'>ことがある</span>。<br>Muốn nói lịch sự thì dùng <span class='gd-jp'>ことがあります</span>; nếu chưa có trải nghiệm thì đổi ある thành <span class='gd-jp'>ない</span>：<br><span class='gd-pair'><span class='gd-jp'>食べたことがある</span> → <span class='gd-jp'>食べたことがない</span></span>（chưa từng ăn）</div><div class='gd-h'>Cách biến đổi: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'>Thể た thực ra chỉ là đổi 「て」 của thể て thành 「た」, nên biết thể て là biết luôn thể た.<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: nhìn âm cuối.<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>Đặc biệt chú ý：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>, chứ không phải 行いた。</div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」 rồi thêm 「た」。<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Hỏi về kinh nghiệm</span>Rất tiện để tìm chủ đề khi trò chuyện. Khi trả lời không cần lặp lại cả câu, chỉ cần nói「あります／ありません」là được.</div><div class='gd-ex-line'>・<span class='gd-jp'>沖縄に行ったことがありますか。</span>（Bạn đã từng đến Okinawa chưa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>（Rồi, tôi đã từng đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、一度もありません。</span>（Chưa, tôi chưa đi lần nào）</div><div class='gd-sec'><span class='gd-tag'>Thêm số lần</span>Thường đi cùng <span class='gd-jp'>一度</span>、<span class='gd-jp'>何度も</span>、<span class='gd-jp'>一度も〜ない</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には何度も行ったことがある。</span>（Quán đó tôi đã đi nhiều lần rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆は一度も食べたことがない。</span>（Natto thì tôi chưa ăn lần nào）</div><div class='gd-sec'><span class='gd-tag'>Trạng thái trước đây</span>Dùng <span class='gd-jp'>〜ていたことがある</span>, nghĩa là “trước đây có một khoảng thời gian từng ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、大阪に住んでいたことがある。</span>（Hồi nhỏ tôi đã từng sống ở Osaka）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>“Đã … rồi” trong tiếng Việt không phải lúc nào cũng là mẫu này</b>. Câu “Hôm qua tôi đã đi siêu thị rồi” chỉ kể việc làm hôm qua, tiếng Nhật chỉ cần nói <span class='gd-jp'>昨日スーパーに行きました</span>, không được nói 昨日スーパーに行ったことがあります。<br>・<b>Việc vừa mới xảy ra, gần đây thì không dùng được</b>：những mốc thời gian rõ ràng và gần như <span class='gd-jp'>さっき</span>、<span class='gd-jp'>昨日</span>、<span class='gd-jp'>先週</span> không hợp với “trải nghiệm đời người”. Còn một khoảng thời gian dài như <span class='gd-jp'>子どものころ</span> thì không vấn đề gì.<br>・<b>Việc ngày nào cũng làm, quá đỗi hiển nhiên thì nghe cũng lạ</b>: nếu bạn nói “tôi từng ăn cơm trắng”, “tôi từng đi xe buýt”, người Nhật sẽ nghĩ: chuyện này có gì đáng nói đâu? Chỉ dùng cho những trải nghiệm khá đặc biệt, không phải ai cũng có.<br>・Phía trước nhất định phải là <b>thể た</b>. Nếu viết <span class='gd-jp'>行くことがある</span> thì nghĩa thay đổi hoàn toàn (xem bên dưới).</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'>Cùng là「ことがある」, nhưng dạng đứng trước khác nhau thì nghĩa hoàn toàn khác:<br><b>Thể た＋ことがある</b>＝<b>đã từng</b> làm (kinh nghiệm trong quá khứ)<br><b>Thể từ điển＋ことがある</b>＝<b>đôi khi có</b> (việc thỉnh thoảng xảy ra)</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行ったことがある。</span>（Tôi đã từng đi xem phim một mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行くことがある。</span>（Đôi khi tôi đi xem phim một mình）</div><div class='gd-sec'>Câu đầu chỉ nói “đã có từ một lần trở lên”, hiện tại chưa chắc còn làm; câu sau nói hiện tại thỉnh thoảng vẫn làm như vậy.</div><div class='gd-warn'>Mẹo nhận biết: thấy「た」ở phía trước thì dịch là “đã từng ～”, thấy thể từ điển thì dịch là “đôi khi ～”.</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>Cũng bắt đầu bằng thể た còn có <span class='gd-jp'>〜たばかり</span>（vừa mới ～）, nói về việc vừa xảy ra không lâu, vừa hay ngược với “kinh nghiệm”, nên có thể nhớ cùng nhau.</div>","n3-75":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことができる」tương đương với <b>“có thể ～”</b>, <b>“biết ～”</b> trong tiếng Việt. Nghĩa gần giống thể khả năng (như <span class='gd-jp'>話せる</span>、<span class='gd-jp'>行ける</span>), chỉ là cách nói đầy đủ và trang trọng hơn. Bạn sẽ hay gặp trong thông báo, hướng dẫn, phỏng vấn và những dịp trang trọng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Biết làm (năng lực)</span>Đã học qua, có khả năng làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はピアノを弾くことができる。</span>（Anh ấy biết chơi piano）</div><div class='gd-sec'><span class='gd-tag'>Được phép, làm được</span>Theo quy định thì được làm, hoặc điều kiện cho phép làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ることができます。</span>（Ở đây có thể chụp ảnh）</div><div class='gd-ex-line'>・<span class='gd-jp'>この展示は予約なしで入場することができます。</span>（Triển lãm này không cần đặt trước vẫn có thể vào）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ dùng thể từ điển（dạng gốc bạn tra thấy trong từ điển）, phía sau thêm thẳng「ことができる」. Tin vui là <b>không cần quan tâm động từ thuộc nhóm nào</b>, cứ ghép vào là xong.<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話すことができる</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができる</span>（くる）</span></div><div class='gd-sec'>Muốn nói “không thể” hay “đã làm được”, chỉ cần đổi 「できる」 ở cuối:<br><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できない</span>（không thể）</span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できた</span>（đã làm được）</span></div><div class='gd-sec'><b>Danh từ cũng có một cách nói</b>: danh từ chỉ “hoạt động” như ngôn ngữ, thể thao, kỹ năng có thể nối trực tiếp với「ができる」：<span class='gd-jp'>日本語ができる</span>（biết tiếng Nhật）、<span class='gd-jp'>テニスができる</span>（biết chơi tennis）.<br>Danh từ chỉ đồ vật thông thường thì không được. Ví dụ “biết lái xe” phải nói <span class='gd-jp'>車の運転ができる</span> hoặc <span class='gd-jp'>車を運転することができる</span>, không được nói <span class='gd-jp'>車ができる</span>。<span class='gd-jp'>本ができる</span> nghĩa là “cuốn sách đã làm xong”, không phải “biết đọc sách”.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ことができます</span>Cửa hàng, thông báo cho bạn biết có thể làm gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>カードで払うことができます。</span>（Có thể thanh toán bằng thẻ）</div><div class='gd-sec'><span class='gd-tag'>ことはできません</span>Quy định không cho phép. Khi phủ định,「が」thường đổi thành「は」, nghe giống như đang nói “việc này là không được”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここでたばこを吸うことはできません。</span>（Ở đây không được hút thuốc）</div><div class='gd-sec'><span class='gd-tag'>ことができました</span>Cố gắng rồi cuối cùng cũng làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>やっと切符を買うことができました。</span>（Cuối cùng cũng mua được vé rồi）</div><div class='gd-sec'><span class='gd-tag'>ことができるようになった</span>Trước đây không được, bây giờ đã có thể.</div><div class='gd-ex-line'>・<span class='gd-jp'>オンラインで申請することができるようになった。</span>（Bây giờ đã có thể đăng ký trực tuyến）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định phải dùng thể từ điển, không dùng thể ます: phải nói <span class='gd-jp'>行くことができる</span>, không được nói 行きますことができる。<br>・「を」trước động từ không cần đổi：<span class='gd-jp'>日本語を話すことができる</span>。Khi chuyển sang thể khả năng thì「を」mới thường đổi thành「が」：<span class='gd-jp'>日本語が話せる</span>。<br>・Khi nói chuyện với bạn bè, dùng thể khả năng sẽ tự nhiên hơn. Hỏi bạn <span class='gd-jp'>明日来ることができる？</span> nghe sẽ khá cứng, thường sẽ nói <span class='gd-jp'>明日来られる？</span>（Ngày mai bạn đến được không?）。<br>・“Sẽ” trong tiếng Việt không phải lúc nào cũng dịch được thành ことができる. “Ngày mai trời sẽ mưa” là dự đoán, không liên quan đến năng lực, phải nói <span class='gd-jp'>明日は雨が降るでしょう</span>。</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'>「ことができる」và「ことがある」chỉ khác nhau một chữ, nhưng nghĩa khác nhau rất nhiều. So sánh với cùng một việc:<br><b>ことができる</b>＝có thể, biết：<span class='gd-jp'>納豆を食べることができる。</span>（Tôi ăn được natto）<br><b>Thể khả năng</b>＝nghĩa giống nhau, khẩu ngữ hơn：<span class='gd-jp'>納豆が食べられる。</span>（Tôi ăn được natto）<br><b>Thể た＋ことがある</b>＝đã từng làm：<span class='gd-jp'>納豆を食べたことがある。</span>（Tôi đã từng ăn natto）<br><b>Thể từ điển＋ことがある</b>＝đôi khi có làm：<span class='gd-jp'>納豆を食べることがある。</span>（Đôi khi tôi ăn natto）</div><div class='gd-warn'>Mẹo nhận biết: xem cuối câu là「できる」hay「ある」。できる＝làm được hay không; ある＝có hay không (đã từng làm, hoặc đôi khi làm).</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>Thêm「ようになる」phía sau nghĩa là “trở nên có thể ～”：<span class='gd-jp'>日本語で電話することができるようになった。</span>（Tôi đã có thể gọi điện bằng tiếng Nhật rồi）</div>","n3-44":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜わけにはいかない」gần với <b>“đâu thể nào ~ được”</b> trong tiếng Việt. Điểm chính không phải bạn làm không nổi, mà là xét theo lẽ thường, tình nghĩa hay vị trí của mình thì <b>không tiện làm như vậy</b>. Sếp còn đang tăng ca, trong đầu bạn nghĩ “đâu thể về trước được”, đúng là cảm giác này.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Không thể làm</span>Thể từ điển＋わけにはいかない<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るわけにはいかない</span></span>（đâu thể về được）</div><div class='gd-sec'><span class='gd-tag'>Không thể không làm</span>Thể ない＋わけにはいかない, nghĩa sẽ thành <b>nhất định phải làm</b>.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないわけにはいかない</span></span>（đâu thể không đi＝nhất định phải đi）<br>Thể ない là cách nói phủ định “không ~” của động từ, ví dụ <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span>.</div><div class='gd-sec'>Khi nói với người lớn tuổi hoặc khách thì cần lịch sự hơn, bạn đổi いかない thành いきません：<span class='gd-jp'>休むわけにはいきません</span>（tôi không thể nghỉ được）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đâu thể làm</span>Xét về lý do hoặc vị trí của mình thì không tiện làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>車で来たから、お酒を飲むわけにはいかない。</span>（Tôi lái xe đến, đâu thể uống rượu được）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は大事な会議だから、休むわけにはいかない。</span>（Ngày mai có cuộc họp quan trọng, không thể nghỉ được）</div><div class='gd-sec'><span class='gd-tag'>Đâu thể không làm</span>Thật ra không muốn lắm, nhưng tình nghĩa và trách nhiệm đã ở đó rồi, nên đành phải làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>先輩に頼まれたから、手伝わないわけにはいかない。</span>（Anh chị khóa trên nhờ rồi, đâu thể không giúp）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したから、行かないわけにはいかない。</span>（Đã hẹn rồi, không thể không đi）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>わけにもいかない</span>Đổi は thành も, nghĩa thành “<b>cũng</b> không thể ~”, hay dùng khi bạn đang bị kẹt giữa hai bên.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く帰りたいけど、先に帰るわけにもいかない。</span>（Rất muốn về sớm, nhưng cũng ngại không dám về trước）</div><div class='gd-sec'>Khi nói nhanh, đôi khi は bị lược đi thành <span class='gd-jp'>わけにいかない</span>, nghĩa vẫn y như vậy.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không dùng cho việc “không biết làm, không đủ năng lực”. “Tôi không biết bơi” là <span class='gd-jp'>泳げない</span>, không phải 泳ぐわけにはいかない.<br>・Phần đuôi là <b>いかない</b>, không phải いけない. 「わけにはいけない」là sai.<br>・Phía trước là khẳng định hay phủ định thì nghĩa ngược hẳn nhau: <span class='gd-jp'>飲むわけにはいかない</span>＝không thể uống; <span class='gd-jp'>飲まないわけにはいかない</span>＝không thể không uống.<br>・Chỉ đơn giản là “không muốn làm” thì đừng dùng, đó là <span class='gd-jp'>行きたくない</span>. Đằng sau わけにはいかない luôn có một lý do kiểu “theo lẽ thường thì…”.<br>・Thường dùng để nói về hoàn cảnh của <b>chính mình</b>, người nói cảm thấy “mình đâu thể ~”.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về buổi liên hoan công ty, xem khác nhau ở đâu nhé:<br><b>Phủ định của thể khả năng</b>＝không làm được vì điều kiện: <span class='gd-jp'>熱があって、飲み会に行けない。</span>（Bị sốt, không đi được）<br><b>わけにはいかない</b>＝xét về tình nghĩa, vị trí thì không thể: <span class='gd-jp'>部長も来るから、行かないわけにはいかない。</span>（Trưởng phòng cũng đến, đâu thể không đi）<br><b>わけがない</b>＝tôi phán đoán là không thể nào: <span class='gd-jp'>田中さんは忙しいから、来るわけがない。</span>（Anh Tanaka bận như vậy, không thể nào đến được）<br><b>わけではない</b>＝không phải là: <span class='gd-jp'>飲み会が嫌いなわけではない。</span>（Không phải là tôi ghét liên hoan）</div><div class='gd-warn'>Mẹo phán đoán: “không làm được” dùng thể khả năng, “đâu thể ~” là わけにはいかない, “không thể nào” là わけがない, “không phải là” là わけではない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜ざるを得ない」của N2 cũng có nghĩa “buộc phải ~”, giọng cứng hơn và mang tính văn viết hơn: <span class='gd-jp'>行かざるを得ない。</span>（Buộc phải đi）</div>","n3-61":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜べきだ」gần với <b>“đáng lẽ phải ~”, “đã là con người thì phải ~”</b> trong tiếng Việt. Nó không phải đoán xem sự việc sẽ ra sao, mà nói về <b>đúng sai, phải trái</b>, tức là bạn thấy làm như vậy mới đúng. Như câu “vay tiền thì phải trả”, tiếng Nhật là <span class='gd-jp'>借りたお金は返すべきだ。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ thể từ điển＋べきだ</b><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るべきだ</span></span>（nên tuân thủ）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝るべきだ</span></span>（nên xin lỗi）</div><div class='gd-sec'><b>Nói “không nên”</b>: vẫn dùng thể từ điển, đổi 「だ」thành「ではない」.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うべきではない</span></span>（không nên nói）</div><div class='gd-sec'><b>する hơi đặc biệt</b>: <span class='gd-jp'>するべき</span> và <span class='gd-jp'>すべき</span> đều đúng. Trong văn viết, báo chí hay gặp <span class='gd-jp'>すべき</span> hơn, còn khi nói thì nghe được cả hai.<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認すべきだ</span></span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: thêm「であるべきだ」phía sau.<br><span class='gd-pair'><span class='gd-jp'>公平</span> → <span class='gd-jp'>公平であるべきだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は公平であるべきだ。</span>（Thầy cô phải công bằng）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>べきだ／べきです</span>Nói ra việc bạn thấy “nên làm”.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束は守るべきだ。</span>（Đã hứa thì phải giữ lời）</div><div class='gd-ex-line'>・<span class='gd-jp'>若いうちに、いろいろな経験をするべきです。</span>（Khi còn trẻ nên trải nghiệm thật nhiều thứ）</div><div class='gd-sec'><span class='gd-tag'>べきではない</span>Việc bạn thấy “không nên làm”.</div><div class='gd-ex-line'>・<span class='gd-jp'>人の悪口を言うべきではない。</span>（Không nên nói xấu người khác）</div><div class='gd-sec'><span class='gd-tag'>べきだった</span>Nhìn lại với chút hối tiếc: lúc đó đáng lẽ phải làm mà đã không làm. Ngược lại, <span class='gd-jp'>べきではなかった</span> nghĩa là “lúc đó đáng lẽ không nên làm”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あのとき、ちゃんと謝るべきだった。</span>（Lúc đó đáng lẽ phải xin lỗi tử tế）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなこと、言うべきではなかった。</span>（Câu như thế đáng lẽ không nên nói）</div><div class='gd-sec'><span class='gd-tag'>べき＋danh từ</span>“…cần phải ~”, đặt thẳng trước danh từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>今やるべきことは何だろう。</span>（Việc cần làm bây giờ là gì nhỉ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi phủ định đừng nói「言わないべき」, phải nói <span class='gd-jp'>言うべきではない</span>. Phía trước べき luôn là thể từ điển.<br>・する không biến thành「しべき」, chỉ có <span class='gd-jp'>するべき</span> hoặc <span class='gd-jp'>すべき</span>.<br>・Giọng khá mạnh, mang cảm giác lên lớp kiểu “bạn làm vậy mới đúng”. Nói thẳng「〜べきです」với cấp trên, người lớn tuổi rất dễ nghe như đang dạy đời. Muốn đưa lời khuyên thì dùng <span class='gd-jp'>〜たほうがいいと思います</span>; dù có dùng べき thì ít nhất cũng thêm <span class='gd-jp'>と思います</span> để giọng dịu hơn.<br>・べき là điều <b>chính người nói thấy</b> là nên làm, không phải quy định. Những việc bắt buộc như luật lệ, nội quy trường thì dùng <span class='gd-jp'>〜なければならない</span>: <span class='gd-jp'>日本では、車は左側を走らなければならない。</span>（Ở Nhật, xe cộ phải chạy bên trái）Chỗ này mà thay bằng べき thì nghe như đang nêu ý kiến cá nhân, rất kỳ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>べき vs はず</b>: tiếng Việt cũng có hai kiểu “nên/phải” và “chắc là/hẳn là”, tiếng Nhật tách thành hai cách nói riêng.<br><b>べき</b>＝<b>nên làm, phải làm</b> (phán đoán đúng sai)<br><b>はず</b>＝<b>chắc là, hẳn là</b> (suy đoán)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るべきだ。</span>（Anh Tanaka phải giữ lời hứa: tôi cho rằng anh ấy nên làm vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るはずだ。</span>（Anh Tanaka hẳn sẽ giữ lời: tôi đoán anh ấy sẽ làm vậy）</div><div class='gd-sec'><b>べきではない vs ものではない</b>: cả hai đều có thể dịch là “không nên”. <span class='gd-jp'>ものではない</span> nói về lẽ thường của xã hội, đạo lý ai cũng biết, giống như người lớn dạy trẻ con “đã là người thì đâu được như vậy”; còn <span class='gd-jp'>べきではない</span> giống phán đoán và chủ trương riêng của người nói hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るものではない。</span>（Không được thất hứa: lẽ thường của con người）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るべきではない。</span>（Không nên thất hứa: tôi cho rằng làm vậy là sai）</div><div class='gd-warn'>Mẹo phán đoán: “nên làm／không nên làm” dùng べき, “chắc là／hẳn là” dùng はず; còn khi nói với giọng lẽ thường kiểu “đã là người thì đâu được ~” thì dùng ものではない.</div>"});
